window.__D("text/hemshech-ayin-beis/c000",{"p":[[3601330145,"<h3>בס\"ד. חה\"ש, תער\"ב, לפ\"ק</h3>\n<b>בשעה</b> שהקדימו ישראל נעשה לנשמע ירדו מה\"ש וקשרו להם שני כתרים א' כנגד נעשה וא' כנגד נשמע, ומשמעות הענין הוא דמה שניתנו להם הכתרים הוא מפני שהקדימו נעשה לנשמע, אבל אם היו מקדימים נשמע לנעשה לא היו נותנים השני כתרים לפי שהשמיעה הוא בשביל העשי', וכשאומר אח\"כ א' נגד נעשה כו' משמע שהשני כתרים הן רק משום שאמרו נעשה ונשמע שהרי אינו אומר א' נגד נעשה ונשמע וא' נגד מה שהקדימו נעשה לנשמע ואי' היתרון מה שהקדימו נעשה לנשמע כו'. גם צ\"ל מה שנתינת הכתרים הוא ע\"י המלאכים, והלא לפעמים מצינו במד\"ר קדושים ס\"פ ך\"ד משל למלך שבני המדינה עטרו לו ג' עטרות כו', כך העליונים מכתירים בכל יום להקב\"ה ג' עטרות שהן ג' קדושות נטל א' ונתן בראשו ושנים נתן בראש בניו, הרי דנתינת העטרות הוא מהקב\"ה בעצמו וכאן או' ירדו מה\"ש וקשרו כו', אך גם שם או' העליונים מכתירים כו'. והנה במשנה דאבות אי' ג' כתרים הן כתר תורה וכתר כהונה וכתר מלכות וכתר שם טוב עולה על גביהן הרי שיש ג' כתרים וכאן או' שקשרו להם רק ב' כתרים כו'. גם צ\"ל\nמ\"ש במשנה ג' כתרים הן הרי בפרטות הן ד' כתרים עם כתר ש\"ט ולמה לא חשיב כתר ש\"ט במנין כל הכתרים, ויאמר ד' כתרים הן כו'. וגם מהו הל' שעולה על גביהן כו'. והנה הג' כתרים כתר תורה כו' בד\"כ הן בהג' קוין, דכתר כהונה הוא בקו הימין, וכידוע דכהן הוא בחי' החסד וכמ\"ש ואתה כהן לעולם דקאי על בחי' החסד דאתה הוא בחי' גילוי שזהו ההפרש בין אתה להוא דאתה לנוכח כו', וחסד הוא בחי' גילוי והוא ראשית גילוי המדות שנק' ג\"כ יום כו' וכמ\"ש בסי' בפי' ברוך שאמר כו'. וכתר מל' הוא בקו השמאל דהרי מל' עיקר בנינה הוא מהגבורות להיות דהתהוות בי\"ע וכל ההמשכות והגילוים בבי\"ע הכל הוא ע\"י המל' ע\"כ בנינה היא מהגבו' כו' וכמ\"ש במ\"א, וע\"כ גם הכתר מל' הוא בקו השמאל כו'. וכתר תורה הוא בקו האמצעי וכנודע בהג' דברים תורה ועבודה וגמ\"ח דתורה היא בקו האמצעי כו'. ולהבין כ\"ז צ\"ל תחלה ענין בחי' הכתר בכלל מהו. דהנה אי' בפרד\"ס שעה\"כ ערך כתר וז\"ל יש שפי' מל' המתנה כמו כתר לי זעיר, והכוונה אל תחשוב במקום הזה כלל אמנם המתן עד שיתפשט ואז תוכל להבין\nכן פי' הגאונים (ובזה ג\"כ פי' כתר ל' שתיקה דהיינו המתן לי ודום מלהגיד דבר, וענין השתיקה בזה הוא לפי שזהו למעלה מהידיעה והשגה וע\"ד מ\"ש בס\"י בלום פיך מלדבר ולבך מלהרהר כו'. אמנם ממ\"ש המתן עד שיתפשט כו' מובן דמ\"מ ה\"ז התחלת דבר שיהי' מזה התפשטות וגילוי, והיינו דכתר הוא ל' המתנה, ובהמתנה יש ב' ענינים והוא העיכוב מלעיין ולחשוב בו, וגם ענין התקוה (אז מיא קען עפעס דער ווארטן דערפון) והו\"ע התקוה אל ההתפשטות והגילוי כו', וע\"ש בפרש\"י כתר ל' הוחל שהוא ענין התקוה וכמו דום לה' והתחולל לו כו'). ויש שפי' כתר כמשמעו (היינו כתר ועטרה),"],[3601330146,"והטעם כמו שהכתר ראש לכל לבושי הגוף כן מדה זו ראש לכל האצילות (ונר' הכוונה שזהו ראש לכל האורות מקיפים דאצי' כו' וכמו לבושי הראש שהן ראש ללבושי הגוף, וענין העטרה צ\"ל שזהו למעלה גם מבחי' לבושי הראש כו'). ויש שפי' כתר מל' מכתיר את הצדיק, והכוונה ל' סיבוב לכל האצי' בתוכו כו', ונק' כן לרמוז אל תר\"ך עמודי אור המאירים ממנו ובעצמותו והם כחות נעלמים השופעים אור הנעלם אל הנאצלים התחתונים עכ\"ל. והענין הוא דהנה ידוע דבחי' הכתר בכלל הוא בחי' הרצון וכמו כתר דאצי' הוא בחי' הרצון להאציל עולם האצי' כו'. וכן כתר דברי' הוא הרצון לברוא עולם הברי' כו', והן בחי' הכתרים הפרטים כו', ובחי' א\"ק נק' כתר לגבי כללות ההשתל' שממנו ולמטה וכמ\"ש המ\"ח דא\"ק הוא בחי' אריך דד' עולמות אבי\"ע כו', ועז\"א בזהר כד סליק ברעותי' למברי עלמא דהיינו בחי' רצון ומחה\"ק דא\"ק וכמ\"ש בע\"ח. ובכללות יותר הוא בחי' הרצון הפשוט שבאוא\"ס לפני הצמצום וכמ\"ש בע\"ח כשעלה ברצונו הפשוט להאציל ולברוא כו', דכ\"ז הוא בבחי' כתר בכל מדרי' ומדרי' שכולל בעצמו כל\nמה שעלה בבחי' רצון זה וכשנתהווה מה שנעלם וכלול בהרצון ובא בבחי' גילוי ה\"ה בבחי' סובב ומקיף לכל מה שנתהווה כו', וכמו כתר דאצי' כולל כל הע\"ס דאצי' וכשנאצל האצי' הרי בחי' הכתר סובב ומקיף את האצי' וכידוע דעיגולי אריך סובבים עד בחי' מל' דאצי' כו', וכן בחי' א\"ק הוא בחי' אור כללי שכולל הכל קודם שנתהוו ואחר שנתהוו העולמות ה\"ה בבחי' סובב ומקיף עליהם דעיגולי א\"ק מגיעים עד תחתית העשי' כו', וכ\"ה גם ברצון הפשוט שלפני הצמצום שג\"כ כולל בתחלה הכל ואח\"כ סובב ומקיף שזהו בחי' העיגול הגדול שלפני הקו שסובב ומקיף כל ההשתל' שמהקו כו' וכל העיגולים שרשן הוא מהעיגול הגדול כו' כנודע. וזהו שהכתר בכ\"מ הוא בבחי' ממוצע וכמו כתר דאצי' הוא ממוצע בין המאציל לנאצלים כו', וכן בכל מדרי' הנ\"ל הכתר הוא הממוצע (וכ\"ה גם בעולמות אבי\"ע דמל' דאצי' שנעשה כתר לברי' ה\"ז ממוצע בין אצי' לברי' וכן מברי' ליצי' כו'), והיינו שע\"י התעוררות הרצון כבי' נעשים בבחי' שייכות אל הדבר שנתעורר בו כו'. וכמו עד\"מ באדם למטה דקודם שנתעורר באיזה רצון\nלאיזה דבר ה\"ה מובדל ממנו לגמרי ואין לו שייכות כלל לזה וכאשר נתעורר ברצון ע\"ז ה\"ה בבחי' שייכות כו'. וכנודע דרצון הוא ל' מרוצה והו\"ע ההטי' וההמשכה שנמשך לאיזה דבר כו', וקודם שנתעורר באיזה רצון ה\"ה בבחי' הבדלה בכלל היינו בבחי' עלי' והעלם בעצמו ביותר שהרי אין לו שום התגלות בזה כו', והרצון הוא ההטי' היינו היציאה וההתגלות לדבר שחוץ לעצמו כו'. ובדוגמא כזאת יובן למעלה כבי' דקודם התעוררות הרצון על העולמות הרי האוא\"ס בבחי' הבדלה לגמרי מן העולמות שאינו בבחי' שייכות כלל אל העולמות ואדרבה בבחי' העלם לגמרי בעצמותו שאינו בבחי' גילוי כלל בעצם (גם לא בבחי' גילוי לעצמו כבי' להיות שגם הגילוי לעצמו הוא בבחי' שייכות לאיזה דבר כו', שהרי גם ההתעוררות והגילוי לעצמו ה\"ה באיזה דבר א\"כ ה\"ז בבחי' שייכות להדבר רק שהוא לעצמו עדיין כו', וקודם ההתעוררות הוא שאינו בבחי' גילוי כלל כ\"א אדרבה בבחי' העלם בעצמו לא בבחי' גילוי כלל כו'. והנה יכול להיות גילוים לעצמו שאינם בבחי' שייכות לדבר הזולת כו', וכמו בתענוג שמתענג בהעצם\nשלו כו', אבל אין זה ענין הגילוי באמת, אדרבה הוא בבחי' עלי' ורוממות יותר בהעצמות כו'. וע\"כ תענוג כזה הוא דוקא במי שמרומם בעצם ובזמן תכלית"],[3601330147,"הרוממות שלו וכמו המלך בתכלית הרוממות שלו שמתענג בתענוג פשוט ועצמי לא מאיזה דבר כ\"א בעצם רוממות עצמו כו', דבהתענוג הוא מתרומם יותר בהעצמות שלו בבחי' הבדלה ביותר כו'. ובדוגמא כזו יש ברצון שהוא מרוצה והיינו לא שרוצה באיזה דבר כ\"א מה שהוא מרוצה כו' שזהו בחי' גילוי לעצמו ולא בבחי' שייכות לאיזה דבר כו', אך אין בזה התעוררות עדיין (רק יכול להיות בבחי' סיבה לאיזה התעוררות כו'), אבל כאשר מתעורר באיזה רצון אפי' רק לעצמו ה\"ז בבחי' שייכות להדבר כו', וקודם שנתעורר הוא שאינו בבחי' גילוי כלל גם לא לעצמו כו'). וכאשר עלה ברצונו ית' ה\"ז בחי' המשכה וגילוי אל כללות ההשתל' בכלל או אל איזה עולם בפרט כו', והגם דבחי' הרצון הוא למעלה עדיין מהתהוות כו', וכמו בעליית הרצון דאוא\"ס שלפני הצמצום הרי בכדי שיהי' התהוות העולמות הוצרך להיות הצמצום תחלה שהוא בחי' סילוק האור כו', וכן במדרי' שלאחר הצמצום שיש כמה צמצומים וכמו צמצום א\"ק וצמצום הדיקנא כו'. מ\"מ ה\"ז בבחי' ממוצע שנעשה האור בגדר שייכות אל העולמות שמזה יתהוו העולמות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> יקשה דמשמע שהשני כתרים הם מפני שהקדימו כו' ואח\"כ או' א' כנגד נעשה כו'. ובמד\"ר אי' שהקב\"ה נותן שתי עטרות בראש בניו וכאן או' ירדו מה\"ש וקשרו. ובמשנה דאבות אי' שלשה כתרים הם, ובפרטיות חושב ד' כתרים. הג' כתרים הן בג' קוין. יקדים ענין הכתר בכלל, ג' פירושים בכתר א' ל' המתנה והוא העכבה והתקוה, ב' ל' עטרה, ג' ל' סיבוב. ויבאר שהכתר עד רוהמ\"ע הוא בחי' הרצון שכולל הכל ומקיף וסובב הכל, ולכן כתר בכ\"מ הוא בחי' ממוצע. כי קודם התעוררות הרצון אפי' לעצמו כבי' ה\"ז בבחי' העלם והבדלה לגמרי, והתעוררות הרצון ה\"ז בחי' הטי' והתגלות להיות בבחי' שייכות כו'.</span>\nב) <b>והנה</b> ידוע דהרצון הוא בחי' אור מקיף וכמ\"ש כצנה רצון תעטרנו כו', דבזה מחולק כח הרצון מכל הכחות שכולם באים בבחי' אור פנימי בבחי' אור בכלי כו', וכמו כח השכל במוח שבראש וכח הראי' בעין וכח השמיעה באזן כו', שכל כח יש לו כלי מיוחדת לפי מזגו ותכונתו שלא יתלבש בכלי אחרת, וכמו שכח הראי' לא יתלבש באזן וכח השמיעה בעין וכן השכל מתלבש דוקא במוח שבראש ולא בשאר אברים כו'. והגם שיש התלבשות השכל גם ביד וברגל וכמו בכתיבת האותיות הרי יש בזה שכל וחכמה כו' לבד התלבשות השכל באותיות הכתב שבא ע\"י היד להביא אור השכל בכתב כו' שזהו רק בדרך מעבר בהיד כו' וכמ\"ש במ\"א, הרי בעצם ציור האותיות יש בזה שכל והיא מלאכת הכתיבה שהיא ג\"כ חכ', ובפרט במלאכת הציור שהיא חכמה גדולה כו', ובד\"כ מי שהוא אומן יד אין זה בכח התנועה שביד לבד כ\"א מקורו הוא בשכל שיש לו חוש במלאכת היד בכתיבה וציור או באריגה וריקום וכה\"ג (ועמ\"ש הרמב\"ם בשמונה פרקים פ\"א), וכמו\"כ יש התלבשות השכל ברגל וכמו בריקוד וכה\"ג. הנה התלבשות זאת אינה בהאברים\nדיד ורגל כ\"א בהכחו' שבהם בכח התנועה שביד וכח ההילוך שברגל והו\"ע התלבשות הכחות זב\"ז כו', דלהיותם כחות פנימיים ה\"ה מתלבשים זב\"ז שהכח העליון מתלבש בכח התחתון ומנהיגו כו' (רק שההתלבשות זב\"ז היא דוקא כאשר הכחות מלובשים בכלים כו' וכמ\"ש במ\"א), ומה שמתלבש הוא רק הארה לבד, לא עצם"],[3601330148,"הכח כמו בהאבר הראוי לו כו' וביותר הוא בכח השכל מה שמתלבש בכח התנועה וההילוך שביד וברגל אין זה אמיתית ומהות כח השכל המתלבש במוח שבראש, והיינו שההתלבשות הוא רק שכל המעשי לבד שהוא כח היותר אחרון שבשכל שעם היותו נמצא בכח השכל גם כמו שהוא במוח שבראש, הרי אין זה מהות השכל שבראש כו'. שהרי גם כח השכל המתלבש במדות אין זה עצמות ומהות השכל, דעצמות השכל הוא להשכיל שכליים עמוקים ונעלים שאינם שייכים למדות כלל ובכל ענין בעצם ומהות הענין כמו שהוא למעלה מגדר מדות כו', והמוחין השייכים למדות בכלל דהיינו חיצוניות המוחין ובפרט המוחין שבמדות שהוא הבכן אין זה עצם ומהות השכל כו' וכמ\"ש במ\"א, וכ\"ש השכל שבכח התנועה וההילוך שאין זה מהות השכל כו'. משא\"כ במוח שבראש הרי השכל מתלבש בחומר המוח ממש ומתלבש בו מהות ועצמות השכל להשכיל כל דבר שכל וחכ' כו', והיינו להיותו כלי הראוי לאור השכל ה\"ה מתלבש ומתגלה בו ומתאחד בו כו'. וזהו הסיבה מה שהאברים פועלים בהכחות שבאים בהגשמה כפי מהות האברים, וכמו שהשכל ישכיל השכלה גשמיות ובכח\nהראי' יראה דבר גשמי כו' שאין זה מהכחות מצ\"ע, דהרי השכל שבנשמה מצ\"ע הוא רק להשכיל בענינים רוחניים ואין לו שייכות כלל להשכלה גשמיות וכשמתלבש בחומר המוח ה\"ה משכיל השכלה גשמיות כו'. הגם דבהתלבשותו במוח ג\"כ עיקר ענינו של השכל דנשמה ועיקר הכוונה בירידתו והתלבשותו הוא להשכיל בעניני אלקות (עם היות שבאמת בכל השכלה גשמיות ובכל ענין גשמי יש בזה מהנשמה האלקית כו' וכמ\"ש בסש\"ב דעיקר החיות דנש\"י הוא מהנשמה האלקית דוקא וע\"כ בכל דבר יש בזה כחות הנה\"א כו', ולכן נוגע מאד הענינים שעוסקים בהם מפני שבכל דבר ודבר שהאדם פועל ועושה מכניס בזה כחות אלקי' כו'. אמנם עיקרו של השכל האלקי דנה\"א הוא להשכיל בעניני אלקות כו'). אך ג\"ז הוא ע\"י ענינים גשמיים דמה שאנו יודעים באלקות הוא ע\"י הענינים הגשמיים שמהם אנו מבינים באלקות וממילא גם ההשגה האלקית היא באה בהגשמה ואינה מערך ההשגה דהנשמה קודם התלבשותה בגוף כו'. וכ\"ז הוא שחומר האברים פועלים בהכחות, והיינו לפי שהכחות באים בבחי' התלבשות והתאחדות שזהו בבחי' תפיסא שנתפסים\nבהאברים וע\"כ פועלים בהם שבאים בהגשמה כמהות חומר האברים כו'. אמנם האברים בטלים אל הכחות (דאל\"כ לא היו בבחי' כלים להם כו') שהכחות יש להם שליטה וממשלה על האברים ומנהיגים אותם כו', והיינו לפי שהכחות הן בבחי' התגלות בהאברים ע\"כ הם מנהיגים את האברים, וזה גופא הוא מפני שהן כלים הראויים לאור צורת הנפש ע\"כ הכחות מתגלים בהם, וכנודע שיש התלבשות שהמלביש מושל ושולט על המלובש וכמו בגלגולים ר\"ל וכמ\"ש במ\"א, והיינו לפי שהמלביש אינו בבחי' כלי וממילא אין הנפש מתגלה שם כו'. אבל בהתלבשות הנפש בגוף האברים ה\"ה בבחי' כלי והכחות מתגלים בהם וע\"כ הם מושלים ושולטים עליהם להנהיגם כו', ולכן שליטה וממשלה זאת דהכחות על האברים אינו בדרך הכרח שהכחות מכריחים אותם כ\"א מה שפועלים בהם ע\"י התלבשות והתגלות שלהם כו'. ויובן זאת בהתלבשות הכחות זב\"ז כמו כח השכל כשמתלבש בכח התנועה ומנהיגו במלאכת הציור וכה\"ג הרי אין זה בדרך הכרח כ\"א מה שפועל בו להיות כפי חיוב השכל כו'. ואין זה כמו פעולת הרצון שפועל בכל הכחות והאברים שזהו בדרך הכרח להיותו כח נעלה בעצם לכן"],[3601330149,"בהתגלות כח הרצון ה\"ה מכריח התגלות הכחות כו', וכן בהאברים שנשמעים לרצונו הוא שמתבטלים ממילא לפני הרצון כו'. אבל בהכחות פנימיים אינו כן כ\"א מה שפועלים להיות הכח התחתון כפי חיוב כח העליון שזהו בדרך פנימי ע\"י התלבשות והתגלות כו'. וכמו מה שהמוח שליט על הלב הרי אין זה שליטה בדרך הכרח כ\"א שפועל חלישות בהטבע שבלב ומזככו כו', וכמ\"ש בסש\"ב הטעם מפני שהלב מקבל חיות מהמוח ע\"כ המוח שליט כו', והיינו ע\"י שהלב הוא כלי אל המוח ע\"כ המוח שליט על הלב בבחי' או\"פ כו', וכן הוא שליטת הכחות בהאברים כו'. וכמו\"כ הענין ברוחניות בהתלבשות הנה\"א בנה\"ב שהנה\"א מושל ושולט על הנה\"ב אין ענינו בבחי' שליטה בהכרח כ\"א מה שפועל בו התיקון והזיכוך שהנה\"ב יסכים על עניני הנה\"א עד שגם הוא ירצה בעניני האלקית כו' וכמ\"ש במ\"א. וכ\"ז הוא לפי שהאברים המה כלים ראוים לאור צורת הנפש ע\"כ הכחות מתגלים ופועלים בהם כו', ולכן לפי אופן חומר האברים כן הוא התגלות הכחות, וכמו דלפי אופן חומר המוחין הוא התגלות אור השכל שאם מזג המוח יבש וחם ביותר לא יהי'\nמזג השכל טוב ואם הוא מזג קר ולח ביותר ג\"כ לא טוב, אך במזג ממוצע בין קר ולח וחם ויבש לפי אופן טוב המזג במוח הגשמי כך יהי' השראת אור השכל במזג טוב אם בהשכלה בעומק או ברוחב או בהשכלות דקות וצחות וכה\"ג. וכמו\"כ בכח הראי' שבעין לפי אופן חומר העין בשחור ולבן שבו כך יבוא אור הראי' הרוחניות כו', וכנודע דגם ענין טוב עין ורע עין תלוי במזיגת חומר העין הגשמי אם הוא בריבוי דמים או במיעוט דמים כו' וכמ\"ש במ\"א (ובד\"כ לפי אופן מזיגת והרכבת הדם והמים באברי הגוף (שז\"ע אדם א' דם כו') לפי אופן כזה הוא מזיגת הכחות הרוחניים כו', וכמו מי שהוא רגזן בטבע או שהוא שקט ונח בטבעו ה\"ז לפי הרכבת הדם והמים בחומר הגוף כו', ויש שגם בריבוי דמים תהי' מזיגת המים בטוב וכמו אדמוני עם יפה עינים כו'). והגם שהכחות והאברים אינם בערך כלל זל\"ז שהכחות רוחנים המה והאברים גשמים כו', מ\"מ מאחר שמתלבשים בהם וכפי אופן מזגי הכלים הוא מזגי הכחות בהכרח לומר שיש בהגשמת טבעי האברים מעין ודוגמא טבע מהות אור הרוחני דנפש שעי\"ז הם כלים מוכנים לקבל\nבהם צורת הנפש כו', וכמו בהירות העין כלי לאור הראי' וכמו כל דבר מלוטש מקבל אור כו', וכמו\"כ חומר המוח והלחלוחית הדקות שבו יש בו איזה דוגמא מטבע אור השכל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> יתחיל לבאר ההפרש בין הכתר לשארי הספירות, ויבאר המשל בנפש שכל הכחות ובראשם כח השכל הם כחות פנימיים, ולכן מתלבשים דוקא בכלים הראוים להם (ויזכיר בקצרה ענין התלבשות השכל בהכחות שלמטה ממנו). וזהו הסיבה שהאברים עושים הגשמה בהכחות, ולהיפך שהם בטלים אל הכחות והכוחות מנהיגים אותם ובבחי' או\"פ בהתגלות לא בהכרח, והתגלות הכחות הוא כפי מזיגת האברים.</span>\nג) <b>אמנם</b> עיקר הענין בזה הוא לפי שהכחות הם פנימיים בעצם היינו שבאים בהגבלה מן הנפש עד שהן בערך להתלבש בכלים כו' (ומה שבא מהכחות בהתלבשות בהאברים הוא הבחי' האחרונה שבהם שנק' גשם שברוחני, אך להיות שהכחות המה פנימיים בעצם ע\"כ דקות האברים הנק' רוחני שבגשמי הוא"],[3601330150,"בבחי' כלי להלביש ולהתפיס את הגשם שברוחני כו'). והגם דהנפש הוא בלתי מוגבל, מ\"מ הרי הכחות הם בבחי' גבול שהרי הן כחות פרטים כמו כח החכ' כח החסד כו', והן נמצאים כלולים בנפש לא שהן הארה והתפשטות מהנפש עצמו כו', דכל הארה ה\"ה לפי אופן העצם כו', אבל הכחות אינם הארה מעצם הנפש כ\"א מה שהנפש עם היותו בלתי מוגבל בעצם ה\"ה כולל בעצמו כחות שהן בבחי' כחות מוגבלים בעצם כו' (ומ\"מ גם הנפש בעצמו נושא את הכחות ושם הם בבחי' אחדות ממש שהנפש אחת היא גם שנושאה את הכחות בעצמה כו' וכמ\"ש במ\"א, אבל מה שהנפש כוללת בתוכה כחות אין זה עצמות הנפש כו'). אמנם הכחות כמו שהן כלולים בנפש ה\"ה ג\"כ בבחי' בלי גבול ואינם במציאות כחות כלל, וכידוע דכח השכל ההיולי העצמי הכלול בעצם הנפש אינו בבחי' שכלי כלל וכלל כו' וכן בשארי כחות כו', אך הארתן שנמשך להתלבש באברי הגוף ה\"ז בא בבחי' צמצום שהנפש מצמצם א\"ע בכדי להתלבש באברי הגוף להיות בבחי' חיות פנימי כו', ועי\"ז הן באין בהגבלה עד שהן בערך בחי' הרוחניות שבאברים להיות נתפס בהם כו'. וזהו ג\"כ\nהסיבה מה שהאור והחיות פנימי של הנפש בא בבחי' התחלקות באברי הגוף שאינו בשוה בכל האברים, שהרי אינו דומה אור וחיות הנפש כמו שהוא בראש וכמו שהוא בגוף, שעם היות שהראש הוא קטן בכמות לגבי הגוף ומ\"מ הרי עיקר גילוי הנפש הוא בראש דוקא כו', וברגל החיות במיעוט ביותר כו'. וזהו מפני שהגילוי דאור וחיות הנפש הוא לפי אופן הכלים שהחיות בא בבחי' התלבשות ותפיסא לפי מזיגת הכלי כנ\"ל, ע\"כ לפי אופן דקות הכלי הוא גילוי אור הנפש דהראש שהוא במזיגה דהרכבה בבחי' חומר דק דמשו\"ז הוא כלי מוכן יותר לאור וחיות הנפש, ע\"כ מאיר שם אור הנפש בגילוי יותר דהיינו שמאירים שם כל הכחות הנעלים שבנפש כו', ובגוף הוא בבחי' מיעוט האור לגבי הראש שאור הנפש מצומצם שם כו', וברגל שהוא בבחי' חומר עב ביותר ע\"כ גם אור הנפש מצומצם שם ביותר כו'. וכמו\"כ בהתלבשות הכחות זב\"ז שהכח העליון מתלבש בכח התחתון, וכמו השכל שמתלבש במדות וגם בכח התנועה וההילוך כו' כנ\"ל, ה\"ה בא בבחי' התחלקות, וכמשנת\"ל דאור השכל המתלבש במדות הוא בחי' חיצוניות השכל לבד כו', ובכח\nהתנועה מתלבש רק שכל המעשי שאין זה עצמות השכל כלל כו', ועצם ומהות השכל הוא במוח שבראש דוקא כו'. וכן בשארי כחות כמו המדות וכח התנועה גופא שנמצא ביד וגם ברגל הרי אינו בשוה בהם דעיקר כח התנועה לפעול ולעשות דבר הוא ביד ומה שבא ברגל הוא בהילוך לבד כו', והיינו דלפ\"ע הכלים כן מתצמצם אור וחיות הנפש בהם שמתמעט ממדרי' למדרי' כו'. וכ\"ז הוא מפני שזהו התגלות בחי' הפנימי שיש בנפש היינו בחי' הכחות שבו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והעיקר הוא כי הכוחות הם פנימיים היינו מוגבלים בעצם, והנפש שהיא בלתי מוגבלת כוללת בתוכה כחות מוגבלים, רק בהתכללותן בהעצם הן בלתי מוגבלים, והתגלות הארתן הוא ע\"י צמצום הנפש, ולפי אופן האברים הוא הצמצום באור הנפש כו'.</span>\nד) <b>וזהו</b> שהכחות עצמן באים בבחי' הגבלה ובהתחלקות, וכמו כח השכל שאינו בא בבחי' פשיטות ובבחי' בלי גבול כ\"א בהגבלה ובהתחלקות, דכל אור"],[3601330151,"שכל ה\"ה מורגש בהגבלה, ולא כמו הרצון שבא בהתגלות בהתפשטות בלתי מוגבלת, משא\"כ אור השכל שבא בהגבלה, לבד מה שהוא באיזה פרט דבר (שכן הוא גם ברצון כו'), הנה עצם האור והגילוי הוא אור מוגבל כו', שגם אור שכל שבא בהפשטה שאינו נתפס כ\"כ באותיות ה\"ה בבחי' אור מוגבל כו', וזהו ההגבלה בעצם מציאותו כו'. וגם מוגבל בההתפשטות שלו דעד פה תבוא כו', דכל שכל אמיתי יש בו הגבלה כמה יכול להתפשט כו', ומי שהוא חכם גדול שמבין הענין לעומקו יותר יוכל להתפשט בו יותר, מ\"מ הכל הוא בהגבלה כו', והיינו להיותו אור פנימי בעצם ע\"כ בא בהגבלה כו'. וגם בא בבחי' התחלקות שהרי כל ענין שכלי יש בו כמה פרטים, שא\"א להיות ענין שכלי שלא יהיו בו פרטים, ובכל פרט שבו אינו דומה אור השכל המאיר בו והן בבחי' פנימיות וחיצוניות כו', והיינו שבפרט אחד שבו מאיר השכל יותר והוא בחי' הפנימיות והעומק שבו ובפרט אחר אין בו מאור השכל בבחי' פנימיות כ\"כ כו'. וכן במדות שע\"פ השכל יש בהם כמה התחלקות באופן התפשטות אור המדות בכל פרט כו', וכמו האהבה שע\"פ טו\"ד ה\"ה\nבאה בהגבלה ואינו מחייבת ענין המס\"נ לפי שהאהבה היא מוגבלת בזה כו'. וזהו מה שבכוונת המצות יש התחלקות שאין הכוונה בכל המצות בשוה לפי שהטעם והסוד שבכל מצוה אינו בשוה בכולם כו', ומה שארז\"ל אל תהי יושב ושוקל מצותי' של תורה דקלות שבקלות וחמורות שבחמורות כולם שוים, זהו מצד הרצה\"ע שבמצות שהרצון אינו בא בהגבלה והתחלקות וע\"כ כל המצות שוין כו', אבל מצד הטעם והכוונה יש בזה חילוקי מדרי' כו'. ובכללות הוא ההפרש בין תורה למצות שהתורה באה בבחי' התחלקות שכל עניני התורה יש בהם חילוקים בבחי' אור החכ' שבהם כו', וגם בהתענוג שבתורה יש בזה חילוקי מדרי' כו', וזה\"ע שבמ\"ת על כל דבור ודבור פרחה נשמתן דבמ\"ת הי' התגלות בחי' התענוג שבתורה ובכל דבור ודבור יש תענוג פרטי ומיוחד ע\"כ על כדו\"ד כו', וכמ\"ש בלקו\"ת ד\"ה ואהי' אצלו אמון ובד\"ה ראו כי ה' נתן לכם את השבת, והמצות מצד הרצה\"ע שבהם כולם שוין כו'. וכן יש הפרש בהחיוב דעסק התורה לחיוב דקיום המצות, דבחיוב דעסק התורה יש בזה מדרי' דהרי החיוב הוא והגית בו יומם ולילה שיהי' עסק\nהתורה תמיד, אך זהו ליושבי אהל, אבל בעלי עסקים החיוב שלהם הוא פרק א' שחרית ופרק א' ערבית, ומשארז\"ל שיהא תורתך קבע ומלאכתך עראי היינו שיהי' בבחי' קביעות בנפש, דתכלית כוונתו יהי' עסק התורה וגם בעסקו במו\"מ יהי' כוונתו בכדי שישתכר ויוכל לעסוק בתורה ולהדריך בניו בת\"ת ולקיים מצות כו', וזהו בעסק התורה. אבל בקיום המצות הרי כל ישראל שוין שכולם מחוייבים בקיום המצות, משא\"כ בתורה שאין כולם שוין כמו בעלי עסקים כו' כנ\"ל. וגם בזה יש חילוקי מדרי' דגם בע\"ס השייכים לתורה צ\"ל תורתן קבע בקביעות בזמן, ומי שאינו שייך בעצם לעסק התורה דמ\"מ גם הוא מחויב בעסק התורה משום דמצוה דעסק התורה הכל מחוייבים בה כו', רק שיוצאים י\"ח בפ\"א שחרית כו', ובהם הפי' תורתך קבע בבחי' קביעות בנפש כו', וכמ\"ש בהל' ת\"ת פ\"ג, הרי שאינו דומה החיוב בעסק התורה להחיוב בקיום המצות, וכ\"ז הוא בתורה ומצות שהתורה היא מבחי' חכ' שיש בזה מדרי' חילוקים, והמצות הן רצה\"ע שאין בזה התחלקות מדרי' כו'. ובפרטיות הוא במצות עצמן ההפרש בין כוונת המצות לעצם קיום המצות מצד הרצון שבהם כו' כנ\"ל, ולכן בכל מצוה צ\"ל ב' כוונות, הא' בהכוונה פרטיות שבה, והב' בבחי'"],[3601330152,"קבעומ\"ש לקיים רצונו ולעבדו בכל מיני עבודת עבד כו' וכמ\"ש בסש\"ב פמ\"א. וזהו שברוב המצות מסיים בתורה אני הוי' דלכאו' אינו מובן מה\"ע החותם דאני הוי'. אך הענין הוא שזהו ב' הענינים שבמצות, דכוונת המצות זהו כמו שהמצות תלוים בש' הוי' שיש מצות התלוים באות יו\"ד ויש באות ה\"א כו', וענין אני ה' היינו בחי' עצמות אוא\"ס שלמעלה משם הוי' שמתחבר בש' הוי' כו', דמצד בחי' ומדרי' זו לא יש התחלקות מדרי' כלל כו'. וזהו שחותם אני הוי', דעם היות שבתורה יש חילוקי מדרי' והיינו בהסוד וטעם המצות כו', מ\"מ אל תהי יושב ושוקל במצותי' ש\"ת כו', משום דאני הוי' דעצמות אוא\"ס מאיר בש' הוי' והוא בחי' רצה\"ע שלמעלה מחכ' דמצד זה לא יש חילוקי מדרי' כלל כו'. וכללות הענין הוא דהאורות והכחות שבאים בבחי' פנימי ה\"ה בבחי' הגבלה וע\"כ הם בבחי' התחלקות בעצם וכן בהתלבשותן זב\"ז ובהתלבשותן בהכלים כו', וכמו\"כ ברוחניות בתורה וכוונת המצות יש התחלקות וברצון שבמצות לא יש התחלקות, וזהו אני הוי' דמבחי' אני שבהוי' כל המצות שוין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולכן הכחות בעצם הן בהגבלה ובהתחלקות, וזהו שיש חילוקים בכוונת המצות משא\"כ מצד הרצון שבהם, וכ\"ה בתורה ומצות בכלל, ולכן א\"ד חיוב עוסק התורה להחיוב בקיום המצות, ולכן בעשיית המצות צ\"ל ב' כוונות, וזהו שחותם בכל פ' אני הוי' כו'.</span>"],[3601330153,"<h3>בס\"ד. ליל ב' דחה\"ש, תער\"ב</h3>\n<b>עוטה</b> אור כשלמה נוטה שמים כיריעה, וצ\"ל שייכות הענינים דעוטה אור ונוטה שמים זה לזה. ולהבין זה, יש לה\"ק משנת\"ל בהמשל דכחות הנפש שבאים בבחי' פנימי' באברי הגוף שכל כח יש לו כלי מיוחדת שהכח מתלבש ומתגלה ומתאחד בו, וע\"כ לפי אופן האברים הוא פעולת והתגלות הכחות כו'.\nה) <b>והדוגמא</b> מכ\"ז יובן למעלה בבחי' ציור אדה\"ע דהגם שאין לו דמות הגוף ולא גוף כו', מ\"מ הרי כתיב ועל דמות הכסא דמות כמראה אדם עליו כו' שאין זה בבחי' עצמות אוא\"ס ב\"ה (דמה שאמרו אין לו דמות כו' העיקר קאי על בחי' עצמות אוא\"ס שלמעלה מאצי', דז\"ע דמות הגוף וגוף שהקשה בשל\"ה מאחר שאין לו דמות הגוף ממילא אין לו גוף, ומה צ\"ל אין לו גוף כו'. ומבו' במ\"א התי' ע\"ז דדמות הגוף הוא בחי' בי\"ע שנק' כדמותינו כו', וגוף הוא בחי' אצי' וכמא' וכמה גופין תקינת לון כו', שכ\"ז אינו שייך בעצמות אוא\"ס ב\"ה), כ\"א בהאורות וגילוים דאוא\"ס שנמשך בע\"ס דאצי' כו'. וגם באצי' ה\"ז למעלה מבחי' הגבלה, וכנודע דע\"ס דאצי' אין סוף להתפשטותן ונק' ג\"כ ע\"ס בלי מה כו', וכדאי' בס\"י מדתן עשר שאין להם סוף שגם כמו שהן בבחי' מדה ושיעור דעשר בבחי'"],[3601330154,"מהותים מיוחדים ה\"ה בבחי' א\"ס כו' וכמ\"ש במ\"א. ומ\"מ ה\"ה בבחי' ציור אדם חסד דרועא ימינא גבו' דרועא שמאלא כו' חכמה מוחא כו', בבחי' התלבשות אור בכלי שהאור בא בבחי' תפיסא בהכלי כו', שיש לכל אור כלי מיוחדת שלפי אופן כזה הוא האור, דכלי החכ' הוא כלי לאור החכ' דוקא וכלי הבינה לאור הבינה דוקא כו', וכן בהמדות חו\"ג כו' שיש לכל אור כלי מיוחדת כו'. וכנודע שיש בכלים חילוקי מדרי' וכמ\"ש בע\"ח דחיוהי הוא בחי' המוחין וגרמוהי בחי' מדות, ובאגה\"ק אי' דחיוהי הוא האור וגרמוהי בחי' הכלים, והיינו דבמוחין גם הכלים הם בבחי' חיוהי שהם כמו האור וע\"כ הם כלים לגילוי אור המוחין כו', וכלים דמדות שנק' גרמוהי הם כלים רק לאור המדות כו'. והגם שיש התלבשות המוחין גם במדרי' שלמטה מהמוחין וכמו עד\"מ התלבשות השכל בכח התנועה שביד ובכח ההילוך שברגל כו', כמו\"כ בבחי' חסד דרועא ימינא כו' שזהו בחי' חיצוניות המדות לפעול פעולת החסד כו' יש בזה מבחי' המוחין כו', שז\"ע הג' פרקין שביד שהן בחי' חב\"ד חג\"ת נה\"י שבכל מדה בפרט כו', וכמו השכל שמחייב\nהשפעת החסד ועצם החסד ופעולתו היינו השפעתו בפועל כו' וכמ\"ש במ\"א. וכ\"ש בבחי' פנימיות המדות שבלב אדה\"ע כבי' שהן למעלה עדיין מבחי' פעולה כו', שיש בהם מבחי' המוחין וכמו ויאמר ה' אל לבו שזהו המשכת בחי' המוחין למדות כו'. וכמו\"כ בבחי' המל' שזהו כמשל כח ההילוך שברגל שהיא בחי' סוכ\"ד דאצי' כמשל הרגל כו' (וגם נק' רגל להיות שבה וע\"י נמשך הגילוי בעולם שלמטה, וכידוע דמל' הוא בחי' הגילוי שגם הגילוי בע\"ס גופא מהספי' העליונה אל התחתונה הוא ע\"י המל' כו', ועש\"ז נק' רגל שבה וע\"י הולך האדם ממקום למקום כו'), יש בזה ג\"כ בחי' המוחין כו', שז\"ע חכ' דמע\"ב דכולם בחכ' עשית שנמשך ומתלבש בז\"א ומל' דששת ימים עשה ה' כו' שהן ששה מדות דז\"א, ובד\"פ הן מדות שבמל' ויש בהם התלבשות המוחין שז\"ע כולם בחכ' עשית כו', דעש\"ז נק' המל' חכ' תתאה כו'. מ\"מ הרי כ\"ז הוא בחי' הארת המוחין לבד שאין בחי' עצמות המוחין מתלבשים בזו\"נ כ\"א בחי' חיצוניות והארת המוחין לבד כו', וכמשנת\"ל במשל דבחי' המוחין שבמדות הן בחי' חיצוניות המוחין לבד והשכל שביד\nורגל הוא בחי' שכל המעשי לבד כו'. וכמו\"כ הוא הדוגמא למעלה דבחי' המוחין דזו\"נ אין זה בחי' עצמות המוחין כ\"א הארה לבד, וכנודע דנה\"י דאימא נעשים מוחין לז\"א ונה\"י דז\"א נעשים מוחין לנוק' ויש בזה הארה מבחי' ו\"ק דאי' כו', אבל זהו רק הארה ומדרי' חיצוניות דמוחין כו', ועצמות המוחין הן בג\"ר דוקא כו'. ועמ\"ש בע\"ח שער הפרצופים ד\"ג וז\"ל כי עיקר המוחין הוא בחי' נשמה פנימית שבתוך הג\"ר ממש אלא שנק' הג\"ר מוחין כו', והיינו דהג\"ר הן כלים לגילוי אור המוחין ששם הוא עצמות ומהות המוחין להיותם בבחי' כלים לאור זה ומתלבש שם האור בבחי' פנימיות שהוא בחי' הגילוי אל הכלים כו', ובכלים דמדות מאיר בחי' אור המדות בגילוי ומה שיש בהם מבחי' המוחין הוא בחי' חיצוניות המוחין והארתן לבד כו'. וכ\"ז הוא מפני שהאורות באים בבחי' התלבשות פנימי וע\"כ צ\"ל הכלי כפי מדרי' האור להיות האור בבחי' התלבשות בהכלי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא מזה למעלה, הנה אצילות הוא בחי' אדה\"ע והן אורות המתלבשים בכלים חסד דרועא ימינא כו' חכמה מוחא כו' דהתלבשות</span>"],[3601330155,"<b>אור</b> המוחין הוא בג\"ר דוקא, ואור המדות בכלי המדות, ויש ג\"כ התלבשות המוחין במדות וגם בבחי' מל' והו\"ע חכ' דמע\"ב, זהו הארה לבד, ועצמות המוחין הן בג\"ר דוקא שהן כלים אל האור כו'.\nוא\"ו) <b>וזהו</b> הטעם מה שהכלים פועלים בהאורות להיות כמהות הכלים, וכמו בפעולת ההתהוות דאיהו וגרמוהי חד לברוא בהן מאין ליש, דהתהוות הוא ע\"י האור דוקא וכמ\"ש באגה\"ק ד\"ה איהו וחיוהי לפי שהאור מעין המאור הוא מהותו ועצמותו כו' שהוא לבדו בכחו ויכולתו להוות יש מאין כו', דכח ההתהוות הוא בעצמות דוקא ובא ע\"י האור כו'. אמנם מהאור עצמו הרי א\"א להיות מציאות יש כו', וז\"ע הוי' אחד דמצד שם הוי' הרי העולמות גם לאחר שנתהוו הם בבחי' ביטול בתכלית כו', והיינו דמש' הוי' עצמו א\"א להיות מציאות היש, וע\"כ גם לאחר שנתהוו ה\"ה בטלים כמו קודם שנתהוו כו'. רק משם אלקי' דשמש ומגן הוי' אלקי' שמעלים ומסתיר על שם הוי' יכול להיות התהוות היש כו', ומבו' בסש\"ב ח\"ב ספ\"ד שזהו בחי' הכלים שמסתירים על האור כו'. הרי שהאורות פועלים כפי אופן הכלים כו', וזהו לפי שהאורות הן בבחי' תפיסא והתלבשות ממש בהכלים ע\"כ הכלים פועלים בהאור להיות פעולת האור כפי אופן הכלי דוקא כו'. אמנם ההתלבשות היא בבחי' התגלות שהאורות מתגלים בהכלים, והיינו\nלפי שהכלים בטלים אל האורות והם ראוים לקבל את האורות, ע\"כ האורות הם מאירים בגילוי ממש בהכלי ויש להם שליטה וממשלה על הכלים ומנהיגים אותם, והו\"ע פעולת הגילוי שהאור פועל שיהי' הגילוי בבי\"ע כו', והוא מ\"ש החכמה תעוז לחכם יותר מעשרה שליטים אשר בעיר והן הע\"מ דשרשם מע\"ס דאצי', שהכלים פועלים להיות פעולת ההתהוות ע\"י שמסתירים על האור כו' כנ\"ל, ומ\"מ החכ' תעוז לחכם להיות גילוי אור בבי\"ע ולהיות בהם בחי' הביטול כו' (ועמ\"ש מזה בד\"ה בשעה שהקדימו, רס\"ג). וזהו דאצי' הוא ממוצע בין אוא\"ס המאציל אל הנבראים להיות גילוי אוא\"ס בעולם כו', שזהו תכלית הכוונה בהתהוות האצי' בכדי שיהי' גילוי אלקות בעולמות כו', דכשם שאמצעית האצי' הוא להיות התהוות המציאות דבי\"ע, כמו\"כ תכלית הכוונה הפנימית דאצי' להיות עי\"ז גילוי אלקות בבי\"ע כו', דלולא האצי' לא היינו יודעים כלל ענין האוא\"ס ולא הי' ידיעת והשגת אלקות בנבראים ולא הי' התגלות כחות אלקים כלל כמו התעוררות אהוי\"ר וכה\"ג, וע\"י האצי' הוא שיש גילוי אלקות בעולם כו'. ושרש ההמשכה היא\nמבחי' חכ', וזהו שהחכ' היא ראשית ההשתל' היינו שהחכ' היא בחי' כלי להגילוי דאוא\"ס להאיר בבחי' פנימיות כו', וז\"ש הוי' קנני ראשית דרכו דראשית גילוי הקו הוא בחכ' כו', להיות דכללות ענין הקו הוא להאיר את העולמות והיינו להיות בבחי' אור פנימי שזהו בחי' גילוי כו' כנודע, וראשית גילוי הקו להיות בחי' הגילוי בעולמות הוא בחכ' שהיא הכלי כללית לקבל בתוכה בחי' הגילוי דאוא\"ס ב\"ה, וע\"י החכ' נמשך הגילוי בכל האצי' וגם בעולמות בי\"ע במלאכים ונשמות שיהי' בהם השגה אלקית וגם בנשמות שירדו למטה שיודעים ומשיגים אלקות כו', שכ\"ז הוא בשרש שרשו מבחי' חכ' דאצי' כו'. וכ\"ז הוא מפני שהכלים דאצי' הן כלים ראוים ומוכנים לקבל האור, והאור מאיר בהם בבחי' התלבשות פנימי בהתגלות כו', שעי\"ז נמשך הגילוי גם בבי\"ע כו'."],[3601330156,"<span data-k=\"ks\"><b>קיצור.</b> ולכן הכלים פועלים בהאורות להיות מהם התהוות מציאות היש, והאורות שולטים ומנהיגים את הכלים להיות ביטול היש, החכ' תעוז לחכם כו', והוא מפני שהן כלים אל האור שהוא בהם בבחי' התלבשות פנימי בהתגלות, וזהו שע\"י אצי' הוא בחי' הגילוי דאלקות גם בבי\"ע. וראשית הגילוי הוא מבחי' חכ' ששם ראשית גילוי הקו כו'.</span>\nז) <b>והנה</b> נת\"ל במשל דמה שהכחות מתלבשים בהאברים שאינם בערך זל\"ז הוא לפי שהן כחות פנימיים בעצם והיינו שהן רק כחות הנפש לא אור עצם הנפש כו', ומתצמצמים להיות בבחי' אור פנימי כו'. ולהבין הדוגמא מזה למעלה, הענין הוא דהנה ידוע דאצי' הוא גילוי ההעלם מאוא\"ס המאציל שז\"ע אצי' מל' ואצלתי מן הרוח אשר עליך שהוא הפרשת הארה שאינו התחדשות דבר, וכמו אצילות רוחו של משה על הזקנים שאין זה מהות אחר שהרי ההשפעה הי' צ\"ל ע\"י משה, הרי מה שנאצל על הזקנים זהו רוחו של משה ממש שהי' כלול תחלה במשה ונמשך מההעלם אל הגילוי כו'. וכמו\"כ הו\"ע אצי' למעלה שאינו התחדשות דבר כמו ברי' שהוא התחדשות יש מאין משא\"כ אצי' כו'. וזהו שאצי' הוא אלקות ממש דענין האלקות דאורות דאצי' הוא בחי' התפשטות מעצם אלוק' כו' כמ\"ש במ\"א, והיינו שאין זה עצמות המאציל ממש כ\"א הארה המתפשטת ממנו אבל לא בבחי' התחדשות דבר כו'. ומ\"מ הרי אצי' ג\"כ בבחי' אין ערוך לגבי עצמות, וכן מובן ממ\"ש והחכ' מאין תמצא שהחכ' היא בחי' יש ונמצאת מאין דכתר בבחי' יש מאין,\nוכמ\"ש במ\"א שז\"ע תמצא כמו המציאה שאינו ידוע מאין באה, כמו\"כ בחי' חכ' אינו יודע את מקורה, כמו היש שאינו יודע ומשיג את מקור המהווה אותו כו'. ובתו\"א ד\"ה פתח אלי' כ' דיותר משאין ערוך ברי' לגבי אצי' אין ערוך אצי' לגבי אוא\"ס ב\"ה, וזהו שאו' אין ערוך לך בעוה\"ז דהיינו שאנחנו בני עוה\"ז הגשמי אין לנו לומר שכמו שהעוה\"ז הוא כאין וכלא נגד העולם העליון מכולם שהוא רוחני מאוד (הכוונה על עולם האצי' שזהו עולם העליון, דעולמות בי\"ע נק' עולמות התחתונים כו', וכידוע דרבינו נ\"ע הי' או' על אצי' עליון כו'), כן העולם העליון הזה הוא כלא נגד א\"ס ב\"ה. אלא אין ערוך לך כלל לדמות ביטול זה לביטול זה, היינו שאין לדמות העדר תפיסת מקום (דעם ניט ביטרעף) דאצי' לגבי אוא\"ס ב\"ה להעדר תפיסת מקום דבי\"ע לגבי אצי', כי הנה ביטול עולם העליון נגדו ית' הוא מצד שהוא נברא וחלוק ממנו ומחי' אותו בכל שעה ובלתי השפעת ה' עליו הי' כלא הי', אבל ביטול עוה\"ז נגד עולם העליון אינו אלא מצד שהוא חשוב ממנו (שהרי הוא ג\"כ עולם שנק' עולם העליון כו' שנתהווה\nמאוא\"ס ב\"ה רק שהוא חשוב) במעלה ומדרי' הרוחני' והרחק רב ביניהם, אבל מ\"מ שניהם בבחי' א' שהם נבראים ומקבלים. ואף שהעולם היותר עליון משפיע בעולמות התחתונים ולולא ההשפעה מהעולם העליון היו מתבטלים ח\"ו, הנה מה שהעולם העליון משפיע בעולמות התחתונים אינו מצד עצמו כ\"א מחיותו מה שמקבל מבוראו, ולולא ההשפעה מעולם העליון היו העולמות התחתונים מתבטלים. אבל מ\"מ לא היו מתבטלים לגמרי להיות כאלו לא היו, שהרי ענין ביטולם מצד העדר ההשפעה ח\"ו מעולם העליון הוא שהי' מתכללים בעולם העליון, והרי ידוע דכל מה שנברא בעולמות התחתונים נמצא כלול בעולם העליון כנודע דכל חלקי דצח\"מ דבי\"ע יש גם באצי'"],[3601330157,"כמ\"ש בע\"ח וכמבואר במ\"א (והיינו מפני שהוא ג\"כ בבחי' עולם כו'), וא\"כ הביטול שלהם הוא רק שיהיו במדרי' עליונה יותר אבל לא ביטול לגמרי מכל וכל. משא\"כ עולם העליון אינו שייך לומר שהוא כלול באוא\"ס ב\"ה, שהרי אוא\"ס לאו מכא\"מ כלל ואם הי' מסתלק ח\"ו ההשפעה ממנו הי' מתבטל לגמרי והי' כלא הי' כו'. וזהו שהעולם העליון אין ערוך לגמרי יותר משאין ערוך עולם התחתון לגבי עולם העליון כו', ופי' אין ערוך דענין הערך הוא א' לגבי אלפים כמ\"ש בסש\"ב והיינו שהוא חלק ממנו רק שהוא חלק קטן כו', וברוחניות הו\"ע עו\"ע שהעלול כלול בעילתו והוא כחלק קטן ממנו (רק שאינו חסר בהעילה כלום כו'), ומדרי' התחתונה שבעילה מתלבשת בהעלול וכמו בשכל ומדות ומחדו\"מ (והיינו כח המח' ודיבור כו' וכמ\"ש בד\"ה ואתה הרם כו') שהן נר\"נ והו\"ע בי\"ע וכן אצי' כו' וכמ\"ש במ\"א, ואין ערוך הוא שאינו נמצא כלול במקורו כו'. וענין אין ערוך לך בעוה\"ז י\"ל שבעוה\"ז נראה ונגלה איך שאין ערוך שהרי עצם הגשמי הוא בדרך אין ערוך שא\"א להיות התהוות הגשמי בדרך ערך כו', וכאשר אנו\nרואין דבר גשמי בהכרח לומר שהתהוותו הוא מאין בבחי' אין ערוך כו', וע\"כ בעוה\"ז דוקא נבין איך שהעולם היותר עליון ג\"כ אין ערוך שה\"ה ג\"כ עולם והתהוותו היא בבחי' יש מאין כו', ונמצא דעולם האצי' ג\"כ באין ערוך ועוד יותר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וביאור הענין הנה אצי' הוא בחי' גילוי ההעלם שאינו התחדשות דבר, ומ\"מ אצי' באין אין ערוך לגבי המאציל, ויותר משאין ערוך עשי' לגבי אצי' כו' שזהו רק עליון ותחתון שהתחתון נמצא כלול בהעליון (ולכן גם ביטול התחתון אינו ביטול לגמרי רק שמתבטל ממציאותו הראשון כו'). ואין ערוך הוא שאינו נמצא כלול במקורו, וזהו אין ערוך לך בעוה\"ז שבזה נראה ונגלה, ומזה נבין שכ\"ה בכללות העולמות כו'.</span>\nח) <b>אך</b> אינו מובן מאחר שאצי' הוא כענין ואצלתי כו', שזהו גילוי ההעלם הרי אין זה התחדשות כו' וכמ\"ש המערכת בענין אצי' שלא נתחדש דבר במאציל ונאצל רק שנתגלה כח הכמוס והחתום מכח אל הפועל כו', ואיך יצדקו שניהם. אך הענין הוא דהנה ידוע דאצי' הוא ממוצע בין אוא\"ס המאציל אל הנבראים כו' (ועמשי\"ת לקמן פ' ק\"ס ופ' קס\"א), וידוע דכל ממוצע צ\"ל כלול מב' המדרי', וא\"כ יש באצי' מבחי' אוא\"ס המאציל וגם מבחי' הנבראים, והן בחי' האורות והכלים דאצי' כו'. דהנה כלים דאצי' הן בבחי' גבול וכמ\"ש בעה\"ק שא\"ת שיש לו כח בבע\"ג ואין לו כח בגבול אתה מחסר שלימותו כו' והגבול הנמצא ממנו תחלה הן הספי' כו', והכוונה על הכלים דאצי' שהן בבחי' גבול והיינו שהן בגדר ומהות בחי' חכ' וחסד כו', דעיקר מציאות בחי' חכ' וחסד הוא בהכלים דוקא כו'. וגם יש הגבלה בהתפשטות שלהן וכמו שיעור קומה של יוצר בראשית רל\"ו אלפים רבבות פרסאות כמנין ורב כח כו', וי\"ל דשיעור והגבלה זאת הוא כמו שהוא בבי\"ע דהיינו כאשר נמשך בברי' הוא בבחי' מספר כזה, אבל באצי'\nאינם בבחי' שיעור ומדה עדיין בהתפשטותן כו', וכמ\"ש במ\"א דכללות ענין הגבול דכלים הוא שתהי' בהם וע\"י ההגבלה חוץ לאצי', אבל באצי' גופא אינם בבחי' גבול כו', וזהו מ\"ש בס\"י מדתן עשר שאין להם סוף ומבו' במ\"א שזהו גם בבחי' הכלים שאין להם גבול כמו שהן"],[3601330158,"באצי' כו'. אבל מ\"מ גם כמו שהן באצי' הן בבחי' מציאות מדות וכחות כו', אבל האורות אינם בבחי' מציאות מדות שה\"ה הארה מאוא\"ס המאציל שאינו בגדר מדות כלל כמו\"כ ההארה ג\"כ אינו בגדר מדות כו'. וכידוע דשרש האורות הן מהקו דשרש המשכתו הוא מהאוא\"ס שלפני הצמצום וכמ\"ש בע\"ח המשיך קו דק מאור העליון כו', והגם דהמשכת הקו הוא ע\"י הצמצום דכללות התהוות האצי' הן אצי' האורות ואצי' הכלים הכל הוא ע\"י הצמצום שהי' באוא\"ס ב\"ה, שהרי הצמצום הי' בהאור וכנודע דלפני הצמצום הי' הגילוי בבחי' א\"ס ממש, וכמ\"ש בע\"ח בתחלתו דטרם שנאצלו הנאצלים כו' הי' אור עליון פשוט ממלא כל המציאות כו' ולא הי' לא בחי' ראש ולא בחי' סוף אלא הכל הי' אור א' פשוט שוה בהשוואה אחת והוא הנק' אור א\"ס כו', וענין הצמצום הוא שנתעלם בחי' הא\"ס ונמשך האור בבחי' מדה ומשקל לפ\"ע העולמות כו'. ומ\"מ עיקר הצמצום הוא בשביל התהוות הכלים, וכמ\"ש בע\"ח בשע\"א סוף ענ\"ג דצורך הצמצום הוא כדי לעשות בחי' הכלים כי ע\"י צמצום האור ומיעוטו יש אפשרות אל הכלי להתהוות ולהתגלות כו', דהנה\nהכלים הם בבחי' מציאות דבר, וכאשר הי' מאיר גילוי אור א\"ס לא הי' אפשר להיות מציאות הכלים כו', וגם במדרי' שאחר הצמצום הרי בבחי' א\"ק לא יש עדיין מציאות הכלים מפני שהאור מאיר שם בגילוי דהיינו בחי' עצמות הקו שמאיר שם בגילוי ממש א\"א להיות בחי' מציאות הכלים כו', וגם בעקודים הוא בבחי' כלי אחד כו', וכ\"ש בבחי' גילוי האור א\"ס שלפני הצמצום לא הי' אפשר כלל להיות התהוות הכלים כו', כ\"א ע\"י הצמצום דוקא שהוא בחי' העדר האור והגילוי יכול להיות התהוות הכלים כו'. והתחלת התהוותן הוא מן גוף הצמצום עצמו וכמ\"ש בע\"ח שם ענ\"ב דענין הצמצום הוא לגלות שרש הדין כו', ובהג\"ה שם דשרש הדין הוא בחי' המקום שהוא דוגמת הכלים כו', ובמ\"ח כ' המציא שרש הדין במה שצמצם עצמו כו', והיינו דבחי' מקום הוא החלל שבו נצטיירו כל העולמות כו', ומבו' במ\"א שהיא הרשימו שבתוך החלל שזהו בחי' המקום שנתגלה ע\"י הצמצום כו'. משא\"כ האורות הרי אין התהוותם מן הצמצום שהרי מההעדר א\"א להיות גילוי, כ\"א מהאור והגילוי שנמשך אחר הצמצום דהמשכתו הוא מעצמות אוא\"ס\nכו', והתהוות הכלים בפועל הגם שזהו ג\"כ מהקו שהרי ע\"י האור והגילוי נתהווה כל ההשתל' כו', הנה זהו ע\"י התלבשות הקו בנקודת הרשימו שעי\"ז דוקא הוא שנתהוו הכלים מהאור כו'. וז\"ע מה שמהתעבות האור נעשה הכלי וענין התעבות הוא בחי' ההגבלה והמציאות שבהאור שבא ע\"י דבר אחר כו', וכמו עד\"מ האותיות שבשכל שכל ענין שכלי הרי יש בו אותיות במה שיתלבש ויתגלה כו', שגם קודם שבא בגילוי בהשגה הרי יש בו אותיות בהעלם ונעשים אח\"כ אותיות ממש להלביש את השכל כו', והרי אין האותיות מגוף השכל דא\"כ הי' צ\"ל כל אור שכל באותיות מיוחדים אל השכל ההוא, ואנו רואין שאינו כן, אלא שאין האותיות מן השכל רק שבאים ע\"י השכל כו'. וכמו\"כ מהתעבות האור שהוא בחי' הגבלה שבו שע\"י הרשימו מזה נתהוו הכלים, ושרשם האמיתי של הכלים הוא מהרשימו, רק שפעולת ההתהוות הוא ע\"י הקו שהוא בחי' הגילוי, משום דכל התהוות צ\"ל ע\"י התגלות הפועל כו', אבל עצם שרש התהוותן הוא מהרשימו כו', ושרש האורות הן מעצם הקו שהוא בחי' הגילוי דאוא\"ס שלפני הצמצום שנמשך אחר הצמצום כו', וע\"כ האורות הן בלי מה לא בבחי' מהות ומציאות דבר כו'. וזהו ב' המדרי' שבהממוצע דאצי' שהאורות הן"],[3601330159,"מהאוא\"ס המאציל שבהממוצע והכלים הן מה שבערך הנבראים כו'. והנה ידוע דהתורה היא ג\"כ ממוצע בין האוא\"ס אל העולמות וכמא' אסתכל באורייתא וברא עלמא כו' התורה אומרת אני הייתי כלי אומנתו כו', דקיום כל הדברים הגשמיים והתהוותן מאין ליש הוא ע\"י התורה דעשי' שכל הדברים הגשמיים הכתובים בתורה הם הם חיותם וקיומם ויש מהם שנא' ברמז כו', וזהו שאמרז\"ל דברו חכמים בהווה היינו בהתהוות כו', ויש תורה בכל עולם ועולם שעי\"ז הוא המשכת והתחברות אוא\"ס בעולם ההוא כו', והממוצע דתורה אינו כמו הממוצע שבעולמות שאינו נמשך בחי' העצמות כ\"א הארה לבד, ובתורה אין הממוצע מפסיק ונמשך בחי' העצמית כו' וכמ\"ש במ\"א, ומ\"מ הוא ע\"י ממוצע דוקא. והממוצע כלול מב' המדרי' והו\"ע פנימית התורה וחיצוניות התורה, דהנה חיצוניות התורה ה\"ה באה בהגבלה וכמו אלו טריפות ואלו כשרות שיש מדה ושיעור לכל דבר שזהו מצד העולמות שהן בבחי' גבול כו', אבל פנימיות התורה אין לה מדה וגבול כלל, וכדאי' לכל יש סיקוס חוץ מהתורה שאין לה סיקוס והיינו פנימיות התורה כו', שזהו בחי' אוא\"ס שבתורה שבבחי' בלי גבול כו'.\n<b>וזהו</b> מ\"ש עוטה אור כשלמה שהן ב' מדרי' אור הוא בחי' הפנימיות בחי' האוא\"ס שבתורה, ושלמה הוא חיצוניות התורה שהוא בחי' לבוש המעלים את האור שיוכלו העולמות לקבל כו', וכמ\"ש בסש\"ב פנ\"ב וז\"ל אבל השכינה עצמה כו' א\"א לעולמות לסבול ולקבל כו' בלא לבוש המעלים ומסתיר כו', ומהו הלבוש שיוכל להסתירה ולהלבישה ולא יתבטל במציאות באורה הוא רצונו ית' וחכמתו כו' המלובשים בתורה ומצותי' הנגלית לנו ולבנינו כו' עכ\"ל, והיינו דבלבוש התורה נמשך ג\"כ בחי' העצמות ממש רק שהוא בבחי' לבוש המעלים עכ\"פ שאינו מאיר בגילוי כו'. ולעתיד יהי' גילוי בחי' עצמות אוא\"ס ב\"ה ע\"י בחי' פנימיות התורה וכמ\"ש בסש\"ב פל\"ו ולזה נתן הקב\"ה לישראל את התורה שנק' עוז כו' לקבל שכרם לע\"ל בלי שום לבוש כו', וכבר הי' לעולמים מעין זה במ\"ת כו', דכל הגילוים שיהיו לעתיד הכל הי' במ\"ת בהתגלות לפי שעה ולכן על כל דו\"ד פרחה נשמתן והחזירן בטל תחי' שהוא טל תורה שנק' עוז כו', וזהו עוטה אור כשלמה שהן ב' המדרי' שבממוצע דתורה שעי\"ז יוכל להיות התחברות דאוא\"ס\nועולמות כו', וזהו השייכות דנוטה שמים למ\"ש עוטה אור כו' דבכדי שיהי' נוטה שמים כיריעה שיהי' התהוות וקיום העולם הוא ע\"י עוטה אור כשלמה שהן ב' מדרי' שבתורה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולתווך הענין יקדים שאצי' הוא בחי' ממוצע בין א\"ס לעולמות הנבראים, וב' המדריגות שבממוצע הן בחי' האורות והכלים, שהכלים הן בחי' הגבול והמציאות שבאצי', והאורות הן בלי מציאות, כי שרשן מהקו שנמשך מאוא\"ס שלפני הצמצום, והגם שהמשכתו הוא ע\"י הצמצום, הנה עיקר הצמצום הוא בשביל התהוות הכלים ומה שנמצא ע\"י הוא נקודת הרשימו בחי' המקום, וזהו שרש הכלים רק פעולת התהוותן הוא ע\"י האור, והקו הוא מאוא\"ס שלפני הצמצום, והוא שרש האורות, והנה התורה ג\"כ ממוצע (וית' לקמן), ובזה יתבאר מ\"ש עוטה אור כשלמה שזהו ב' המדרי' שבממוצע דתורה כו'.</span>"],[3601330160,"<h3>בס\"ד. יום ב' דחה\"ש, תער\"ב</h3>\n<b>ויחן</b> שם ישראל נגד ההר ופרש\"י כאיש אחד בלב אחד, וצ\"ל מה\"ע כאיש א', ומה הי' נצרך במ\"ת להיות כאיש אחד דוקא. ולהבין זה ילה\"ק משנת\"ל דאצי' הוא ממוצע בין אוא\"ס המאציל אל הנבראים והממוצע כלול מב' מדרי' והן בחי' האורות והכלים דע\"ס דאצי', דהכלים הן בבחי' מציאות דבר בבחי' גבול והאורות הן בבחי' בלי מ\"ה כו'.\nט) <b>ועפ\"י</b> הנ\"ל יובן דמה שהאצי' הוא באין ערוך לגבי אוא\"ס ב\"ה, היינו בחי' הכלים שהן בבחי' גבול שאינו ערוך לגבי אוא\"ס כו', והתהוותן הוא ע\"י הצמצום דהיינו ע\"י העדר האור כנ\"ל, הרי דאופן התהוותן הוא בדרך אין ערוך היינו בבחי' ריחוק כו', וכמו\"כ ההתהוות משרשן מהרשימו הוא בדרך אין ערוך שהרי רשימו הוא בחי' כח נעלם, שזהו ההפרש בין הקו לרשימו דקו הוא בחי' גילוי ורשימו הוא בחי' העלם כו', וא\"כ מה שנמשך מן הרשימו התהוות הכלים ה\"ז ג\"כ בבחי' העלם, הרי אין זה התהוות שבבחי' קירוב כו'. והענין הוא דהנה ידוע דז' שמות שאינן נמחקים הם בע\"ס שם אל בחסד שם אלקים בגבו' כו', ה\"ז בבחי' הכלים דע\"ס ש' אל בכלי החסד דאל הוא ל' גדולה וגם ל' תוקף והיינו תוקף ההשפעה כמ\"ש הפרד\"ס וזהו שייך בכלי החסד שהוא בחי' חסד ממש ושם שייך ענין הגדולה ותוקף ההשפעה כו', וכן ש' אלקי' שהוא בחי' הדין ה\"ז שייך בכלי הגבו' כו'. אך מה שהשמות הן בכלים אין זה בהכלים עצמן שהרי השמות הן להבורא ית', אלא הכוונה אל האור והחיות של הכלי כו',\nוהוא החיות של הכלי עצמה לבד האור המלובש בה כו', וכמ\"ש בלק\"ת בהביאור דאת שבתותי ובשא\"ד, והחיות של הכלים עצמן הוא מן הרשימו וז\"ע השמות אל אלקי' כו' שהן המשכות מבחי' הרשימו להוות ולהחיות הכלים כו', והרי המשכות אלו מהרשימו אינן בבחי' גילוי אור היינו בבחי' קירוב ודביקות במקורם כ\"א בבחי' העלם כו', ולכן הכלים הם בבחי' העלם מצ\"ע וכמא' כד אנת תסתלק כו' אשתארו כגופא בלא נשמתא, הרי גם שיש בהם בחי' החיות שמצ\"ע היינו בחי' הכחות שמהרשימו כו', מ\"מ אשתארו כגופא כו', בבחי' העלם האור והגילוי כו' כמ\"ש במ\"א. והיינו לפי שמה שנמשך בהם מהרשימו אין זה בבחי' דביקות במקורם דהיינו בבחי' קירוב להיות בבחי' גילוי אור כ\"א בבחי' העלם כו', דרשימו היא בחי' כח נעלם וההמשכה משם היא בבחי' העלם כו', וכן בהתהוות הכלים בפועל שהוא ע\"י האורות כנ\"ל פ\"ח שהאור הוא בחי' גילוי כו', הנה אי' בע\"ח שהתהוות הכלים הוא ע\"י פגיעת האו\"י והאו\"ח שמכים זב\"ז שעי\"ז נופלים מהם אותיות שמהם מתהוים הכלים כו', ומבו' במ\"א שזהו עד\"מ ב' שכליים הפכים של\nב' לומדים שמפלפלים ומקשים זל\"ז נולד מזה השגה וסברא חדשה שלא הי' בדעתם קודם, והיינו שע\"י הקושי' מא' לזולתו שסותר דעת הזולת ה\"ה מוצא סברא חדשה לתרץ ולהעמיד סברתו הקודמת כו', ולהיות שבאה ע\"י סתירת וביטול שכלו וסברתו ה\"ה סברא קטנה בערך עצם ההשגה שנמשכה תחלה, שהרי אם לא הי' חבירו סותרו לא הי' הולדת הסברא כלל רק מן הסתירה דוקא באה ע\"כ היא סברא קטנה בערך כו', ואם בלא סתירה הי' בא לידי עוד השגה מהשגה הקודמת, היתה ג\"כ השגה גדולה כמו השגה הקודמת כו',"],[3601330161,"אבל השגה הנ\"ל שבאה ע\"י סתירה ונפילת השגתו ה\"ה השגה קטנה בערך כו' וכמ\"ש במ\"א באורך. והדוגמא מזה בהתהוות הכלים שע\"י הכאת האו\"י ואו\"ח שסותרים זל\"ז נופלים אותיות שזהו כענין נפילת ההשגה כו' ומזה נתהוו הכלים שזהו כמו ההשגה הקטנה שנעשה ע\"י הנפילה מהשגתו שאינה בערך ההשגה הקודמת כו'. הרי דהתהוות הכלים מהאותיות שבהאורות אין זה בבחי' קירוב כ\"א מה שנופל מהאותיות שבהם שזהו בבחי' הבדלה וריחוק כו' (וכבר נת\"ל פ\"ח דהאותיות שבהאור הו\"ע התעבות האור שבא מבחי' הרשימו). וז\"ש והחכ' מאין תמצא היינו בחי' כלי החכ' דהתהוותה בבחי' אין ערוך ה\"ז כמו יש מאין כו', וכמו\"כ בכל הכלים דע\"ס דאצי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו שאצי' הוא באין ערוך היינו הכלים דהתהוותן ע\"י הצמצום, וגם החיות שבהם משרשם הרשימו והן הז' שמות, ה\"ז בבחי' ריחוק, ולכן הם העלם כגופא בלא נשמתא, וגם התהוותן מן האור הוא מפגיעת או\"י ואו\"ח שנופלים אותיות, ונת' משל ע\"ז, ונפילה הוא בחי' ריחוק כו'. </span>\nיו\"ד) <b>והגם</b> דבאמת גם הכלים דאצי' הן בבחי' אצילות שה\"ה אלקות ממש, מ\"מ בחי' האלקות דכלים אין זה בחי' התפשטות אלק' דהיינו התפשטות הארה מאוא\"ס המאציל בבחי' גילוי כו', כ\"א מה שבא בבחי' הבדלה וריחוק כו'. וכמו ניצוץ הנבדל מן האבוקה ה\"ה מהות אש ממש שבא מעצם האבוקה, ומ\"מ ה\"ה נבדל מן האבוקה ואינו מאיר כמו להב האבוקה שמאיר כו'. וכמו\"כ בחי' הכלים שהן אלקות ממש שנאצל מבחי' עצמות אוא\"ס מבחי' כח הגבול שבו כו', מ\"מ ה\"ז בא בבחי' הבדלה מן העצם כו', וכמ\"ש הרקנטי בענין הע\"ס דמאורו הגדול התנוצצו הכלים, דענין ההתנוצצות הוא שאין זה כמו אצי' ממש שהוא ע\"ד ויאצל מן הרוח שהיא הארה הקשורה במקורה כשלהבת הקשורה בגחלת כו', משא\"כ ענין ההתנוצצות הוא שבא בבחי' הבדלה כו', וי\"ל דענין התנוצצות הוא כענין נפילת האותיות שע\"י הכאת או\"י ואו\"ח כו' כנ\"ל. וע\"כ עם היותם אלקות ממש דעש\"ז נק' אצי' כו' (ובמ\"א מבו' די\"ל שהן בבחי' אצי' שאינן באים בבחי' שינוי המהות מכח הגבול שבא\"ס שה\"ה אלקות ממש, ולא כמו הברי' שע\"י ההתהוות\nבבחי' אין ערוך היינו בבחי' ריחוק הרי נעשו שלא בערך אלקות לגמרי שהן בבחי' יש כו', משא\"כ בכלים דאצי' הגם דהתהוותן בבחי' אין ערוך מ\"מ ה\"ה אלקות ממש, והיינו דאין ערוך שלהם אינו בעצם מהותם כ\"א מה שהתהוותם הוא באין ערוך היינו בבחי' ריחוק, אבל בעצם מהותם הם כמו שרשן ומקורם שהן אלקות ממש כו' (והחילוקים במדרי' אלקות גופא אין זה בבחי' אין ערוך כו'). ועמ\"ש בד\"ה יו\"ט של ר\"ה, רס\"ו, שהכלים דאצי' אינם בבחי' מהות אחר בעצם לגבי בחי' הכלים דא\"ק דהעדר המציאות שלהם שהם רק בחי' שרש נשמות דגופו' הוא רק מצד האור שמאיר שם בתוקף הגילוי כו', והעיקר מה שהכלים הם באין ערוך לגמרי הוא לגבי הא\"ס הבלי גבול כו', וכן לגבי האור המאיר בהם שהוא הארת אוא\"ס כו' (וי\"ל דכמו\"כ הוא גם לגבי בחי' כח הגבול כמו שהוא לפני הצמצום כו', דהרי לפני הצמצום אינו שייך ענין המציאות כלל באיזה אופן שיהי' כו', וכמ\"ש בדרוש הנ\"ל בענין אותיות החקיקה דלפני הצמצום הוא כמו חקיקה"],[3601330162,"מעבר לעבר שהי' בלוחה\"ר שלא יש כלל מציאות אותיות כו' והכלים שהן בבחי' מציאות ה\"ה באין ערוך לגבי מדרי' זו גם בעצם מהותם כו', אבל לגבי בחי' הרשימו כמו שהוא לאחר הצמצום אין הכלים באין ערוך בעצם מהותם כ\"א באופן התהוותם כו'). ועמ\"ש במ\"א דאמיתית ענין אין ערוך הוא לך דוקא לגבי עצמות א\"ס כו'), מ\"מ ה\"ה ג\"כ בבחי' יש מאין מפני שהן בחי' גבול שאינן ערוך לגבי אוא\"ס הבלי גבול כו' והתהוותן הוא בדרך אין ערוך כו', ויותר משאין ערוך עשי' לגבי אצי' כו', דהרי הכלים דאצי' נעשים נר\"ן לבי\"ע כו', וכל מה שנתהווה בבי\"ע הכל הוא מבחי' הכלים דאצי' דאיהו וגרמוהי חד לברוא כו' דבחי' איהו הוא למעלה מגדר הנבראים כו', ובחי' גרמוהי הוא מה שבבחי' שייכות אל הנבראים כו' (וכמ\"ש במ\"א דבחי' איהו שמתייחד עם גרמוהי הוא בבחי' בלי מספר ובחי' גרמוהי הוא בבחי' מספר, וגם הארת בחי' איהו שע\"י גרמוהי מבו' שם די\"ל שהוא בבחי' מספר שז\"ע שיעור קומה של יוצר בראשית כו'). הרי שיש להם איזה ערך, אבל הכלים דאצי' לגבי אוא\"ס הן באין ערוך לגמרי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והגם שהכלים הן ג\"כ אצי', הנה זהו בבחי' התנוצצות (ע' דרוש שיטת הרמ\"ר פ\"ג) כמו הניצוץ שהוא אותו המהות ונבדל כו', ולכן לגבי מקורם בא\"ק ואותיות הרשימו אחר הצמצום אינו בבחי' שינוי המהות, ולגבי אוא\"ס הבל\"ג וגם לגבי הרשימו לפני הצמצום ה\"ה באין ערוך כו'. ויותר משאין ערוך כו'. </span>\nיא) <b>וכ\"ז</b> הוא בבחי' הכלים, אבל האורות דאצי' ה\"ה בבחי' גילוי ההעלם מאוא\"ס המאציל שהרי התהוותן מהקו הוא בבחי' קירוב שהרי האור קשור ודבוק באוא\"ס המאציל כשלהבת הקשורה בגחלת כו', ולכן הן בבחי' בלי מ\"ה שלא בבחי' מהות ומציאות מדות וכחות כו'. וכן הקו מאוא\"ס ה\"ה ג\"כ בבחי' דביקות וכמ\"ש בע\"ח שהקו נוגע ודבוק בא\"ס ב\"ה כו', והגם דהקו נמשך ג\"כ ע\"י הצמצום כו', מ\"מ הרי המשכתו הוא מהאוא\"ס שלפני הצמצום כו', ועם היות דהמשכתו הוא בדרך דילוג הצמצום כמשל השערות ע\"י הפסק הגולגולת כו', מ\"מ הרי השערות יונקים מהמוח כו', כמו\"כ בחי' חוטא יקירא קדישא כו' דאיקרי מזל ה\"ה בבחי' דביקות באוא\"ס ב\"ה שהמשכתו הוא בבחי' גילוי ה\"ז בבחי' גילוי ההעלם כו' (ועמשי\"ת לקמן פי\"ח), (והנה ממשנת\"ל יובן דבאמת יש יתרון מעלה בכלים על האורות דשרש הכלים הן מהרשימו שזהו רושם מהא\"ס שלפני הצמצום כו', וכמ\"ש במ\"א דהאותיות דרשימו לא נגע בהם הצמצום כלל. ועם היות שי\"ל שע\"י שנתעלם גילוי האור מן האותיות עי\"ז נעשו בבחי' מציאות כו', שזהו ההפרש\nבין אותיות הרשימו כמו שהן לפני הצמצום לכמו שהן אחר הצמצום כו' וכמ\"ש במ\"א. מ\"מ ה\"ז רק ע\"י התעלמות האור לא שנגע הצמצום בהאותיות רק שנתעלם האור ונתגלו האותיות עי\"ז בבחי' מציאות כו' וכמ\"ש במ\"א, והאורות שנמשכים מהקו הגם דשרשו הוא מהאוא\"ס שלפני הצמצום כו', מ\"מ ה\"ז לאחר שנתעלם האור וחזר ונמשך כו', וכן משמע בע\"ח ממה שהקשה למה לא נשאר הקו מאחר שעתיד להחזיר ולהמשיכו, ותי' שלא הי' אפשר להיות התהוות הכלים כ\"א כאשר נתעלם האור לגמרי ואח\"כ חזר והמשיך את האור במדה ובמשקל כו'. הרי מובן דאור הקו שחזר והמשיך האוא\"ס ב\"ה הוא האור שנתצמצם ונסתלק כו' (ומ\"ש"],[3601330163,"בהגהת אוצ\"ח דאדם הישר הוא ממדרי' שלא הגיע בו הצמצום כו' י\"ל שזהו בחי' פנימיות הקו כו'). הרי שיש יתרון מעלה בהכלים לגבי האורות כו', וכן מובן ממשל דניצוץ הנבדל מן השלהבת הנ\"ל שהרי הניצוץ הוא מגוף ועצם הגחלת והשלהבת אינו עצם הגחלת כו', וזהו הטעם מה שהאורות יורדים להתלבש בהכלים הוא מחמת שרש הכלים שלמעלה מהאורות כמ\"ש במ\"א. וע\"כ באמת ביטול הכלים מגיע למעלה מביטול האורות שז\"ע הקדמת נעשה לנשמע דנעשה הוא הביטול שמצד הכלים כו' וכמ\"ש בתו\"א בהבי' דוקבל היהודים, וי\"ל דזהו ג\"כ מעלת אתכפי' על אתהפכא דעיקר ענין האתכפי' הוא בהכלים דוקא וזה מגיע למעלה מאתהפכא כו' וכמ\"ש בהבי' דקחו מאתכם תרומה בהוספות דתו\"א. וי\"ל דזהו ג\"כ מ\"ש ויחן ישראל נגד ההר כולם כאיש אחד כו', דענין ההתחלקות מה שאין דעותיהן שוות ה\"ז מצד הכלים כו', דהרי מצד הנפשות כולם מתאימות המה כו', וכמו בחי' האורות שהן פשוטין ואין בהם התחלקות כו', כמו\"כ הוא בנשמות בעצם שמתאימות המה וההתחלקות הוא מצד הכלים כו', ומה שבמ\"ת היו כולם כאיש א' הו\"ע ביטול\nהכלים כו'. וכמו בהתאסף ראשי עם יחד כו' דקאי על ר\"ה שהן בבחי' התאחדות והתכללות מצד ביטול הכלים כו', דזהו ג\"כ ענין קבעומ\"ש דר\"ה שהו\"ע ביטול הכלים דוקא ועי\"ז הוא ההתאחדות כו'. וכמו\"כ במ\"ת הי' בהם ביטול הכלים עד שנעשו כאיש אחד וזה הי' הכנה רבה למ\"ת דבכדי שיומשך מבחי' עצמות א\"ס ב\"ה שז\"ע התורה שהוא המשכת גילוי עצמות א\"ס ב\"ה דבמ\"ת הי' בגילוי ממש כו', דהמשכה זו הוא ע\"י ביטול הכלים דוקא. וזהו ויחן שם ישראל כולם כאיש א' ע\"י הביטול שלהם והוצרך זה במ\"ת בכדי שתהי' המשכת התורה מבחי' עצמות כו').\n<span data-k=\"ks\"><b>קיצור.</b> אבל האורות התהוותן מהקו בבחי' קירוב, והקו נוגע ודבוק באוא\"ס, ויש יתרון מעלה בכלים דאותיות הרשימו לא נגע בהן הצמצום, משא\"כ הקו הוא מאור שנסתלק ולכן ביטול הכלים מגיע למעלה יותר, ובזה יתבאר מ\"ש ויחן ישראל כו'.</span>"],[3601330164,"<h3>בס\"ד. ש\"פ נשא, וש\"פ בהעלותך, תער\"ב</h3>\n<b>נשא</b> את ראש בני גרשון גם הם למשפחותם כו', וצ\"ל מה\"ע אומרו גם הם איזה מקום יש לחלק בני גרשון מבני קהת שהוצרך לומר גם הם, גם בד\"כ מה\"ע נשיאת ראש כו'. ולהבין זה ילה\"ק משנת\"ל דבאצי' יש ב' ענינים שהוא בבחי' גילוי ההעלם וגם באין ערוך. ונת' שזהו בבחי' האו\"כ דאצי' דהכלים הן באין ערוך והאורות דשרשן מהקו והקו הרי המשכתו הוא מהאוא\"ס שלפני הצמצום ה\"ז בבחי' גילוי ההעלם כו'."],[3601330165,"יב) <b>אך</b> עדיין צ\"ל שהרי מ\"ש והחכ' מאין תמצא משמע דקאי על כללות החכ' גם בחי' האור דחכ' שהוא בבחי' אין ערוך לגבי אוא\"ס כערך יש לגבי אין כו', והרי לפי הנ\"ל פ\"ח דהקו נמשך מאוא\"ס שלפני הצמצום ה\"ה בבחי' בלי גבול ולכן האורות הם ג\"כ בלי מה בבחי' פשיטות כו', וא\"כ איך שייך לומר שהן באין ערוך כו'. אמנם י\"ל שגם האורות דע\"ס הנמשכים מן הקו אין ר\"ל שהן פשוטים לגמרי כמו פשיטות האוא\"ס ממש שהרי או' בס\"י ע\"ס בלי מ\"ה כו' הרי גם כמו שהן בלי מה ה\"ה בבחי' ע\"ס עכ\"פ כו', ומצינו ע\"ס באורות ג\"כ כמו ע\"ס דעתיק והרי בעתיק לא יש עדיין בחי' הכלים, וכידוע בענין ואין אלקים עמדי דלעת\"י אתמר, דאלקים הוא בחי' הכלים, ובעת\"י ואין אלקים עמדי כו'. וי\"ל דמה שבעתיק לא יש בחי' הכלים היינו שלא יש שם ענין הכלים כלל לא רק העדר המציאות של הכלים כו', הגם שבמדרי' שלמעלה מעתיק דאצי' כמו בבחי' א\"ק מבו' במ\"א ונת' ג\"כ לעיל פ\"י דהעדר הכלים דשם הוא רק בבחי' העדר המציאות כו', והיינו שגם בא\"ק יש מציאות הכלים רק שמפני תוקף האור\nוהגילוי הן בבחי' העדר המציאות כו', מ\"מ בבחי' עתיק י\"ל ששם לא יש ענין הכלים כלל, דהרי א\"ק הוא בחי' אריך דכללות העולמות וכמ\"ש בלקו\"ת בהבי' דמוצאיהם בשם המ\"ח, אבל בחי' עתיק שהוא בחי' תחתונה שבמאציל (וכמשי\"ת דשרשו למעלה מבחי' א\"ק) י\"ל דשם לא יש ענין הכלים כלל כו', וא\"כ הרי הע\"ס דעתיק הן בבחי' האור כו'. וכמו\"כ בעקודים אי' בע\"ח שהן עשר אורות בכלי א' כו', הרי שיש ע\"ס בהאורות עצמן גם כמו שהן עקודים בכלי א' כו'. ובאמת אם היו האורות בבחי' בלי גבול ממש לא הי' אפשר להיות כלל התלבשות האורות בהכלים, שהרי זה דבר מוסכם שכל גוף שהוא בבחי' גבול א\"א שיהי' בתוכו בבחי' התלבשות אור וחיות הבלתי מוגבל, והרי הכלים הן בבחי' גבול שהרי יש מציאות ספירות באצי' שהן בבחי' מציאות חכ' וחסד כו', ובהכרח שזהו בבחי' הכלים עכ\"פ (וכמ\"ש בת\"ז וכמה גופין כו', ואתקריאו בתקונא דא חסד דרועא ימינא כו'), הרי הכלים הן ודאי בבחי' מהות ומציאות ספירות ממש (עם היות שהן אלקות ממש מ\"מ ה\"ה בבחי' מציאות והוא מה שאלקות נעשה בבחי' מציאות כו'\nוכמ\"ש בעה\"ק והגבול הנמצא ממנו תחלה הן הספי' והיינו הכלים כו'), ואם נאמר שהאור הוא בבחי' בל\"ג ממש איך אפשר שיתלבש בהכלים בבחי' אור פנימי כו'. והנה במ\"א מכריחים מזה דהגבול דכלים הוא שהן רק כח הגבול לא גבול ממש, והוא דעם היותם בגדר מיוחד דחו\"ג מ\"מ אין סוף להתפשטותן כו', הרי שהן בגדר מיוחד דחו\"ג עכ\"פ. וענין מה שהן רק כח הגבול הוא לשלול שבאצי' אינם מגבילים והחסד עד\"מ הוא בבחי' בל\"ג, מ\"מ ה\"ז בבחי' הגבלה דחסד כו'. וגם מאחר שפועלים בהאור דכשיומשך חוץ לאצי' יהי' בבחי' הגבלה דלולא כח המגביל שבאצי' הרי היו בבחי' בל\"ג גם חוץ לאצי' כו', ממילא בהכרח שגם באצי' פועלים איזה הגבלה, והוא שהגם שא\"ס להתפשטותן מ\"מ יהי' התפשטותן רק באצי' לבד כו'. וכנודע ההפרש בין האוא\"ס שלפני האצי' ובין האוא\"ס שבאצי', דאוא\"ס שלמעלה מאצי' הוא שנמשך ומתפשט בכל העולמות ואוא\"ס שבאצי' הוא שמתפשט רק באצי' לא חוץ לאצי' כו', ובכדי שיהי' גילוי האצי' בבי\"ע הוא ע\"י גילוי אור עליון שלמעלה מאצי' כו', וכמו בקרי\"ס שהי' התחברות אצי' עם בי\"ע כתי' ויולך ה' את הים ברוח קדים מבחי' קדמונו של עולם כו', וכן בנשמות כשנמשך לפעמים נשמה דאצי' בבי\"ע"],[3601330166,"וכמ\"ש במ\"א שיש נשמות שנקרע עליהם הפרגוד כו' הוא ע\"י גילוי אור עליון דוקא כו', והיינו לפי שהאוא\"ס שלמעלה מאצי' הוא בבחי' א\"ס ממש וע\"כ יוכל להיות משם שיהי' גילוי אצי' בבי\"ע כו', משא\"כ אור האצי' הוא שנגבל ע\"י הכלים להיות התפשטותו רק באצי' כו', ואם נא' שהאור דאצי' הוא בבחי' בל\"ג ממש איך אפשר שיתלבש בכלים שהן בבחי' כח הגבול ושתגביל אותו הכלי כו'. ואינו דומה למדרי' שלפני הצמצום דבבחי' כח הגבול שבא\"ס שהן אותיות הרשימו הי' בהם בגילוי ממש בחי' האוא\"ס הבל\"ג כו', הנה לפני הצמצום הרי לא הי' ענין המציאות כלל וכלל שהרי האותיות דרשימו אינם בבחי' מציאות אותיות ח\"ו וכמשנת\"ל פ\"י ומבו' במ\"א באורך שזהו כמו האותיות שבלוחות כו', וא\"כ אינו שייך לשאול ע\"ז איך הי' בהם גילוי אוא\"ס מאחר שהכל הוא א\"ס ממש רק מה שכחו בגבול והכח הגבול הוא א\"ס ממש כמו כח הבל\"ג כו'. וגם בזה כשהי' הגילוי דאור הא\"ס הבל\"ג הי' כח הגבול בבחי' העלם בתכלית כו', דכשם שאחר הצמצום כאשר נתגלה כח הגבול ונתגבר על הכח הבל\"ג הרי הבל\"ג הוא בהעלם לגמרי\nכו', שהרי הגם דאוא\"ס נמצא בכל מקום ממש בכל החלל עד למטה מטה דלית אתר פנוי מיני', ומ\"מ הרי אינו מורגש כלל עד שיש מדרי' שאין בהם גילוי אוא\"ס כלל היינו שאינן יודעים כלל מענין האלקות כו', כמו\"כ קודם הצמצום שאור הא\"ס הי' בגילוי הי' ממלא כל מקום החלל דבכל חלקי החלל הי' בגילוי ממש בחי' האור הא\"ס כו' (ועמשי\"ת לקמן פ'), וכ\"ז הוא במדרי' שקודם הצמצום כו'. אבל שיהי' לאחר הצמצום התלבשות פנימי דאור הא\"ס בכלים שהן בבחי' גבול ושיפעלו ההגבלה בהאור באצי' וחוץ לאצי' איך אפשר שיהי' כן כו', ובהכרח שהאורות דאצי' הן בבחי' התלבשות פנימי בהכלים וכמו שנת\"ל פה\"ו, והרי אנו רואין שיש בחי' התלבשות בעולמות שזהו בשרש מע\"ס דאצי' כו', וגם האמת עד לעצמו שהן בבחי' התלבשות פנימי כו', ואיך אפשר להיות שבגוף שהוא בבחי' גבול יהי' בהתלבשות אור הבל\"ג כו', אלא בהכרח לומר שגם האור דאצי' אינו בבחי' פשיטות ובבחי' בל\"ג ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם גם האורות דאצי' הן בבחי' ע\"ס (וכמו בעתיק ועקודים שהע\"ס הן באורות), שאם הם בל\"ג איך מתלבשים בהכלים שהן בחי' גבול, והגם שהן רק כח הגבול, ה\"ה מגבילים עכ\"פ בבחי' חסד וגבורה, וגם מגבילים בהתפשטותן להיות רק באצי', וא\"ד לגילוי האוא\"ס באותיות הרשימו לפני הצמצום, שהרי האותיות לא היו במציאות כלל, וגם באמת הי' אז כח הגבול בהעלם כערך העלם אוא\"ס הבל\"ג לאחר הצמצום כו'. </span>\nיג) <b>ולבד</b> כל הנ\"ל לא יתכן לומר דמה שהאור נק' אור החסד זהו רק לאחר התלבשותו בכלי, אבל מצ\"ע יוכל להיות אור הגבורה. דא\"כ מה\"ע דאי' בזהר לך לך דפ\"ז ע\"א ובמק\"מ שם בשם האריז\"ל אחליפו דוכתייהו אור החסד בכלי הגבו' כו', הרי אינו שייך לקרותו אף אחליפו שהרי אין לו יחס לחסד יותר מלגבורה כו'. ובמ\"א מבו' ענין אחליפו דוכתייהו עד\"מ שמאי והלל ששניהם קיבלו מרב א' (שקיבלו משמעי' ואבטליון כמ\"ש בפר\"א) סברא א' ואעפ\"כ זה אוסר וזה מתיר, והיינו שנעשה השינוי בהכלים שלהם, כי שמאי שהי' מצד הגבו'"],[3601330167,"נוטה לאיסור שהוא מבחי' גבורה, והלל שהי' מצד החסד נוטה להיתר שהוא בחי' חסד, אבל האורות שהוא הסברא שקיבלו מרבם הרי שניהם קיבלו סברא אחת אלא שנשתנה לפי מזג הכלי כו' (י\"ל שזהו ע\"ד המבו' בענין אור מים רקיע דמיא ניידי ורקיע אגלידו מיא כו', והיינו דמים היא נקודת החכ' שיכולים עדיין להטותה לכל צד כו'. דג' מדרי' אור מים רקיע הן בהשפע שנמשך מן המשפיע אל המקבל, דאור הוא כמו שההשפעה היא עדיין אצל המשפיע בהעלם, ומים הוא כמו שנמשך בהתגלות מן המשפיע אל המקבל, ורקיע הוא כמו שנתפס אצל המקבל כו' וכמ\"ש במ\"א. כמו\"כ בשכל הרב אין בה עדיין התחלקות חו\"ג כו', ובהשגה שלהם נעשה התחלקות דחו\"ג כפי אופן ההשגה אם מבחי' החסד או כו', ומבו' במ\"א שיש בחי' אור מים רקיע עד רום המעלות ובשרשן הן בחי' ג\"ר דעתיק וג' ראשין לראשין שהן בחי' אור קדמון וצח ומצוחצח כו'), והנה כשבאים בפעם שני' לשמוע אותה הסברא מפי הרב שהו\"ע יציאת האורות מהכלים בכדי לקבל שכל הרב המשפיע, הנה אז בפעם השני' יכולים להחליף אור החסד בכלי הגבו', כי הסברא\nשקיבלו מרבם היא (רק) מקור החסדים והגבורות כי עצם הסברא אינה עדיין בבחי' חו\"ג (וע\"כ יכול להיות שיתחלפו אם בענין זה גופא או בענין אחר כו'. וכמו שאנו רואין בחוש בבעל שכל שמקבל איזה ענין שכלי ומשיגו באופן כך וכך ואח\"כ כששומע או לומד עוד הפעם את השכלי הזה ה\"ה משיגו באופן אחר, ואין זה שמקודם הטעה א\"ע בזה, כ\"א מפני פשיטות השכלי יוכל להתחלף להיות בהשגה כזו ובהשגה אחרת כו', ומכ\"ש שבענין אחר יכול להיות שישיג לפעמים לחסד ולפעמים לגבו' כו'). ולכן מצינו לפעמים ב\"ש מקילין ומאחר שהן מבחי' הגבו' היו צריכים להיות לעולם מחמירין, אך הו\"ע שהתחלף אור החסד להיות בכלי הגבו'. וכנודע בענין ד' פרשיות שהן ד' מוחין חו\"ב וחו\"ג, ולכאו' יפלא איך נחשבים חו\"ג שהם מדות בבחי' מוחין. אך הענין הוא כנ\"ל שחו\"ג שנחשבים למדות היינו כשהאורות בכלים של חו\"ג ששם הם מתחלקים להיות חסד או גבו' ע\"י מזג הכלי כנ\"ל, אבל האורות אין בהם התחלקות חו\"ג עדיין, וכמו במשל שמאי והלל הנ\"ל שמתחלקים להיות חו\"ג בכלים שלהם כנ\"ל ולא באורות כו'. ומ\"מ\nמובן שגם שכל הרב ה\"ה עכ\"פ מקור בחי' חו\"ג שיש בו בחי' חו\"ג בהעלם רק שהוא בבחי' פשיטות לגבי שכל והשגת המקבלים שבהם בא החו\"ג בבחי' התחלקות במציאות כו', וכמו בד\"פ דתפילין הרי הב' מוחין חו\"ג עם היותן מוחין ה\"ה בבחי' חו\"ג עכ\"פ, וכמבו' במ\"א שזהו בחי' הדעת שהוא ההטי' לחו\"ג כו', ונמצא שגם בבחי' הפשיטות אינו בבחי' פשיטות ממש עם היות שעי\"ז יכול להיות אחליפו דוכתייהו כו'. והמובן מזה הוא ג' ענינים, הא' דהאורות דחו\"ג כשהן בהכלים שלהם ה\"ה בבחי' חו\"ג ממש, וכמו הסברא כשהיא בהשגת הלל ושמאי ה\"ה בבחי' חו\"ג ממש, דבהשגת הלל הרי הסברא מחייבת החסד ולהיפך בהשגת שמאי כו', הרי שהאורות הן בבחי' חו\"ג ממש כו'. ואין זה כמו משל המים שמשתנים לפי גוון הכלים שגם בעת שהן בתוך הכלי ונראים לפי גוון הכלי ה\"ה פשוטים בעצם מהותם כו', אבל כאן הרי הסברא כשהיא בהשגת הלל ה\"ה מחייב רק חסד ולא גבו' וכן להיפך בהשגת שמאי כו', והיינו לפי שסיבת בחי' החו\"ג שבהאורות אינו רק מצד הכלים לבד כ\"א מצד שרש ומקור האור כו', וכמו החו\"ג שבהסברא גבי\nשמאי והלל הרי הסיבה הוא מפני שגם בסברת הרב יש בה חו\"ג בהעלם. ועם היות שבהשגתם נעשה בחי' החו\"ג במציאות"],[3601330168,"דלפי שהשגת שמאי היא בבחי' גבורה ע\"כ הוא תופס הסברא לחומרא, והלל להיות השגתו בעצם בבחי' חסד ע\"כ הוא תופס להיתר כו', מ\"מ אם בהסברא עצמה לא הי' בה חו\"ג כלל לא הי' ההתחלקות בהשגתם בבחי' חו\"ג ממש במציאות כו'. וכמו\"כ עם היות שע\"י הכלים נעשה בחי' החו\"ג, מ\"מ הסיבה לזה הוא מה שבשרש ומקור יש בחי' חו\"ג בהעלם וע\"כ נעשים בבחי' אור החסד ואור הגבו' כו'. ומ\"מ יכול להיות אחליפו דוכתייהו וכמו גבי שמאי דעם היות שהסברות שלהם הן בבחי' חו\"ג ממש ומ\"מ יכולים להתחלף מצד פשיטות מקורם כו'. וענין הב' שההתחלפות הוא רק בהאורות לא בהכלים, שהרי כלי השגתם בעצם אינו משתנה דשמאי כלי השגתו הוא בבחי' גבו' וגבי הלל היא בבחי' חסד, רק שהסברות מתחלפים שזהו האור אבל הכלי אינה משתנית שגם בעת שהשגת הסברא היא לחסד גבי שמאי מ\"מ עצם כלי השגתו היא בבחי' גבו' כו' (רק יכול להיות שזהו ע\"י התכללות בחי' חסד בגבורה ע\"כ ההשגה היא בבחי' חסד כו', ונודע דגם חסד שבגבו' היא בבחי' גבו' וכן גבו' שבחסד היא בחי' חסד כו'). ונמצא שהחילוף הוא רק\nבהאורות לפי שעם היותם בבחי' חו\"ג ממש מ\"מ ה\"ה בבחי' פשיטות לגבי הכלים ויכולים להתחלף, אבל הכלים שהן בבחי' חו\"ג במציאות ממש אינם משתנים ומתחלפים כו'. והג' שסיבת החילוף הוא ע\"י הרב (היינו ע\"י הקבלה ממקורם כנ\"ל), והרי סברת הרב יש בה ג\"כ בחי' חו\"ג בהעלם ומ\"מ ה\"ה בבחי' פשיטות לגבי המקבלים עד שיהי' בהם וע\"י ההתחלפות שזהו בהכרח ע\"י הפשיטות דוקא שעי\"ז דוקא נעשה בהם ההתחלפות כו', הרי הגם שיש בחי' חו\"ג בהעלם ומ\"מ היא בבחי' פשיטות כזו שיכול להיות מזה התחלפות הסברות כו', ונמצא שגם ענין הפשיטות בזה אינו שהוא בבחי' פשיטות לגמרי ומ\"מ הוא בבחי' פשיטות עד שיהי' עי\"ז אחליפו דוכתייהו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וגם ממש\"א אחליפו דוכתייהו כו' מובן שיש בחי' חו\"ג בהאורות, והוא עד\"מ שמאי והלל שקבלו סברה אחת ומתחלקת בבחי' חו\"ג בכלי השגתן וכאשר שומעים עוה\"פ מהרב יכולה להתחלף השגתן מחמת פשיטות שכל הרב, ומ\"מ שם דוקא הוא המקור דחו\"ג שלהם והחו\"ג שלהם הוא בעצם הסברה היינו בהאור מפני שהחו\"ג שבהעלם הוא סיבת החו\"ג שבהתחלקות, וכן ההתחלפות הוא בהסברות, והוא מחמת פשיטת המקור, הרי שיש שם חו\"ג והן בבחי' פשיטות שיהי' משו\"ז ההתחלפות כו'. </span>\nיד) <b>ויובן</b> זה למעלה ע\"ד מארז\"ל שתוק כך עלה במח', דלכאו' משמע שאין לזה טעם כלל, אבל באמת חלילה לומר כן שאין זה בדרך עקשות ח\"ו, אלא שז\"ע טעם הכמוס שלמעלה מהשכל והחכ' וע\"פ השכל אין לזה טעם כלל עד שלא הי' לו מקום בשכלו ע\"ז ושאל וכי זו תורה וזו שכרה כו'. וזהו ענין האור של החכ' כמו שהוא למעלה מכלי החכ', דעם היותו חכ' וטעם, מ\"מ לגבי החכ' והשכל שהוא כלי החכ' נראה כאלו הוא רצון בלי טעם, וא\"כ הוא מופשט מגדר כלי החכ' שהוא שכל (והיינו גם מהאור המתלבש בהכלי כי האור כאשר מתלבש בכלי ה\"ה כמו הכלי להבין ולהשיג מה שהכלי יכולה להשיג, ועצם האור מופשט מזה הגם שהוא ג\"כ חכ' כו'). וה\"ז ע\"ד כמו השכל שבמוח לגבי השכל שבנפש המשכלת קודם"],[3601330169,"התלבשותה בגוף שהוא שכל להשיג מהות הרוחניות ממש שז\"ע ההשגה העליונה, וכמו השגת המלאכים שמשיגים מהות הרוחניות (היינו מהות הרוחני דבי\"ע כו'), וכמו ההשגה בדבר שאינו בבחי' מקום וזמן כו' וכמ\"ש במ\"א, וכ\"ש השגת הנשמות בג\"ע שמשיגים מהות הרוחניות שז\"ע הלימוד דג\"ע בכל ענין בבחי' הרוחניות שבו שהנשמות משיגים מהות הדבר כו', משא\"כ השכל שבמוח אינו משיג מהות הרוחני כלל כ\"א בחי' מציאות לבד, ומה שמשיג המהות הוא בדבר גשמי. הרי שאינו מערך השכל שבנשמה כלל דשם ההשגה היא רק במהות הרוחני ובשכל שבמוח מושג רק מהות הגשמי והרוחני הוא רק בבחי' מציאות לבד כו', ולא כמו המדות לגבי השכל דעם היותם שני מהותים מ\"מ ה\"ה בערך זל\"ז בבחי' המציאות שלהם ושניהם מהותים רוחנים כו', אבל השכל שבנפש המשכלת שמשיג מהות הרוחני ה\"ז כמו למעלה מהשכל ממש לגבי השכל הגלוי כו', ומ\"מ הרי גם הוא שכל והוא מקור לשכל הגלוי כו'. ועד\"ז יובן ענין ח\"ע לגבי ח\"ס ועד\"ז הכלים לגבי האור שאור החכ' שרשו ממוחא סתימאה כו' (ונר' הענין בזה דבחי' אור החכ' להיות שגם\nבשרשו הוא בבחי' חכמה ע\"כ ההארה הנמשכת ממנו להאיר בכלי החכ' ה\"ה בבחי' התלבשות והתאחדות בכלי החכ' להיות כערך מהות הכלי עד שאינו בערך שרשו ומקורו כו', וז\"ע שח\"ע אינו בערך לגבי ח\"ס כו', וכמו שכל אנושי דהיינו השכל שבמוח שאינו בערך השכל וההשגה שבנשמה מצ\"ע שהיא למעלה מן השכל לגבי השכל שבמוח, והסיבה לזה הוא מפני שגם השכל שבנשמה היא בבחי' שכל עכ\"פ ע\"כ הארתה שנמשך במוח נעשה בבחי' שכל כמהות המוח הגשמי לתפוס רק מהות דבר גשמי ובדבר רוחני תופס רק המציאות לבד כו'. והיינו מה ששרשו ומקורו הוא ג\"כ בבחי' שכל זהו הסיבה שההארה בהתלבשותה בכלי ה\"ה נעשית כמהות הכלי ואינה בערך שרשה ומקורה כו' (וכמשנת\"ל בהשגת שמאי והלל שנעשה אצלם הסברא בבחי' חו\"ג ממש שהסיבה לזה הוא בחי' החו\"ג בהעלם שיש בסברת הרב כו'). וכ\"ה בח\"ע לגבי ח\"ס כו', וכמו ששורש ומקור החכ' עם היותו ג\"כ חכמה ה\"ה בבחי' פשיטות לגבי החכ' הגלוי' וכמו שתוק כך עלה כו' שאין לזה מקום כלל בחכ' הגלוי', הגם שבח\"ס יש ע\"ז טעם והוא מפני שהטעם והחכ' דח\"ס היא למעלה מהטעם\nלגבי חכ' הגלוי' כו' כנ\"ל. כמו\"כ בחי' האור דחכ' עם היות שבהתלבשותו בהכלי הוא בגדר החכ' של הכלי, מ\"מ בעצם הוא בבחי' בלי מ\"ה לגבי הכלי, מפני שענין ההשגה של האור בעצם מהותו היינו מצד שרשו ומקורו הוא בבחי' פשיטות היינו כמו למעלה מן השכל והשגה לגבי ענין ההשגה של הכלי, רק ע\"י הכלי נקנה בה השגה כזו (עם היות שסיבת הדבר הוא מה שבשרשה ומקורה ה\"ז ג\"כ שכל כנ\"ל, מ\"מ לולא הכלי היתה באופן שרשה ומקורה ורק ע\"י הכלי נעשה באופן השגה כזאת שאינה בערך כו'), וע\"כ האור בעצם הוא בבחי' פשיטות לגבי הכלי שהכלי אינו בערך האור כו'. ומובן דענין באין ערוך דהכלי לגבי האור הוא הרבה יותר מהאין ערוך דהאור המתלבש בהכלי לגבי שרשו ומקורו, דבהאור המתלבש הרי מה שהוא בגדר ענין השגת הכלי ה\"ז רק מצד ההתלבשות בהכלי כו' (וזאת גופא הוא לפי שגם בשרשו הוא בבחי' החכ' והאור הוא רק הארה ממנו כו'). אבל בעצם ענין ההשגה של האור הוא כמו ההשגה בשרשו ומקורו כו'. וענין אין ערוך דהכלי לגבי האור הוא שבעצם ענין ההשגה והחכ' דהכלי אינו במהות החכ' של האור כו'). ועד\"ז הוא בכל האורות דע\"ס, וכמו חסד דלגאו דע\"י נק' אור לגבי"],[3601330170,"חסד עולם דז\"א, ומ\"מ יכול להיות אחליפו דוכתייהו אור הגבו' בכלי החסד, שהרי בע\"ק אע\"פ שיש שם חו\"ג אמרו לית שמאלא בהאי עתיקא והכל ימין כו', ולכן אור הגבו' עם היות שהוא בבחי' גבו' מ\"מ מצד שרשו מגבו' דעת\"י יוכל להיות בכלי החסד כו', וכנ\"ל בענין שמאי והלל שיש מקולי ב\"ש מצד שכל והשגת הרב שהוא בבחי' פשיטות לגביהם וע\"כ יכולים להתחלף הסברות כו'. וא\"כ מה שהאורות נק' בלי מה בלי מהות היינו שלגבי המהות דע\"ס שהם הכלים הם בבחי' בלי מה, עד שיכולים להתחלף והכלים עצמן אינם משתנים ומתחלפים כו' וכנ\"ל במשל דשמאי והלל כו', דשרש הכלים נמשכו מהרשימו שהוא שרש כח הגבול, אבל מו\"ס דעתיקא נמשך מהקו שהוא בחי' האור שהוא הארת אור א\"ס ב\"ה ולמעלה מעלה ממהות הכלים עד שנקראו אצלן בלי מ\"ה, ועכ\"ז הן אורות דע\"ס ממש, היינו שגם בהאורות יש ע\"ס ממש ושייכים רק בבחי' הקו וחוט הנמשך מאוא\"ס ב\"ה.\n<span data-k=\"ks\"><b>קיצור.</b> ויובן זה למעלה ממשארז\"ל שתוק כך עלה במח', והרי יש שם טעם כמוס, והוא למעלה מן החכמה לגמרי לגבי אור החכ' דאצי', כמו שהשכל דנשמה קודם התלבשותה בגוף הרי שכלה והשגתה הוא למע' מהשכל לגמרי לגבי שכלה כמו שמתלבשת בגוף. ומ\"מ ה\"ז שכל וחכ' ומקור לחכ' הגלוי', ומפני שגם המקור הוא חכ' לכן כשהאור הוא בכלי ה\"ה כמהות חכ' דהכלי וכמו שהמקור ע\"ה חכמה הוא בבחי' פשיטות, כמו\"כ האור בעצם הוא בחי' בלי מ\"ה לגבי הכלים (דאין ערוך דהאור אינו כמו אין ערוך דכלים) ולכן אחליפו דוכתייהו, וא\"כ הרי גם האורות הן בבחי' ע\"ס והן בבחי' בלי מ\"ה לגבי הכלים. </span>\nטו) <b>וי\"ל</b> שזהו ג\"כ ענין ע\"ס הגנוזות במאצילן באוא\"ס שלפני הצמצום, והיינו שגם בהיות הקו כלול עדיין בהאוא\"ס שלפני הצמצום שייך בו ע\"ס הגנוזות שהם שרשי האורות כו'. והפרד\"ס כ' שהע\"ס הגנוזות הן שרשי הכלים, והיינו אם נא' שהאורות דע\"ס הם בלי מהות לגמרי כמו האוא\"ס שלמעלה לגמרי ממהות ע\"ס עכצ\"ל דע\"ס הגנוזות הם שרשי הכלים. אבל לפמש\"כ שגם בהאורות דע\"ס י\"ל שייכות חכ' וחסד כו', רק שנק' בלי מה לגבי הכלים דע\"ס, א\"כ ע\"ס הגנוזות שלמעלה מהרשימו הם שרשי האורות דע\"ס דאצי' כו'. אבל האור א\"ס עצמו אפי' האור והגילוי מן העצמות שהוא בבחי' גילוי העצם כו', ה\"ה מופשט לגמרי ממהות ע\"ס ואינו שייך שם בחי' ספי' כלל כו', וע\"ס הגנוזות (אפשר צ\"ל וע\"ס דאורות) הן נק' בלי מה ובלי גבול לגבי ע\"ס דכלים שנאצלו מהרשימו, כי האורות נאצלו ונמשכו מהאור שלמעלה מהרשימו שממנו נמשך הקו, אבל לגבי אור א\"ס עצמו הם ג\"כ שרש ומקור הגבול כו'. ועפ\"ז יש לתרץ מה שלכאו' אינו מובן דבזהר ובאדרא נר' שעתיק הוא ממש מהותו ועצמותו, וא\"כ יקשה מדוע\nהאריז\"ל אמר שיש כמה בחי' למעלה מעתיק וכמו א\"ק ועקודים שהן למעלה מעתיק דאצי' כו'. ועם היות שיש לתרץ זאת שהרי האריז\"ל או' שיש ג\"כ בחי' עתיק למעלה מא\"ק וכמ\"ש בע\"ח שער ח' פ\"ה ולעילא מגולגלתא דילי' יש כדוגמת עתיק דאצי' כו', הרי גם עתיק דא\"ק הוא נמשך מהקו לאחר הצמצום ומק\"פ, וא\"כ איך נא' שהוא עצמות ממש. גם קשה דבאידרא אמרו בע\"י גלגלתא"],[3601330171,"עיינין מוחא כו' שכ\"ז מורה על ע\"ס ובעצמותו ממש אין שייך שום ספירה כו'. ולפי הנ\"ל יתורץ דמאחר שגם בשרש ומקור הקו דהיינו כמו שהוא כלול בהאוא\"ס שלפני הצמצום שייך ע\"ס הגנוזות, והקו י\"ל שנמשך רק מבחי' מל' שבמל' דע\"ס הגנוזות וממנו נתהווה א\"ק כו'. והנה בא\"ק יש עיגולים ויושר שהן נפש ורוח, והקשו בסה\"ק מדוע לא נז' בא\"ק נשמה חי' יחידה כו', וממה שתירצו ע\"ז מובן דיחידה דא\"ק זה\"ע ע\"ס הגנוזות כמו שכלולים באוא\"ס כו', והקו זהו כמו חי' או נשמה הנמשך מבחי' יחידה להתלבש תוך א\"ק, ויחידה הוא בחי' עתיק, והיינו שהע\"ס הגנוזות הן בחי' עתיק דא\"ק (ועמ\"ש לקמן פ' כ\"ז). ועפ\"ז יתורץ מה שמשמע בזהר דעתיק הוא מהותו ועצמותו כי הע\"ס הגנוזות שהן כמו עתיק ויחידה לא\"ק ה\"ה כלולים באוא\"ס ממש שלמעלה מהצמצום והקו, כי הקו נמשך רק מל' דא\"ס כו', ולכן נק' עתיק עצמותו ממש. ומ\"מ ג\"כ שייך בו להזכיר ענין גלגלתא עיינין כו' המורים על ע\"ס כו'. וכ\"ז שייך בשרש ומקור הקו, אבל באור הא\"ס שהוא בבחי' גילוי מהעצם אינו שייך שם ספירות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ושרשי האורות הן הע\"ס הגנוזות באוא\"ס שלפני הצמצום, שהן שרש הגבול, ואוא\"ס עצמו הוא האור הבל\"ג והע\"ס הגנוזות זהו בחי' עתיק דא\"ק, ולכן נחשב בחי' עצמות, ומ\"מ שייך שם בחי' גולגלתא עיינין ומוחא כו'. </span>\nטז) <b>(והנה</b> משנת\"ל דשרש ומקור הקו הוא לגבי עצמות אור הא\"ס שרש ומקור בחי' הגבול כו', אין זה בחי' כח הגבול שבא\"ס כמו בחי' הרשימו כו'. דהנה נת\"ל פ\"ט דרשימו שהוא שרש ומקור הכלים הו\"ע השמות אל אלקים כו' שזהו האור והחיות של הכלים עצמן כו', אבל האור הוא בחי' ש' הוי', וכמ\"ש בסי' שער המועדים דפנימיות ז\"א הוא בחי' ש' הוי' שזה שוה בכל הספי' כו', ובפרד\"ס שע\"ד פ\"ו כ' בענין ש' מ\"ה מלגאו דשם בן ד' עם היות דיסודו ד' עולה עשרה אותיות במילוי שהם ע\"ס והם הספי' המתפשטים בתוך הכלים כו', והיינו שזהו העצמות (ר\"ל האור) המתפשט ומתלבש בתוך הכלים כו', וא\"כ גם בשרשו ומקורו באוא\"ס שלפני הצמצום הוא בחי' ש' הוי' כו'. וידוע ההפרש בין ש' הוי' לשארי שמות דש' הוי' הוא שם העצם כו', וענין שם העצם הוא שמיוחד בהעצם וכמ\"ש אני הוי' הוא שמי המיוחד בי כו', והיינו דכח הגבול הוא כמו כח נבדל מן העצם כו', וע\"ד שנת\"ל פ\"י בענין התהוות הכלים מן הרשימו שאינו בבחי' דביקות וכמו הניצוץ הנבדל כו', כמו\"כ בחי' הרשימו לגבי העצמות הוא\nכמו כח נבדל כו' וכמ\"ש במ\"א. אבל שרש ומקור האור הוא בבחי' יחוד ודביקות כו', וזהו שם הוי' שם העצם כו'. אמנם בש' הוי' יש ג\"כ ב' מדרי' וכמ\"ש ויקרא הוי' הוי' וידוע דהיינו הוי' דסדר השתל' ושלמעלה מסדר השתל' כו', דש' הוי' דסדר השתל' הוא ל' מהווה והיינו שהוא מקור המהווה והוא האור והגילוי דאוא\"ס שזהו מקור ההתהוות כו' (וזהו כמשנת\"ל פ\"ח דההתהוות בפועל הוא ע\"י הקו כו', או י\"ל כמ\"ש באגה\"ק ד\"ה איהו וחיוהי חד שהאור הוא מעין המאור כו'). ובד\"ה ועשית ציץ בתו\"א מבו' דב' השמות הוי' הן בבחי' הרצון והוי' הב' הוא כי ענין הוי' מורה שהוא מהווה כל הויות מאין ליש כו' ע\"י שעלה ברצונו כך, ויש מקור ושורש לזה להיות עולה כך ברצונו כו' והוא הוי' הא' כו'. ולפ\"ז הוי' הב' הוא בעלות הרצון"],[3601330172,"להאציל שבאוא\"ס שלפני הצמצום כו', והוי' הא' הוא קודם עלות הרצון כו'. וי\"ל דהוי' הב' שהוא הוי' דסדר השתל' הנה כמו שהוא באוא\"ס שלפני הצמצום הו\"ע שרשי ההויות כמו שכלולים בהרצון והוא שרש דממכ\"ע הכלול באוא\"ס הבלי גבול כו' כנ\"ל, וש' הוי' א' הוא בעצם הרצון שלמעלה משרשי ההויות הכלולים כו'. אמנם באמת הכל א' הוא דבכלל שרשי ההויות הכלולים כו' הוא גם בחי' הרצון מה שעלה ברצונו להאציל כו', דבד\"כ זהו בחי' שרש דממכ\"ע כו', והוי' הא' שהוא השרש להיות עולה כך כו' הו\"ע רעדכ\"ר שזהו עצם הרצון הכולל הכל כו', והוא בעצם שרש ומקור בחי' הסוכ\"ע כו', וה\"ז כמ\"ש בד\"ה ביום הזה יכפר דרוה\"ר פ\"ד דצור הוא שרש ומקור לכל שרשי ההוי\"ה (וזה\"ע ש' הוי' הא' בחי' רעדכ\"ר כו') ושרש ההוי\"ה הוא בו בהעלם בכח ולא בפועל כו', וזהו בחי' ש' הוי' הב' היינו בחי' שרש ומקור האור דממכ\"ע הכלול בעצם הרצון כו'. ולפ\"ז בחי' ע\"ס הגנוזות שבשרש ומקור הקו הו\"ע ש' הוי' כו', ואין זה כמו השמות דרשימו, דש' הוי' הוא שם העצם שמיוחד כו' (וגם לפמ\"ש במ\"א דענין שם\nהעצם הוא שהוא בחי' בלי גבול ניחא ג\"כ שה\"ה בלי מה לגבי ע\"ס דכלים כו'), והוא בחי' ש' הוי' השייך לסדר השתל' כו', והאוא\"ס הבל\"ג ממש זהו ש' הוי' הא' בחי' רעדכ\"ר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והע\"ס הגנוזות שהן שרש הגבול היינו גבול דאורות, והן ש' הוי', וזהו ויקרא הוי' הוי', הא' קודם עלות הרצון, והב' בעלות הרצון, והיינו דשם הוי' הא' הוא בעצם הרצון והוא האוא\"ס הבל\"ג שרש בחי' סוכ\"ע, והב' הוא שרשי האורות הכלולים באוא\"ס, והוא שרש בחי' ממכ\"ע).</span>\nיז) <b>ואפ\"ל</b> שזהו פי' נעשה אדם בצלמנו כדמותנו דקאי על בחי' אדה\"ע דאצי', דע\"ס דאצי' הן בחי' ציור אדם גולגלתא מוחא כו'. הנה בצלמנו היינו מבחי' ע\"ס הגנוזות במאצילן שמהם נמשכו האורות דע\"ס שהן בחי' נשמה של אדם דאצי' וכמא' וההוא נביעו איהו כנשמתא כו', כדמותנו בחי' הרשימו שממנו שרש הכלים דאצי' שהם בחי' גופא כו', אכן האוא\"ס עצמו לא שייך בו בחי' אדם כי לא אדם הוא כו'. ובהבי' דששים המה מלכות כת\"י הר\"פ ז\"ל כ' וכל ספי' לא שייך לקרוא בעצמותו ומהותו רק בבחי' אור א\"ס שם שייך לקרוא בשם ספי' אבל לא בבחי' ע\"ס כי גם בבחי' אור א\"ס אין מספר כו', אבל במהו\"ע לא שייך שם ספי' כלל עכ\"ל. נשמע לפ\"ז דגם באוא\"ס הבלתי מוגבל שלמעלה מהקו שייך ספירות, רק במהו\"ע המאור לא שייך שם ספי' כלל, והיינו להיות שהאור הוא בחי' גילוי וכל גילוי הוא ע\"י ספי' ולכן שייך ספי' גם בהאור הבל\"ג כו'. ומ\"מ מספר ע\"ס הגנוזות י\"ל דלא שייך רק בשרש הקו שם שייך לומר ע\"ס הגנוזות שזהו בחי' ממכ\"ע כמו שהוא בשרשו ומקורו באוא\"ס ב\"ה, דלהיות דאור\nהממכ\"ע הוא בבחי' ע\"ס ע\"כ גם בשרשו שייך לומר ע\"ס הגנוזות כו', משא\"כ באוא\"ס הבל\"ג בחי' שרש ומקור דאור הסוכ\"ע לא יש מספר לספי' כו', והיינו שהן בבחי' ספירות עד אין קץ והספי' גופא הן בבחי' פשיטות לגמרי, שז\"ע בלי גבול שאין הגבלה ומספר לספירות והספירות עצמן הן בבחי' בל\"ג דהיינו שהן בבחי' פשיטות כו' (ועמשי\"ת לקמן פ'). וכידוע בענין אנת הוא חד ולא בחושבן דלהיותו חד בעצם ע\"כ הוא לא בחושבן דהיינו בהתפשטות אין שיעור (שז\"ע ספי' אין קץ כו')"],[3601330173,"וממילא כל ההתפשטות הוא בבחי' חד כו'. וכמו המשל שבאד\"ז כהאי בוצינא דאתפשט לכל סטר ועיבר וכד בעינא למנדע לון לא תשכח אלא בוצינא בלחודוי כו'. ובעצמות המאור לא יש ספי' כלל כו', ובמ\"א מבו' דהיינו בבחי' עצם האור כמו שכלול בעצמותו שאינו בבחי' המשכה וגילוי כלל מן העצמות כו' לא שייך שם ספי' כלל כו'. וכשם דבאוא\"ס שלפני הצמצום יש ב' מדרי' בד\"כ, הא' בחי' האור שהוא בבחי' א\"ס בחי' בל\"ג, והב' שרש ומקור הקו שבאוא\"ס שהן ע\"ס הגנוזות כו'. כמו\"כ הוא במדרי' שאחר הצמצום בבחי' כתר דאצי', הנה בחי' כתר בעצם ה\"ז למעלה מבחי' ע\"ס ומשם הי' יכול להיות ספי' אין קץ כו', ומה שיש בחי' חכ' שבכתר ומדות שבכתר הן שרשי ע\"ס דאורות כמו שהן כלולים בכתר, אבל הכתר עצמו ה\"ה למעלה מעלה מבחי' ע\"ס כו'. ועפ\"ז יובן מ\"ש והחכ' מאין תמצא דהתהוות החכ' מאין דכתר הוא בבחי' יש מאין דהיינו באין ערוך והלא אצי' הוא בבחי' גילוי ההעלם כו', הענין הוא דזה שהן בבחי' גילוי ההעלם היינו לגבי שרש ומקור הע\"ס כמו שכלולין בבחי' הכתר כו', דאור החכ' דאצי'\nלגבי בחי' חכ' שבכתר ה\"ז בבחי' גילוי ההעלם מאחר שגם חכ' שבכתר היא בחי' חכ' כו'. והגם שהיא למעלה מעלה מבחי' ח\"ע וכנ\"ל בענין שתוק כך עלה במח' כו', מ\"מ הרי גם היא בחי' חכ', אלא שהיא חכמה נעלמה שלמעלה מהשכל וטעם המושג כו'. והעיקר מה שהיא למעלה מהשכל המושג הוא לגבי כלי החכ' דמה שאור החכ' הוא בבחי' שכל מושג כפי מהות הכלי ה\"ז מה שהכלי פועל בהאור כו' כמשנת\"ל, וע\"כ לגבי בחי' מו\"ס אור החכ' הוא בבחי' ערך ובבחי' גילוי מההעלם כו'. אבל לגבי עצמות הכתר ה\"ז באין ערוך דלהיות דעצמות הכתר למעלה מגדר חכ' לגמרי, והוא בחי' בל\"ג ממש, א\"כ החכ' באין ערוך לגמרי לגבי מדרי' זו כו'. וכמו\"כ הוא בבחי' הקו לגבי אוא\"ס שלפני הצמצום הנה לגבי שרש ומקור הקו שהן הע\"ס הגנוזות ה\"ה בבחי' גילוי ההעלם כו', אבל לגבי עצמות אוא\"ס היינו האור שבבחי' א\"ס ממש ה\"ה בבחי' אין ערוך כו'.\n<b>וע\"פ</b> הנ\"ל מובן מ\"ש נשא את ראש בני גרשון גם הם כו', דהנה במשכן היו ב' ענינים יריעות המשכן והכלים. וידוע שזהו או\"פ ואו\"מ דהכלים ארון שלחן כו' הם בחי' או\"פ והיריעות הם בחי' או\"מ כו'. ובני גרשון היו נושאי היריעות, וע\"כ יש מקום לומר שבהם אינו שייך נשיאת ראש כו', דהנה ענין נשיאת ראש הוא להגבי' בחי' ראש ומוחין בבחי' עצמות אוא\"ס ב\"ה וכמ\"ש שאו כו' לגולגלתם בחי' כתר כו', וא\"כ בני גרשון שהן נושאי היריעות בחי' או\"מ א\"צ נשיאת ראש כו'. ומ\"מ נא' בהם ג\"כ נשא את ראש להיות שגם האו\"מ אין זה בחי' העצמות כ\"א בחי' אור וגילוי ושייך שם ספי' אין קץ עכ\"פ כו', ע\"כ צריכים ג\"כ נשיאת ראש כו', וזהו שנא' גם הם שהגם שהן בחי' או\"מ מ\"מ צ\"ל בהם נשא את ראש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו נעשה אדם, בחי' אדם דאצי', בצלמנו שרשי האורות, כדמותנו רשימו שרש הכלים (ומ\"מ גם באור הא\"ס שייך ספירות אין קץ ובעצם האור לא יש ספי' כלל), וכמו באוא\"ס שלפני הצמצום כמו\"כ בכתר, עצם הכתר בחי' א\"ס. ויש שרשי האורות דע\"ס הכלולים, דלגבי מדריגה זו אור החכ' הוא בבחי' גילוי ההעלם, ולגבי עצם הכתר אין ערוך, ובזה ית' פסוק נשא את ראש כו'.</span>"],[3601330174,"<h3>בס\"ד. ש\"פ שלח, תער\"ב</h3>\n<b>שלח</b> לך אנשים ויתורו את ארץ כנען, וצ\"ל מהו\"ע שליחות המרגלים הלא כללות ענין כבישת הארץ הי' לא ענין טבעי ולמה הי' כל ענין שליחותם, דכאשר הכבישה היא בדרך טבעי שייך לתור קודם לידע תוקף וחוזק המדינה באיזה אופן ביכולת לכובשה, אבל בכבישת הארץ לכאו' אינו שייך כ\"ז כו'. וגם מה\"ע ויתורו את הארץ למה לא נא' לרגל את הארץ וכמו שנים אנשים מרגלים כו'. והנה משה אמר להם ג' דברים לראות, א' את העם שעז\"א וראיתם את הארץ מה היא, דהכוונה היא על יושבי הארץ וכמו שפרש\"י ז\"ל, ב' הארץ עצמה וכמ\"ש ומה הארץ כו', ג' הערים כמ\"ש ומה הערים כו'. וצ\"ל מהו ג' ענינים אלו, ומה שנא' ל' מה בכאו\"א. ולהבין כ\"ז ילה\"ק משנת\"ל דהאורות עם היותם פשוטים אינם בבחי' פשיטות ממש כפשיטת הא\"ס שהרי א' בס\"י ע\"ס בלי מה שגם בהאורות יש ע\"ס רק שהן בלי מה לגבי הכלים כו'. ונת' דהקו גם כמו שהוא כלול באוא\"ס שלפני הצמצום יש בו ע\"ס והן ע\"ס הגנוזות שהן שרש ומקור הגבול כו', ולגבי מדרי' זו הקו הוא בבחי' גילוי ההעלם ולגבי האור הא\"ס הוא באין ערוך כו'.\nיח) <b>ועפ\"ז</b> אפשר י\"ל מה שמשמעות הע\"ח הוא שהי' יכול להיות גילוי אור הקו מבלי שיצמצם האור ויתעלם בתחלה כו', דהנה בע\"ח שע\"א סוף ענ\"ג הקשה למה הי' הצמצום באופן כזה שנסתלק האור לגמרי ואח\"כ נמשך הקו ולא הניח אותו בחי' הקו במקומו ויסלק שאר האור הגדול בלבד כו', ולכאו' א\"מ והלא מבו' בכ\"מ דבכדי שיהי' גילוי אור השייך אל העולמות הי' צ\"ל סילוק והתעלמות האור לגמרי, וכידוע המשל בזה בהשפעת השכל דבשכל הרב כמו שהוא לעצמו אינו ניכר כלל האור שכל השייך אל המקבל וע\"י שמעלים אורו לגמרי אזי נבדל וניכר האור השייך אל המקבל כו', וא\"כ לפ\"ז איך הי' אפשר שישאר אור הקו מבלי שיתעלם האור לגמרי כו'. וע\"פ הנ\"ל י\"ל מאחר שיש שרש ומקור לאור הקו באוא\"ס שלפני הצמצום והן ע\"ס הגנוזות שאין זה בחי' העצמות דאוא\"ס הבלי גבול רק מה שכלולים באוא\"ס כו', ולגבי בחי' ומדרי' זו אור הקו הוא בבחי' גילוי ההעלם כו'. א\"כ יצדק הקושיא דמפני מה נתעלם האור לגמרי, הרי הי' מספיק שיתעלם רק האור שבבחי' א\"ס וישאר אור הקו הנמשך מהע\"ס הגנוזות\nשבאוא\"ס כו'. ואם לא הי' הצמצום כלל לא הי' אפשר להיות התגלות הקו דכאשר מאיר האור שהוא בבחי' בלי גבול אינו ניכר כלל האור שבבחי' גבול כו', והיינו דכאשר הי' גילוי אור הא\"ס קודם הצמצום היו הע\"ס הגנוזות בטלים לגמרי באוא\"ס הבלי גבול, וכביטול זיו השמש בשמש דמפני אור גוף ועצם השמש שמאיר שם אינו עולה בשם אור וזיו כו' וכמ\"ש בסש\"ב, וע\"כ הוצרך להיות התעלמות הא\"ס בכדי שיהי' התגלות הע\"ס הגנוזות כו', וזה יספיק שיהי' התגלות הקו מהע\"ס הגנוזות כו' (וכמו בבחי' כח הגבול שבא\"ס שהוא הרשימו לא הי' בזה צמצום רק שנתגלה ע\"י צמצום אור, כמו\"כ הי' יכול להיות בגילוי אור הקו כו'), ומפני מה נתעלם האור לגמרי כו'. ותי' שם שזהו רק בשביל התהוות הכלים דאם הי' נשאר האור אפי' רק אור הקו לא הי' אפשר להיות התהוות הכלים ואחרי שכבר נתהוו אינם מתבטלים גם כשנמשך בהם האור והגילוי כו' וכמ\"ש במ\"א. אמנם עדיין צ\"ל דהרי גם המשכת הקו הוא"],[3601330175,"ע\"י הצמצום שהי' תחלה כו', וגם לפי המשמעות דהע\"ח שהי' באפשר שישאר בחי' הקו כו', מ\"מ הרי הי' עכ\"פ צמצום גם באור הקו כו', וא\"כ איך הוא בבחי' גילוי ההעלם גם משרשו ומקורו כו'. אך הענין הוא דלפי שיטה זו דע\"ס הגנוזות הן שרשי האורות ומשם נמשך הקו כו', צ\"ל דבאמת אינו דומה הצמצום דאור הא\"ס להצמצום שבשרש ומקור הקו כו' (ולעיל פ\"ח נת' דבד\"כ עיקר ענין הצמצום הוא בשביל הכלים לא בשביל האור (ועמ\"ש בדרוש דג' מיני אדם), והיינו שהאור הוא ע\"י שחזר והאיר כו' כנ\"ל, אבל מ\"מ הצמצום הוא בבחי' התעלמות ממש כו'. וזהו ע\"פ השיטה דהמשכת הקו הוא מאור הא\"ס ממש, ע\"כ צ\"ל דהצמצום לגבי הקו הוא ג\"כ בבחי' סילוק והתעלמות לגמרי כו', רק שהמשכת הקו הוא ע\"י שהאור חזר והאיר כו', ולפי ששרש המשכתו הוא מהאור הבלי גבול שחזר והאיר, הנה הגם דאופן המשכתו הוא בדרך דילוג הצמצום וכמו המשכת השערות דרך הפסק הגולגלת כו', מ\"מ ה\"ה נוגע ודבוק באוא\"ס והוא מעין המאור כו'. לפי שלגבי האור הא\"ס גם דביקות כזו כדביקות השערות עד\"מ מספיק להיות האור מעין\nהמאור מפני שהוא בבחי' א\"ס בעצם כו', וכמ\"ש במ\"א שמאוא\"ס גם הארה הבאה בדרך דילוג היא למעלה באין ערוך מההמשכה דסדר השתל' שבסדר והדרגה (עם היות שזהו מעצמות האור כו') והוא שההארה היא ג\"כ בבחי' א\"ס כו', והיינו לפי שבהמשכה שבדרך דילוג יש ג\"כ קצת דביקות (דאל\"כ לא הי' בבחי' אור כו'), ובבחי' האור הבלי גבול ה\"ז בבחי' דביקות להיות ההארה ג\"כ בבחי' א\"ס כו'. וזהו שהקו הגם שנק' מזל שזהו כמו המשכת השערות מ\"מ ה\"ה נוגע ודבוק כו'. וכ\"ז להשטה שהמשכתו הוא מהאוא\"ס הבלי גבול כו', ולפי המבו' כאן לשטה הנ\"ל דשרש הקו הוא מהע\"ס הגנוזות אין ענין הצמצום דומה זל\"ז כו'), דהצמצום שהי' באוא\"ס הוא בבחי' סילוק והתעלמות לגמרי, משא\"כ בהצמצום בשרש ומקור הקו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה משמעות הע\"ח דגילוי הקו גם מבלי שיתעלם האור לגמרי, ומובן ע\"פ הנ\"ל שיש להקו שרש מיוחר בפ\"ע והן הע\"ס הגנוזות, ורק כשהי' גילוי אור הא\"ס לא היו ניכרים. א\"כ הי' מספיק שיתעלם רק אור הא\"ס, והתי' שזהו בשביל התהוות הכלים. והגם דהקו הוא ג\"כ ע\"י הצמצום, הנה לשיטה זו דשרש הקו הוא מע\"ס הגנוזות הצמצום בשביל הקו הוא רק בבחי' מיעוט.</span>\nיט) <b>והענין</b> הוא דהנה נת\"ל פט\"ו דבשרש ומקור הקו כמו שכלול באוא\"ס יש שם ע\"ס והן ע\"ס הגנוזות במאצילן, וענין שהן גנוזות ונעלמות באוא\"ס היינו שהן כלולים ומיוחדים בו שאינן בבחי' מציאות לעצמן להיות בבחי' מציאות ניכרת בפ\"ע במציאות חכ' ובינה כו', ואינם מוסיפים שום ריבוי ח\"ו באוא\"ס ב\"ה, וכמו הנפש שכוללת בה כל הכחות, מ\"מ הנפש אחת היא כו', כמו\"כ הע\"ס אינם מוסיפים ריבוי כו'. דכמו\"כ הוא גם בשרשי הכלים כמו שהן באוא\"ס ב\"ה שאינן בבחי' מציאות ח\"ו, וכנודע דאותיות הרשימו כמו שהן קודם הצמצום אינן במציאות אותיות כלל וכידוע במא' גליף גליפו כו' וכמ\"ש במ\"א, וכ\"ש בשרשי האורות שהן בבחי' בלי מ\"ה כו', וממילא מובן שאין בהם התחלקות להיות חכ' ספי' לבדה ובינה ספי' לבדה כו', דמאחר שבעצם מהותם אינם בבחי' מציאות ממילא ה\"ה בבחי' עירוב ואחדות כו'. ולהבין זה איך הוא שיש שם ע\"ס והרי יש"],[3601330176,"בהם מדרי' הפכים כמו חו\"ג שהן כמו אש ומים (וכן חו\"ב ג\"כ כו'), ובאמת הרי כל כח כמו שהוא עצמי ה\"ה בתוקף ביותר ואיך הם כלולים בבחי' עירוב והתאחדות זע\"ז. הנה באמת זהו למעלה מהשגה, אך זה נראה ונרגש בחוש השכל שהן שם בהתאחדות כו' (ואפ\"ל דענין ההפכיות הוא רק בהתפשטות הדבר שבא בבחי' ציור מוגבל וה\"ה הפכי מציור זולתו, אבל העצם שאינו בא עדיין בציור אין שם ענין ההפכיות. וכמו אש ומים שהאש חם והמים קר ה\"ה הפכים זמ\"ז וא\"א להם להתערב וכאשר מתערבים ה\"ה מתגברים זע\"ז או שהאש לוחכת המים או המים מכבין את האש כו'. וזהו בהתפשטות האש והמים שהן בציור חם וקר, אבל בעצם היסודות הרי נודע דהאש היסודי אינו חם שהרי הי' שורף את העולם כו', וכמו\"כ המים היסודי אינו קר כו'. וע\"כ עם היות שהן עצמיים ואם היו נמשכים (להיות בבחי' מציאות) כמו שהן בעצם הי' בהם תוקף החום והקור ביותר ולא הי' בהם התחברות כלל וכלל כו', מ\"מ כמו שהן בעצמותן הרי אין בהם חום וקור כלל וע\"כ אפשר שיתחברו ויתערבו זע\"ז כו'. וענין ההתערבות אין זה שהן כלולין זמ\"ז\nרק שישכנו יחד שאין האש בפ\"ע והמים בפ\"ע כו', אך זהו לפי השגתינו וידיעתינו שאנו יודעים ההפכיות דאש ומים רק בחום וקור ואנו שוללים זה מהכחות העצמיים כו'. ועיקר הענין הוא שנא' דענין ההפכיות הוא רק בהתפשטות הדבר שזהו ציור הדבר, והעצם בהיותו מושלל מכל ציור עם היות שזה כח האש וזה כח המים יכולים לשכון יחד כו'), שהרי גם בבחי' א\"ק וגם בבחי' עקודים הרי כולם עקודים בכלי א' כו', וכ\"ש באוא\"ס שלפני הצמצום כו'. והעיקר הוא לפי שאינם שם בבחי' מציאות כו' (וכמו אור שכל מופשט שיוכל להתערב עם אור שכל הפכי ממנו, וכמו שני חכמים שתופסים אור שכל א' זה באופן כך וזה באופן אחר, הנה כאשר אומרים את השכל לפ\"ע כח חכמתם העצמי שבא בבחי' הפשטה ובעומק הענין אינו ניכר עדיין במה שהן מחולקים זמ\"ז ויכולים לערבם יחד (והחכמים עצמן שיודעים עומק הענין ופנימיותו ה\"ה מחולקים ומובדלים זמ\"ז, אבל בהתגלות אינו ניכר עדיין ההבדל שביניהם ויכולים להתערב כו'), וכאשר בא אור שכלם בלבושי השגה אז ניכר איך שהן מחולקים זמ\"ז שזה תופס הענין כך וזה כך\nכו', וכמו אור שכל היולי שיוכל לבוא בהשגות שונות כו', וכמשנת\"ל בענין שמאי והלל שקיבלו שניהם מרב א' כו'. ומכ\"ז יובן הדוגמא באוא\"ס ב\"ה דעם היות שיש שם בחי' חכ' ובינה וחו\"ג כו', מ\"מ מצד העדר המציאות שלהם ה\"ה מעורבים ומיוחדים זע\"ז כו'). והמשל בזה ידוע מכחות הנפש שבודאי נמצאים כלולים בעצם הנפש ושם ישכנו כולם יחד, דכמו שהן בהתגלות הרי כל כח הוא בכלי מיוחדת וכמו כח החכ' במוח החכ' וכח הבינה במוח הבינה וראי' בעין כו', וכמו שהן בעצם הנפש הרי ישכנו כולם יחד כו'. ועם היות שהן כחות מובדלים זמ\"ז זה בבחי' אש וזה בבחי' מים ומ\"מ ה\"ה כולם ביחד כו', והיינו להיותם שם בתכלית הזכות והרוחניות לא מיני' ומקצתו כלל מכמו שהן אח\"כ בהתגלות ואינם במציאות ניכרת עדיין וע\"כ שוכנים כולם יחד כו'. וכמו\"כ יובן בענין הע\"ס דעם היות דבהתלבשותן בכלים ה\"ה בבחי' חו\"ג מובדלים זמ\"ז, מ\"מ בעודן כלולים באוא\"ס ב\"ה ה\"ה בבחי' הדקות והרוחניות לאין קץ מכמו שהן אח\"כ ולכן אין שם התחלקות כל בחי' בפ\"ע כ\"א כלולים כולם כא' כו'. ולכן במ\"ת שהי'\nהגילוי מלמעלה מהשתל' ובנפש הו\"ע התגלות הכחות עצמיים, היו רואין את הנשמע ושומעין את הנראה שלא הי' התחלקות בחי' ראי' מבחי'"],[3601330177,"שמיעה כו' (ולכאו' זהו יותר מבחי' התאחדות והתערבות הנ\"ל שהרי כל כח פועל פעולה הפכית כו'. דלעיל נת' דענין ההתערבות הוא רק מה ששוכנים יחד ואינם ניכרים זמ\"ז מפני שאין בהם ציור כו', אבל כ\"א הוא כמו שהוא בעצם מהותו כו', וכאן הרי כח הראי' פעל פעולה הפכית דכח השמיעה כו'. וי\"ל שזהו ג\"כ רק פשיטות הציור וההגבלה, שהרי מ\"מ הי' כאן ראי' ושמיעה, והי' מהכחות עצמים דכח הראי' וכח השמיעה כו'. ומה שראי' תופס דבר גשמי ושמיעה תופס דבר רוחני ה\"ז הציור בהם כו', ובפשיטות הכחות העצמיים היו רואין את הנשמע כו'. ומ\"מ קשה לומר כן שהרי מהות ענין ראי' ושמיעה מה שמחולקים בעצם מהותם הוא שראי' תופס מהות ועצם הדבר, ושמיעה תופס רק מציאות הדבר, וזהו מה שהכחות האלו כשבאים בכלים שלהם הראי' תופסת דבר גשמי דוקא ושמיעה דבר רוחני, שזהו לפי מהות העצמית שלהם שראי' תופס מהות הדבר ע\"כ תופס דבר גשמי להיות שבזה הוא תפיסת המהות ושמיעה תופס דבר רוחני שהו\"ע המציאות כו'. ונמצא מה שמחולקים שזה תופס דבר גשמי וזה רוחני ה\"ז התחלקות בעצם המהות\nשלהם כו'. ובמ\"ת שהיו רואין את הנשמע היינו שהראי' תפס את המציאות ושמיעה תפס מהות הדבר כו' (דכפשוטו שראו את הקולות ה\"ז רק בהציור, ולפי הנ\"ל ה\"ז במהות הכחות כו'), וא\"כ ה\"ז התחלפות הכחות. אך לפ\"ז אינו מובן מהו היתרון במה שראו המציאות כו'. הנה במ\"א מבואר ענין רואין את הנשמע דבחי' הרוחניות המהווה את היש שהוא אצלינו ברחוק היינו רק בבחי' שמיעה והשגה מרחוק הי' אצלם בבחי' ראי' מקרוב, וממילא שומעין את הנראה היינו היש הגשמי הי' אצלם בבחי' שמיעה מרחוק כי כשנגלה הרוחניות נתבטל היש כו', והיינו שראו מהות האין האלקי המהווה שזהו אמיתית הדבר, והגשמי הי' אצלם רק בבחי' שמיעת המציאות שהרי באמת אינו מציאות אמיתי כו' כנודע, וא\"כ אין זה התחלפות הכחות. ולכאורה זהו כענין מ\"ש בסש\"ב ח\"ב אלמלא ניתנה רשות לעין לראות כו', וכמ\"ש במ\"א בענין איזה חכם הרואה שרואה את הנולד מאין ליש כו'. אך לפ\"ז הוא כמו בהנשמה בעצם בכח הראי' ושמיעה שבה קודם התלבשותה בגוף ואין כאן גם התערבות הכחות כו'. אמנם י\"ל שלפי הנ\"ל הפי' דרואין את הנשמע\nהוא שההתחדשות היא בכח השמיעה, והוא שכח השמיעה הי' אצלם כמו כח הראי' בבחי' השגת המהות, והיינו לא בחי' ראי' לבד כ\"א שהשיגו מהות הדבר, וכמו לעתיד ויבין כל יצור כי אתה יצרתו כו', ועמשית\"ל פ'. וצ\"ל דבמ\"ת הי' גילוי מבחי' עצמות א\"ס שלמעלה מע\"ס הגנוזות, וי\"ל שהו\"ע טל תחי' כו', ועי\"ז הי' התכללות הכחות להיות רואין את הנשמע כו'). י\"ל דבחי' ראי' ושמיעה דנשמה קודם התלבשותה בגוף שהוא בחי' ראיית המהות והשגת המהות (וכמו השגת הנשמות בג\"ע), הנה זהו בהאור דהשתל', והיינו בההארה האלקית שבא בבחי' התלבשות בעולם כו' (ובאצי' י\"ל שזהו רק בהארה מאורות דאצילות לא בעצם האור מאחר שיצאו ונפרדו מהכלים כו'). אבל עצם האור ובד\"כ באוא\"ס שלמע' מהתלבשות בעולמות הוא בבחי' ידיעת המציאות לבד כו'. וענין רואין את הנשמע הוא ראיית מהות עצם האור, ושומעין את הנראה שההשגה היא בבחי' השגת המהות, וענין ההתערבות הוא שכל כח אינו מוגדר במהותו דוקא והוא כענין אחליפו דוכתייהו כו' שנת\"ל שזהו מצד פשיטת מקורם כו', וה\"ז יותר מענין ההתאחדות כו'."],[3601330178,"<span data-k=\"ks\"><b>קיצור.</b> וביאור הענין הנה ע\"ס הגנוזות הן בבחי' עירוב והתאחדות, והגם שהן הפכיים במהותם, הנה העצמיים שאינן בהתגלות, אינו ניכר בהם ההפכיות, מפני שאינן בבחי' מציאות, וע\"כ מתאחדים יחד, וכמו שכליים מופשטים, וכמו שכל היולי, וכמו כוחות עצמיים הכלולים בעצם הנפש, וזהו דבמ\"ת היו רואין את הנשמע היינו שהי' הראי' במהות הרוחני, ושומעין את הנראה היינו השגת המהות. </span>\nכ) <b>(והנה</b> בתורה יש מדבר ישוב ושדה, וידוע דתורה בכלל היא בחי' ציור אדם וכמ\"ש זאת התורה אדם כו', והיינו שהתורה היא בחי' פנימי, שזהו ההפרש בין תורה למצות שהמצות הן רצה\"ע בחי' מקיף ותורה היא בחי' חכ' בחי' או\"פ כו'. וענין בחי' המדבר שבתורה י\"ל שזהו התורה כמו שהיא בבחי' ע\"ס הגנוזות, דעם היותן ע\"ס מ\"מ ה\"ה לא בבחי' מציאות ולא בבחי' התחלקות, והיינו מה שבבחי' אדם יש ג\"כ בחי' כי לא אדם הוא כו'. וי\"ל שזהו בחי' סודות ורזין דאורייתא שהן למעלה מהשגה כו', והעיקר בחי' רזא דרזין שבתורה שסתום ונעלם לגמרי כו' וכמ\"ש במ\"א. וממילא בבחי' זו אין בזה תענוג דהתגלות עתיק הוא בבינה בהשגה כו', והרזין דאורייתא שהן למעלה מגדר השגה אין בזה תענוג כו' (וזהו אמיתית בחי' טעמי תורה שיתגלו לעתיד בבחי' תענוג הבלתי מורגש כו' וכמ\"ש במ\"א, ויהי' לעתיד בבחי' השגת המהות כו'). ובחי' ישוב שבתורה הוא שמשיגים אלקותו ית' כו', והו\"ע ידיעת התורה בבחי' ידיעה והשגה שיש בזה טעם ועונג כו'. ושדה הוא שאין בה ישוב אדם ומ\"מ היא לצורך\nהישוב ובכלל ישוב יחשב, וי\"ל שהו\"ע כוונת המצוות דעם היות שזהו ג\"כ השגה מ\"מ אין זה כמו ידיעת התורה שעיקרה השגה כו'. ומבחי' מדבר שבתורה זהו שבא בעשי' בפו\"מ מבלי שירצה בהטעם ותענוג רק לעשות רצונו ית', וז\"ש החפץ לה' כו' שהוא בחי' הטעם כו', כשמוע בקול ה' בקיום בפו\"מ בלי שום טעם כו', וז\"ע בחי' ארץ כנען דארץ סתם הו\"ע מדבר ונק' ארץ כנען שמזה בא בחי' הכניעה עבודה בלי טעם כו'. וזהו היתרון שיש במצות מעשיות על התורה שעי\"ז דוקא נמשך מבחי' עצמות א\"ס ב\"ה שלמעלה מבחי' גילוי כו', דהנה ידיעה והשגה באלקות וגם בחי' העונג הכל הוא בחי' גילוים לבד דאוא\"ס ב\"ה, אבל המשכת העצמות הוא ע\"י עשי' בפו\"מ דוקא בבחי' קבעומ\"ש כו'. ונודע דמ\"מ צ\"ל גילוים ג\"כ וכמו עד\"מ הצמיחה היא מן הארץ בכח עצמה, ומ\"מ כתי' כאשר ירד הגשם כו' והולידה והצמיחה כו' (וכמו שהתגלות המצות הוא ע\"י התורה דוקא כו'), וכמו\"כ בכדי שיהי' הגילוי דמעהמ\"צ מצ\"ע צ\"ל מ\"מ המשכת מ\"ד תחלה שזהו בחי' גילוי אור ועי\"ז יהי' העלאת מ\"ן דמעהמ\"צ מצ\"ע כו'. וזה הי' ענין שילוח\nהמרגלים לתור את ארץ כנען להמשיך בחי' המשכת מ\"ד לעורר את ההעלאת מ\"ן דהארץ כו', ותכלית הכוונה הוא העשי' בפו\"מ שבזה דוקא היתרון אור כנ\"ל, וזהו שנק' ארץ כנען דתכלית הכוונה היא הכניעה בקיום המצוות בפו\"מ דוקא רק שלזה צ\"ל תחלה המשכת מ\"ד כו'.\n<b>והנה</b> המרגלים היו בבחי' השגה וגילוי התענוג, וז\"ש בהם איש אחד למטה כו' בבחי' התחלקות, דבהשגה הרי יש חילוקי מדרי' כו' (ובד\"כ הוא שבחי' הגילוי בא בבחי' התחלקות כו'). וז\"ש ויתורו את הארץ, פי' ויתורו הוא ל' יתרון וכמ\"ש במד\"ר ע\"פ ולתור בחכ' להותיר בחכ' כו', והיינו דהכוונה הוא להיות מזה"],[3601330179,"היתרון בהארץ בבחי' ההעלאת מ\"ן שבכח עצמה להיותה בחי' מדבר כו'. ומרע\"ה הי' בחי' מ\"ה שלא רצה בשום תענוג רק בעבודה תמה הנ\"ל, ורצה להביאם ג\"כ למדרי' זו. וז\"ש וראיתם את הארץ כו', וחשיב ארץ ערים ועם שהן מדבר ישוב ושדה, ארץ מדבר וערים מקום ישוב בנ\"א, ועם הם מדרי' פחותה שההשגה היא מעט כו', ובכולם אומר מה שהכוונה שיהיו בבחי' ביטול דמדבר כו'. והמרגלים לא רצו בהכנעה וביטול זה וע\"כ הוציאו דיבת הארץ כו'. אך כוונת משה הי' להיות בחי' ביטול הנ\"ל ושילוח המרגלים הוא בבחי' המשכת מ\"ד להיות העלאת מ\"ן דהארץ מצ\"ע, וזהו ויתורו להיות בזה יתרון כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה בתורה יש מדבר ישוב שדה, וי\"ל מדבר פנימיות התורה בשרשה מבחי' חכמה דע\"ס הגנוזות, והו\"ע תענוג עצמי הבלתי מורגש (ע' לקמן פ' בענין החכ') וישוב תורה שבהשגה, ושדה כוונת המצוות. ושרש מעהמ\"צ בקבעמ\"ש הוא בבחי' מדבר, וזה\"ע ארץ כנען, רק תחלה צ\"ל המשכת מ\"ד בחי' גילוי (והו\"ע תלמוד מביא לידי מעשה כו'). ובזה ית' ענין שילוח המרגלים וענין ויתורו ל' יתרון כו'.</span>"],[3601330180,"<h3>בס\"ד. ש\"פ קרח, תער\"ב.</h3>\n<b>כל</b> מחלוקת שהיא לש\"ש סופה להתקיים ושאינה לש\"ש אין סופה להתקיים, איזה מחלוקת שהיא לש\"ש כגון מחלוקת הלל ושמאי ושאינה לש\"ש זו מחלוקת קרח ועדתו. וצ\"ל מהו המעלה דסופה להתקיים דלכאו' ענין המחלוקת אין זה מעלה, וא\"כ מה\"ע מחלוקת שלש\"ש שהמעלה בזה שסופה להתקיים. גם צ\"ל שבמחלוקת שלש\"ש חושב הלל ושמאי היינו שני צדדים המחלקים, ובמחלוקת שאינה לש\"ש חושב רק קרח ועדתו ואינו מזכיר את משה, וע\"פ פשוט הוא שהרי משה לא חלק עמהם ורק הם עשו מחלוקת, וגם שגבי משה הי' זה לש\"ש, מ\"מ צ\"ל מהו הענין דבמחלוקת שלש\"ש יש שני צדדים ובמחלוקת שאינה לש\"ש רק צד אחד כו'. ולהבין כ\"ז יש להקדים משנת\"ל דבשרש ומקור הקו כמו שהוא באוא\"ס שלפני הצמצום יש ג\"כ ע\"ס והן ע\"ס הגנוזות במאצילן. ונת' שהע\"ס הגנוזות הן בבחי' התערבות והתאחדות שאין הספי' במדרי' פרטיות אלא כולם הם בבחי' התערבות יחד, והיינו מצד העדר מציאותם שאינם במציאות ניכרת וה\"ה בבחי' פשיטות ע\"כ הם בבחי' התערבות והתאחדות כו'.\nכא) <b>אמנם</b> עדיין צ\"ל איך נא' שהע\"ס הגנוזות הן בבחי' פשיטות שה\"ה ע\"ס עכ\"פ. דהנה זה שישכנו כולם יחד ניחא כמשנת\"ל דענין ההפכיות הוא בהתפשטות וציור הדבר, אבל העצמיות שאינן בהתגלות בעצמותן אינו בבחי' הפכיות, וע\"כ עצמיות הספי' כמו שהן שלא בבחי' המשכה אינם במדרי' הפכיים"],[3601330181,"וישכנו כולם יחד כו'. אבל איך נא' שהן בבחי' פשיטות (שיהי' ההתערבות שלהם מצד הפשיטות שזהו כמו דבר א' כו'), מאחר שהן עכ\"פ ע\"ס עשר ולא תשע כו' (ובבחי' חכ' וחסד כו' באיזה אופן שהוא כו') א\"כ ה\"ז הגבלה, והגבלה ופשיטות ה\"ז ב' הפכים כו'. אך הענין הוא דהנה נת\"ל פט\"ז דע\"ס הגנוזות עם היות שהן שרש ומקור הגבול אין זה בחי' כח הגבול שבא\"ס, דהע\"ס הן ש' הוי' וכתי' אני הוי' הוא שמי שמי המיוחד בי כו', ומאחר שהן בבחי' יחוד ודביקות ה\"ה בבחי' פשיטות דהדביקות בהמקור מחייב שיהי' כמו המקור כו'. וא\"כ הע\"ס הגנוזות שהן בבחי' יחוד ודביקות באוא\"ס הרי צ\"ל בבחי' פשיטות, רק מפני שהן בבחי' גילוי (היינו שכללות האור הוא בבחי' גילוי בעצמותו ית'), וכל גילוי בהכרח שיהי' בו ספירות כו', ויש ב' אופנים בהגילוי (והכל בעצמותו) אם שהגילוי הוא בבחי' בל\"ג שגם בגילוי זה יש ספירות רק שהן בבחי' ספירות אין קץ כו', או שהגילוי הוא להאיר בגבול שבגילוי זה הספירות הן בבחי' ע\"ס כו' וכנ\"ל פי\"ז, ולהיותם בבחי' דביקות באוא\"ס והספירות שבהם הוא מצד\nהגילוי כו', ע\"כ הע\"ס הן ג\"כ בבחי' פשיטות כו' (הגם שזה שהן בבחי' ע\"ס אין זה רק מצד הגילוי לבד, דזה שהגילוי מחייב שיהי' ספירות ה\"ז בבחי' ספירות אין קץ (וכבר נת\"ל פרק הנ\"ל, דבספי' אין קץ הספי' גופא הן בבחי' פשיטות כו', וית' עוד לקמן פ'), אבל זה שהן בבחי' ע\"ס אין זה רק מצד הגילוי כ\"א מה שהכוונה הוא שיהי' ע\"ס וכמשי\"ת בפרק כ\"ז שזהו מה ששיער האוא\"ס להאיר בבחי' גבול כו'. מ\"מ מאחר שכ\"ז הוא בבחי' יחוד ודביקות בהעצם, וזה מחייב שיהיו בבחי' פשיטות כמו העצם כנ\"ל וגם הם בבחי' התכללות בעצמותו ית', וכנ\"ל פי\"ט שעש\"ז נק' גנוזות שהן כלולים ומיוחדים בעצמותו ית', שההתכללות מחייב העדר המציאות שלהם, וידוע דענין ההתכללות הזאת היא עד\"מ כח האש שבאבן החלמיש (ועמשי\"ת לקמן פ' ועמשנת\"ל פט\"ז), וע\"כ הגם שהן בבחי' ע\"ס ה\"ה בתכלית הפשיטות ובתכלית האחדות וההתערבות כו'). וע\"ד אדם קדמון דידוע הקושיא שזהו שם מורכב מב' ענינים הפכים דאדם מורה על החידוש וקדמון הוא בלתי מחודש וא\"כ מהו שם אדם קדמון. ונת' במ\"א שזהו בחי' מח' הראשונה\nעל העולמות שעלה באוא\"ס קדמון לכל הקדומים כו', ולהיות שזהו בחי' אדם שעלה באוא\"ס קדמון לכה\"ק ג\"ז הוא בבחי' קדמון, דהרי בצלם אלקי' עשה את האדם שזהו גם באדם שלמטה וכ\"ש בבחי' אדם העליון בחי' א\"ק שהוא בצלם אלקי' שחשב מח' זו כו', וזהו ש' א\"ק דעם היותו בבחי' אדם מ\"מ ה\"ה בבחי' קדמון כו' (ומבו' במ\"א דבחי' א\"ק עם היות שכלול שם כל דבר בפרט וכמא' צופה ומביט כו', מ\"מ אין שם התחלקות כלל אפי' בהעלם, וכמו הרקיע שמתחלק למעלות והוא עצם א' כו'). ועד\"ז יובן כאן במכש\"כ בהע\"ס הגנוזות כמו שהן באוא\"ס שלפני הצמצום דעם היותם בבחי' ע\"ס מ\"מ הם בבחי' פשיטות והן בבחי' התערבות והתאחדות ממש כו', שהרי גם בחי' מו\"ס היא בבחי' פשיטות לגבי בחי' ח\"ע דאצי', וכן אור החכ' הוא בבחי' פשיטות לגבי כלי החכ' כו' וכמשנת\"ל פי\"ד, וכ\"ש באוא\"ס שלפני הצמצום הרי שרשי האורות הן בבחי' פשיטות ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולכאורה איך הע\"ס הגנוזות בבחי' פשיטות לגמרי מאחר שהן עשר, הענין להיות שהן שרשי האורות ה\"ה בבחי' דביקות בהעצם וכמו העצם.</span>"],[3601330182,"<b>וגם</b> כ\"ז הוא בבחי' התכללות בעצמותו, ע\"כ הם בבחי' פשיטות ובבחי' התערבות והתאחדות ממש, וע\"ד בחי' א\"ק.\nכב) <b>והנה</b> באופן כזה כמו שהן בעצמותו ית' א\"א שיומשכו בעולמות, והוא שהעולמות גם העולם היותר נעלה אינו יכול לקבל אור פשוט כזה כו', ועוד שאם היו נמשכים הע\"ס הגנוזות כמו שהן באוא\"ס שלפני הצמצום היו נמשכים כולם יחד, וכמו כחות הנעלמים בנפש שנמשכים כולם ביחד כו'. וכידוע דכחות הגלוים אופן המשכתם הוא בסדר והדרגה בקדימה ואיחור דתחלה הוא המשכת המוחין ואח\"כ המשכת המדות, דא\"א להיות התגלות המדות בלי קדימת המוחין כו', והיינו במדות שע\"פ טו\"ד שא\"א להיות התעוררות המדות כ\"א ע\"י קדימת ההשגה תחלה, ודוקא כאשר נפסק גילוי אור המוחין אז יהי' תולדת המדות, דבעת התגלות המוחין א\"א להיות התגלות מדות כו'. ובהתגלות כחות הנעלמים אינו כן דבעת התגלות אור המוחין אפשר להיות התגלות המדות, וכמו בעת השמחה שמתגלים כחות הנעלמים אין התגלותם בסדר והדרגה בקדימה ואיחור, דבעת התגלות המוחין יכול להיות התגלות המדות ואור המוחין מתגלים אז ביותר, וכמו שאנו רואין בחוש שבעת השמחה יכול להשכיל ענינים נעלים ביותר, וכמה ענינים שלא\nהיו מתיישבים אצלו ולא הבינם ובעת השמחה יבוא עליהם. והיינו מפני שמאיר ומתגלה אז פנימית ועצמית אור השכל כו', ומ\"מ בעת ההיא ממש יהי' ג\"כ התגלות המדות וגם המה בתוקף הגילוי ואינם מבלבלים לאור המוחין כו'. והיינו משום דכחות הנעלמים אינם מקבלים זמ\"ז כ\"א כולם מקבלים ונמשכים מעצם הנפש, וע\"כ אין בהם סדר והדרגה ונמשכים כולם כא' כו'. ובדוגמא כזאת יובן למעלה דהע\"ס הגלויות המשכתם הוא בסדר והדרגה בבחי' קדימה ואיחור דתחלה הוא המשכת והתגלות המוחין דהיינו אצי' בחי' חו\"ב כו' ומחו\"ב נאצל ז\"א כו', ודוקא לאחר שמתמעט האור דחו\"ב נאצל בחי' ז\"א כו' וכמ\"ש במ\"א. וכ\"ז הוא מפני שנמשכים ומקבלים זמ\"ז ממילא בהכרח שיהי' סדר והדרגה באופן המשכתם כו', אבל הע\"ס הגנוזות ונעלמים באוא\"ס אינם נמשכים ומקבלים זמ\"ז כ\"א כל הע\"ס נמשכים מבחי' עצמות אוא\"ס ב\"ה, ואם יהי' התגלות הע\"ס העצמיים כמו שהן יהי' התגלות כולם כא', וכולם בבחי' תוקף האור והגילוי באופן שלא היו כלל בבחי' אור פנימי בבחי' התלבשות אורות בכלים וגם לא הי' אז ענין ההשתל'\nכלל, שהרי לא היו הספירות משתלשלים זמ\"ז אלא היו כולם מקבלים ונמשכים מבחי' אוא\"ס בשוה כו', וממילא לא הי' ג\"כ ענין ההתכללות, וכנודע דהתכללות הספי' זה מזה וזה עם זה שייך דוקא כשהן בבחי' הגבלה ובבחי' התלבשות בכלים כו', אבל בכחות הבלתי מוגבלים אינו שייך ענין ההתכללות כו' וכמ\"ש במ\"א, אשר לא כן הי' כוונת המאציל עליון ב\"ה דכוונת המאציל הוא שיהי' בחי' או\"פ התלבשות אורות בכלים דוקא ויהי' בחי' ההשתל' וההתכללות כו' וכמ\"ש במ\"א. וע\"כ הי' הצמצום באוא\"ס ב\"ה בשרשי האורות להיות נמשכים ספי' מיוחדות שלא יהיו בבחי' התערבות והתאחדות כו', וכמו שמבחי' החכ' הכלולה בא\"ס ב\"ה נמשכה בחי' החכ' בהתגלות, ונמשכה בפ\"ע שלא תהי' בבחי' התערבות עם ספי' אחרת שעי\"ז נעשה החכ' בבחי' ניכרת להיות בבחי' אור החכ' כו', ולא שנעשה ניכרת בבחי' היכר עצמי ח\"ו, היינו להיות בבחי' שינוי המהות לגבי שרשה ומקורה, כי"],[3601330183,"היא אותה החכ' ממש כמו שהיא במקורה, רק שע\"י שנחלקה משארי הספי' ונתגלה ממקורה, הרי נעשית בבחי' מדרי' ניכרת כו' (ואין זה כמו בהתהוות הכלים שנת\"ל פ\"י, די\"ל שלגבי שרשן ומקורן בחי' כח הגבול כמו שהוא לפני הצמצום הכלים הן באין ערוך לגמרי כו', אבל באורות גם לאחר הצמצום אינן באין ערוך לגבי שרשן ומקורן כו', וענין הצמצום הוא רק שיהי' התגלות האור ובבחי' אור פרטי בפ\"ע שעי\"ז נעשה בבחי' מציאות ניכרת ובבחי' מיעוט האור והגילוי כו'. והענין הוא דההתגלות גורם מציאות הדבר כו' וגם אם הי' ההתגלות באופן שיהיו כולם יחד היו בבחי' מציאות ניכרת כו', וכמו בהתגלות כחות עצמיים הרי בהתגלות שלהם נעשים בבחי' מציאות ניכרת לגבי כמו שהן קודם ההתגלות כו', וכמו\"כ בהספי' גם אם הי' ההתגלות כולם ביחד היו בבחי' מציאות (ומובן שלא הי' בבחי' מציאות כמו בהתגלות מדרי' פרטיות כו'), אבל הי' בהם אז ריבוי אור כו', וע\"י שנמשך רק ספי' אחת בפ\"ע ה\"ה בבחי' מיעוט האור כו'. וכמשל אור וזיו השמש שבסש\"ב דבגוף כדור השמש הוא ביתר שאת כו' בבחי' ריבוי\nהאור ובהתגלות מתמעט האור כו', ומ\"מ אין זה בבחי' שינוי המהות שהוא הוא האור הקדום כו'. ונמצא ההיכרות דספי' החכ' שע\"י ההתחלקות אין זה רק בעצם מהותה להיות בבחי' חכ' ניכרת, כ\"א גם בבחי' מיעוט האור, ועי\"ז היא בבחי' אור החכ' שיכולה להתלבש אח\"כ בכלי כו').\n<span data-k=\"ks\"><b>קיצור.</b> והנה אם הי' התגלות הע\"ס הגנוזות שלא ע\"י צמצום, היו מתגלים כולם יחד בלי סדר והדרגה בקדימה ואיחור, ובריבוי האור ולא היו בבחי' או\"פ ולא הי' ענין ההשתל' וע\"כ הוצרך הצמצום, וענינו הוא שיהי' התגלות ספי' פרטיות כמו ספי' החכ' בפ\"ע, ועי\"ז נעשית במדרי' ניכרת ובבחי' מיעוט האור. </span>\nכג) <b>והמשל</b> בזה כמו בקיבוץ וצירוף ג' או ד' אותיות יחד נעשה מהם תיבה א' אשר היא כלי להשכלת איזה ענין שהשכלה זו מובנת מתוך אותיות אלו, עד\"מ תי' ברוך שבצירוף ד' אותיות יחד מושג ומושכל בזה ענין ברכה שהוא שמברכו איש שיגדל ויתרבה טובו וחייו ה\"ז השכלת ענין ממש. וגבי ברכה העליונה מרומז שרש ומקור הברכה בתי' ברוך וכמ\"ש בת\"ז דברוך ר\"ת ראש ומקור כל ברכה, והיינו שרש הברכה שנמשך מבחי' הכתר כו', ובזהר פ' עקב דרע\"א ע\"א דברוך הוא בחכ' ובד\"כ הוא בחי' יסוד אבא וכמ\"ש במאו\"א. ויש הפרש בין ברוך לברכה דאיהו ברוך בחי' יסוד אבא ואיהי ברכה בחי' יסוד אימא, ויש הפרש בין ברוך דברכת השחר וברכת המצות ובה\"נ שהן מלמעלמ\"ט וברכת העמידה מלמטלמ\"ע וכמ\"ש בפע\"ח, ועמ\"ש הרמ\"ז בזהר שם ועמ\"ש בלק\"ת ד\"ה קא מיפלגי כו' ובסי' בפי' ברוך שאמר, הרי שבתי' ברוך יש בזה השכלה גדולה. והנה כשמתחילין ללמוד לתינוק שאינו מבין צירוף אותיות יחד ומלמדין אותו אות א' לומר זה אות פלוני, שמראין לו רק אות ב' לבד מתי' ברוך, וה\"ז צמצום לגבי\nהמלמד, והצמצום הוא שלא יהי' הב' יחד עם ג' אותיות רו\"ך שאין זה לפי הבנת התינוק כ\"א יהי' נמשך בפ\"ע כו', ובהתחלקות זאת שנמשך אות ב' לבד הרי ירד בזה הרבה ממדריגתו שנסתלק ממנו האור ולא נשאר בו רק מעט מן המעט מהאור שהי' בו. שהרי מתחלה כשהי' מצורף בתי' ברוך הי' בו ההשכלה דברוך כנ\"ל, ומכ\"ש אם"],[3601330184,"תי' ברוך הי' מחוברת תחלה עם עוד תי' כמו ברוך שאמר והי' העולם, שהי' מובן מהם השכלה מופלאה והוא איך שבמאמר לבד נבראו כל העולמות בלי עמל ויגיעה, אלא ע\"ד הוא צוה ונבראו כו', ובשרשו הוא בחי' אמירה דא\"ק שנבראו בו כל העולמות בהשוואה כו' וכמ\"ש בסי' בפי' ברוך שאמר, ומה שמברכים אותו ית' בברכה זו הוא שיהי' הגילוי דאמירה זו למטה כו', והו\"ע גילוי בחי' מאמר א' הכולל הט' מאמרות כו'. וכשמפרידים אות הב' בפ\"ע הרי אין בו כל ההשכלה ההיא רק מפני שכבר הי' בה ההשכלה נשאר ממנו קצת בהאות (והוא בבחי' רשימו בלבד, ולפי הנושא בהדוגמא מזה בהענין שאנו בו הוא בבחי' מיעוט לבד לא בבחי' סילוק ושנשאר רק רשימו כו', והיינו כי ענין האותיות הוא כמשל הכלים כו' ומ\"מ י\"ל שגם בזה יש ב' ענינים, היינו מה שבבחי' מיעוט לבד ויש בזה גם מה שבבחי' סילוק וכמשי\"ת). ואעפ\"כ זה הב' הוא אותו הב' ממש שהי' בתי' ברוך והוא עצמו הב' המובן לגדול שמושג בו ענין הברכה באיזו מדרי' שהיא או ענין ברוך שאמר והי' העולם כו'. ועד\"ז יובן ענין הצמצום שהי' בהע\"ס\nהגנוזות באוא\"ס ב\"ה שבתחלה היו כל הע\"ס בהתאחדות והתערבות דלבד מה שהיו לא בבחי' מציאות ניכרת כנ\"ל (דאל\"כ א\"א להיות התאחדותם יחד כו'), הי' מאיר בהם אור מופלא ונעלה מאד, ולא הי' ביכולת העולמות אפי' היותר עליונים לקבל התגלות הע\"ס כמו שהן בא\"ס ב\"ה (הן מצד עצם מעלתן שהיו בבחי' פשיטות לגמרי והן מצד האור והגילוי שבהם כו'), אם לא ע\"י הצמצום שיהי' נמשך רק בחי' חכ' בפ\"ע, ואע\"פ שהיא ממש בחי' החכ' שהיתה כלולה בא\"ס ב\"ה עם כל הע\"ס הגנוזות, מ\"מ כשנמשכה בפ\"ע ואינה מעורבת עם שארי הבחי' ה\"ז ירידה ממדריגתה (דלבד הירידה שע\"י עצם ההתגלות שעי\"ז נעשה בבחי' מציאות דבר וכנ\"ל פכ\"ב, ובפרט כשנמשכה ונתגלה בפ\"ע שנעשה בבחי' מציאות דבר ואינה בבחי' פשיטות ממש כמו שהיתה קודם, דהעדר הפשיטות ה\"ז ג\"כ התעלמות האור שאינו מאיר בה בחי' פנימיות אורה בגילוי כו', עוד זאת) שנתעלם האור שהי' מאיר בהם כשהיו מתאחדים יחד כו'. וכמו המשל באות ב' הנ\"ל שכשהי' בתי' ברוך הי' בו ההשכלה דברכה כנ\"ל, וכשנפרד אין בו מהשכלה הזאת רק מעט ורושם בלבד כו' כנ\"ל, כמו\"כ כשנמשכה ספי' החכ' לבד אין בה רק מעט מהאור הקדום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וע\"ד משל תי' ברוך שמלובש בה השכלה, וכשמפרידים אות ב' בפ\"ע אין בו רק מעט מהשכל שהי' מלובש בו, וה\"ה אותו האות הקודם, וכמו\"כ החכ' ע\"י שנבדלה בפ\"ע הנה לבד שיצאה מפשיטותה ה\"ה בבחי' מיעוט האור. </span>\nכד) <b>והנה</b> במשל דאותיות כן הוא שבתחלה הי' בזה השכלה מופלאה וכשמפרידין האותיות מסתלק האור ונשאר רק רושם לבד כו'. ולכאו' זה יצדק אם נא' דהע\"ס הגנוזות הן שרשי הכלים, ועם היות שבאוא\"ס שלפני הצמצום הן בבחי' העדר המציאות לגמרי, מ\"מ להיותן שרשי הכלים שייך לומר דוגמא הנ\"ל כמו בתי' ברוך כו'. אבל לפי המבואר כאן שהע\"ס הגנוזות הן שרשי האורות מה שייך לומר כמו בהמשל שבתחלה נושא ההשכלה וכשנפרד האות אין בו מההשכלה כ\"א מעט כו' מאחר שהכל הוא בחי' האור כו'. אך הענין הוא דהנה ידוע דבאור יש פנימיות וחיצוניות (ע' משי\"ת לקמן פ'), וכמו\"כ בשרשי האורות"],[3601330185,"יש ג\"כ בחי' פנימיות וחיצוניות דהגם שהן בבחי' פשיטות, מ\"מ כל מה שיש בההתגלות יש ג\"כ בשרש ומקור וכמ\"ש במ\"א. ומאחר שבאורות הגלוים יש פנימיות וחיצוניות בהכרח לומר שכן הוא גם בשרשן ומקורן כו', וע\"כ שייך לומר שבהתאחדות כולם הי' בהם אור נעלה יותר היינו בחי' אור פנימי יותר כו'. ועוי\"ל דהנה נת\"ל פט\"ז דשרשי האורות הוא בחי' ש' הוי', והנה בהאורות המתלבשים בכלים דבכולם הוא ש' הוי', הרי נודע שיש חילוקי' בהשם הוי' בהניקוד שבו וכמו בכתר ש' הוי' בניקוד קמץ ובחכ' בניקוד פתח כו', גם יש בחכ' ש' ע\"ב ובבינה ש' ס\"ג כו'. וידוע דהשמות הן לבושים אל האורות (וע' משי\"ת לקמן פ') שעי\"ז הוא התחברות האור עם הכלי כו'. וכמו עד\"מ שם האדם דנראה בחוש ששמו הוא חיותו דכשקוראין לאדם בשמו אפי' טרוד ה\"ה נפנה תיכף לקורא אותו, וידוע שגם בהתעלפות גדולה ר\"ל יכולים להחזיר ע\"י קריאת השם כו'. אך ג\"ז מובן שהשם אינו שכלו דהיינו נשמתו, דהרי קודם שבאה הנשמה בגוף אינה צריכה לשום שם, וכמ\"ש בלק\"ת ד\"ה מי מנה פ\"א במ\"ש ולאדם לא מצא עזר דעזר הוא\nהשם, והנשמה קודם התלבשותה בגוף לא הי' לה שם, רק כשמתלבשת בגוף אז צריכה לשם כו', והיינו דהשם הוא שמקשר את הנשמה עם הגוף כו'. וכמו\"כ למעלה ענין השמות הוא לקשר את האור עם הכלי כו', ובאוא\"ס שלפני הצמצום שיש שם התכללות שרשי האורות נכללו שם ג\"כ השמות דהאורות דע\"ס כו', וכמ\"ש במ\"א דמש\"א הי' הוא ושמו זהו באוא\"ס קודם עלות הרצון שהוא בחי' שם א' (והיינו כמו שנת\"ל פי\"ז דקודם עלות הרצון הוא בחי' ספי' אין קץ בבחי' פשיטות כו'), אבל בעלות הרצון הוא בחי' שמות ל' רבים כו'. ובבחי' השמות שייך לומר דבהצטרף כל השמות יחד מאיר בהם אור עליון יותר וע\"י ההתחלקות מתמעט האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> איך יצדק משל האותיות על שרשי האורות. הענין הוא דגם באורות יש פנימיות וחיצוניות ועוד שהן בחי' שמות, דבעלות הרצון הוא בחי' שמות ל' רבים כו'. </span>\nכה) <b>אך</b> י\"ל דכמו המשל הנ\"ל באות ב' מתי' ברוך אפשר יש לבאר הענין ע\"פ משל אחר בדומה לזה, ויובן בזה איך שבהתאחדות כולם יש בהם אור עליון כו'. והוא דהנה עד\"מ כל ענין שכלי הרי יש בו ענינים רבים שבהם מובן הענין שכלי, והיינו מה שהשכל מתחלק לפרטים רבים, וכמשנת\"ל פ\"ד שא\"א לענין שכלי שלא יהיו בו פרטים כו' שבכל אלו הפרטים מובן השכל כו', ובהם יש פרטים שהם פנימיים יותר מפרטים אחרים שהן בבחי' חיצוניות כו'. והנה בהשפעת השכל מהמשפיע אל המקבל הרי א\"א להשפיע לו כל הפרטים ביחד הן מצד המשפיע א\"א שיושפע הכל יחד והן מצד המקבל כי לא יוכל לקבל הכל ביחד, כ\"א משפיע לו כל פרט בפ\"ע עד שנמשכים לו כל הפרטים כו'. והנה גבי המשפיע שכבר היו כלולים בשכלו כל הפרטים הרי כבר ידוע לו הענין שכלי הבא מהפרטים האלו, אבל המקבל כשידוע לו רק פרט א' או ב' מהם הרי אינו יודע עדיין את הענין שכלי, ומ\"מ בכל פרט שבו כבר יש חלק מהשכל שיש בשכל המשפיע לבד השכלי של הענין הזה הפרטי, דהרי הענין הפרטי הוא ענין שכלי פרטי ומכל הפרטים יחד מובן ענין שכלי"],[3601330186,"שזהו עצם השכלי המובן מאלו הפרטים, ובכל פרט בפ\"ע הרי לבד השכלי הפרטי של הענין הפרטי הזה יש בו חלק מעצם השכלי המובן מכל הפרטים, רק שהוא בבחי' מיעוט לגבי כמו שהוא בשכל המשפיע, והמיעוט אפשר להיות בב' אופנים, או שהמקבל אינו יודע ומבין עדיין כלל את עצם השכלי שיבוא מהפרטים, ומ\"מ הגם שהמקבל אינו יודע מ\"מ יש חלק ממנו בכל פרט, או שגם המקבל מבין את עצם השכלי אבל הוא במיעוט לגבי ידיעת המשפיע, מאחר שאינו יודע את הפרטים והפרטים הרי המה שמביאים את עצם השכלי, וע\"כ המשפיע שכבר יודע כל הפרטים ה\"ה יודע בטוב ובבירור את השכלי הבא מכל הפרטים האלו ומאיר אצלו השכל המושג והמובן מהפרטים בגילוי בכל פרט ופרט, משא\"כ אצל המקבל מאחר שאינו יודע עדיין את השכל (רק מקצת ממנו כו'), ממילא ה\"ז אצלו בבחי' מיעוט האור כו', והיינו שידיעתו בהעצם השכלי בכללותו הוא במיעוט וגם מה שבכל פרט יודע את עצם השכלי שבא מזה הוא בבחי' מיעוט האור כו' (והא בהא תליא כו'), ומ\"מ הרי כל פרט הוא חלק מהענין שכלי כו'. והנה כאשר יבואו כל הפרטים הגם שאז\nיודע גם המקבל את הענין שכלי ומאיר אצלו הענין בהפרטים, מ\"מ יש בזה הפרש גדול מכמו שהי' בשכל המשפיע קודם ההשפעה לכמו שהוא אצל המקבל, דהרי גבי המשפיע היו הפרטים בבחי' הדקות והרוחניות בבחי' הפשטה וע\"כ מאיר אצלו דקות הענין ואור רב בהפרטים, משא\"כ גבי המקבל שהפרטים אצלו בבחי' הלבשה בלבושי השגה ע\"כ גם כשמקבל כל הפרטים ומאיר אצלו הענין בהם אין זה בבחי' דקות ובריבוי אור כ\"כ כו', ואין הכוונה כאן על עומק ופנימיות השכל כ\"א על השכל המושג ומובן בהענין שאצל המשפיע מאיר בהפרטים ריבוי אור ובעילוי המדרי' ואצל המקבל אין האור בריבוי ובעילוי כ\"כ כמו אצל המשפיע כו'. והדוגמא מזה י\"ל בענין הע\"ס, דהנה יש כוונה פנימיות במאציל עליון ב\"ה בענין האצי' בכלל ומה שנאצלו ע\"ס דוקא עשר ולא תשע ולא י\"א, שע\"י אצי' הע\"ס דוקא באה הכוונה הזאת כו', ועמ\"ש מזה בפרד\"ס שער טעם האצי' ובשער שם בן ד' פ\"א, ובע\"ח שער הכללים כ' כדי להטיב לברואיו ויכירו גדולתו ויזכו להיות מרכבה להדבק בו ית' כו', ובשער עגו\"י כ' להוציא לאור פעולותיו ושמותיו\nכו' וכמ\"ש מזה במ\"א. וקודם שנאצלו ונתגלו הע\"ס היו כלולים באוא\"ס המאציל והן הע\"ס הגנוזות שהן שרשי האורות הכלולים בא\"ס ב\"ה כמו שנת\"ל, ויש בהם כוונת המאציל עליון ב\"ה בענין הע\"ס כו'. וכבר נת' שהע\"ס כמו שהן בא\"ס ב\"ה ה\"ה בתכלית הפשיטות והן כולם כלולים יחד ומאיר בהם כוונת המאציל בגילוי ממש בבחי' אור נעלה ומופלא כו' (וכמו שנת\"ל במשל דגבי המשפיע שכלולים בשכלו כל הפרטים מאיר אצלו הענין שכלי בגילוי ממש בהפרטים כו', ובפרט כמו שהפרטים הם בבחי' התאחדות והתערבות יחד כו'), וע\"י הצמצום כשנמשכה ספי' א' בפ\"ע הרי אין בזה עדיין שלימות הכוונה שבהע\"ס, ומ\"מ יש בה חלק מזה רק שהוא בבחי' מיעוט האור כו', וכאשר נאצלו כל הע\"ס ויש בהם שלימות הכוונה מכוונת המאציל ב\"ה באצי' הע\"ס כו', מ\"מ הוא בבחי' מיעוט האור לגבי כמו שהיו בבחי' פשיטות ממש כשהיו כלולים בא\"ס ב\"ה, דהרי בהאצילות וההתגלות נעשו בבחי' מציאות ניכרת עכ\"פ כו'. המובן מהמשל דאות ב' הוא מיעוט האור הפרטי של הספי' בפרט, והמובן מהמשל דהפרטי' שבשכל הוא המיעוט בכוונת\nהמאציל בענין אצילות הספי', והכל הוא בבחי' או\"פ כו'. וענין הבנת השכל מחלק א', י\"ל דמאופן אצי' ספירת החכ'"],[3601330187,"כבר נודע הכוונה בענין הספי' שיהי' בחי' או\"פ בגין דישתמודעון בי' כו'. גם כמשי\"ת לקמן דמאצי' חו\"ב הוא שיהי' השגת אלקות בעולם, ואצי' המדות הוא שיהי' הרגישות אלקות כו'. ועמ\"ש בהבי' דוהניף דבהתכללות הספי' מאיר בהם בחי' אוא\"ס שלימותא דכולהו כו', י\"ל דהיינו שיהי' בהם הגילוי כמו שהוא בשרשי האורות כו'. וע\"פ הנ\"ל יובן המשנה דכל מחלוקת שהיא לש\"ש, דהנה ידוע שיש ב' מיני התחלקות, הא' התחלקות שהיא סיבת ההתכללות והיינו בהתחלקות הספי' במדרי' פרטיות שזהו סיבה להתכללות הספי', וכמשנת\"ל שבאם הי' ההתגלות שלהם כמו שהן בשרשן לא הי' ענין ההשתל' וההתכללות כו', רק ע\"י הצמצום בהע\"ס שנמשכו ספי' פרטיות ובבחי' מיעוט האור ה\"ה משתלשלים זמ\"ז ויש בהם התכללות כו'. וז\"ע מחלוקת שהיא לשם שמים דהיינו כפי אמיתית הכוונה להיות בחי' ההתכללות כו'. וגם פי' לשם שמים דשם הוא בחי' מל' ושמים בחי' ז\"א כנודע, ובכדי שיהי' בחי' משפיע ומקבל והיינו דז\"א הוא בחי' משפיע ומל' בחי' מקבל זהו דוקא ע\"י התחלקות הספי' במדרי' פרטיות כו'. וההתחלקות הב'\nהוא שההתחלקות היא סיבת הפירוד, והוא כמו ההתחלקות דספי' דתהו שנמשכו כמו שהן בשרשן בבחי' ריבוי אור ונמשכו להיות בבחי' מציאות דבר, שעי\"ז נעשה הפירוד בבחי' ענפין מתפרדין שא\"א להיות ההתכללות ואדרבה אינם סובלים זא\"ז כו'. וזהו מחלוקת שאינה לש\"ש שאין זה כפי הכוונה ועי\"ז נעשה הפירוד בין שם לשמים כו'. וזהו כל מחלוקת שהיא לש\"ש סופה להתקיים שיהי' בבחי' קיום מאחר שזהו תכלית הכוונה כו', וגם שע\"י התכללות מאיר גילוי אור עליון יותר שז\"ע הקיום ע\"י הגילוי דעצמות אוא\"ס ב\"ה, אבל מחלוקת שאינה לש\"ש אין סופה להתקיים מאחר שזהו היפך הכוונה, וגם מחמת הפירוד בהכרח שיתבטל וכמו בתהו כו'. ואו' איזה הוא מחלוקת הלל ושמאי שזהו מחלוקת שע\"פ התורה שהיא בחי' התחלקות דתיקון כו'. וגם ענין מחלוקת דהלל ושמאי הכל הוא בבחי' היחוד דז\"א ומל' רק המחלוקת היא אם היחוד הוא בדרך מלמטלמ\"ע שז\"ע שמאי מל' השם אורחותיו או בדרך מלמעלמ\"ט שזה\"ע הלל בחי' חסד כו'. ומחלוקת זו סופה להתקיים שעי\"ז נעשה היחוד דז\"א ומל' (וכן התכללות הע\"ס בכלל כו') שזהו\nעיקר המכוון כו'. וגם להוי כדין וכדין כו', שלעתיד יהיו ב' המדרי' וכמ\"ש בלק\"ת ד\"ה ושמתי כדכד. ומחלוקת שאינה לש\"ש היא מחלוקת קרח ועדתו שכל כוונתו הי' להפריד בין שם לשמים כו', וזהו שנק' אנשי שם ע\"ד ונעשה לנו שם שנא' בדור הפלגה שרצו להפריד בין ז\"א ומל' כו'. ואין סופה להתקיים להיות שזהו היפך הכוונה כו', וגם כי לא ידח ממנו נדח כו' ובהכרח להתברר כו'. וזהו שבמחלוקת שלשם שמים נא' ב' צדדים הלל ושמאי שזהו ב' אופנים בענין היחוד כו', אבל במחלוקת שאינה לש\"ש נא' רק קרח ועדתו שרצו להפריד כו', וע\"כ אין סופה להתקיים כו', אבל מחלוקת שלשם שמים סופה להתקיים שזהו תכלית הכוונה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> י\"ל עוד משל כמו ענין שכלי שמובן בריבוי פרטים דוקא, והמשפיע שיודע את כל הפרטים יודע את השכלי, ובהתגלות אל המקבל הרי כל פרט בפ\"ע שבכ\"א יש חלק ועצם השכלי הוא בבחי' מיעוט האור, אפילו אם המקבל מבין קצת את השכלי, וגם כשנתגלו כל הפרטים הרי אצל המשפיע בעצמות</span>"],[3601330188,"<b>שכלו</b> מאיר אור רב לפי אופן דקות הענינים משא\"כ אצל המקבל, והדוגמא מזה למעלה דכוונת המאציל בענין הספי' (ודוקא בע\"ס שאינם רק מצד הגילוי כו' וכמשי\"ת), הנה בשרשי האורות שהן בפשיטות ובאחדות מאיר אור נעלה ומופלא, וכשנתגלה רק ספי' פרטית ה\"ז בבחי' מיעוט האור וגם כשנאצלו כולם ה\"ז בבחי' מיעוט, ובזה ית' המשנה דכל מחלוקת שהיא לש\"ש כי התחלקות הנ\"ל היא סיבת ההתכללות כו'."],[3601330189,"<h3>בס\"ד. ש\"פ חקת, תער\"ב</h3>\n<b>וידבר</b> ה' אל משה ואל אהרן לאמר זאת חקת התורה אשר צוה ה' לאמר, וצ\"ל מה\"ע אשר צוה ה', דלכאו' הול\"ל אשר אנכי מצוה שהרי כבר נא' וידבר ה' ומהו עוד אשר צוה ה' כו'. גם צ\"ל מה שפרה אדומה חלוקה מכל הקרבנות שכולם מעשיהם בפנים דוקא ופרה אדומה מעשי' דוקא בחוץ רק שהזאת הדם צ\"ל נוכח פני אוהל מועד, גם מפני מה כל מעשי' דוקא ע\"י אלעזר הכהן כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דהע\"ס הגלוים הנמשכים מהע\"ס הגנוזות במאצילן דהיינו שרשי האורות הכלולים באוא\"ס שלפני הצמצום המשכתם הוא ע\"י הצמצום, ונת' ענין הצמצום הזה הוא דבאוא\"ס שלפני הצמצום הרי כל הע\"ס הן בבחי' התאחדות והתערבות והיו אז במדרי' גבוה ונעלה ביותר בעצם שלא היו בבחי' מהות ומציאות ניכרת לעצמן, וגם בהתאחדות הי' מאיר בהם אור נעלה שלמעלה מהאורות עצמן כו', וענין הצמצום הוא שנמשכה ספירה פרטיות כמו ספי' החכ' בפ\"ע שעי\"ז ירדה ממדרי' שנעשית בבחי' מציאות ניכרת (שזהו בחי' מיעוט והעלם האור בעצמה כו') וגם שנתמעט האור הנעלה שהי' בה בהתאחדות כולם כו'. ונת' המשל מתי'\nברוך שיש בו השכלה וכשמפרידין אות אחת עם היות שזהו אותו האות ממש מ\"מ הרי אין בו ההשכלה כו'. ונת' עוד משל כמו ענין שכלי שבא בריבוי פרטים הרי פרט הוא שכל פרטי, ומכל הפרטים יחד מובן הענין השכלי שמתבאר ומובן מהפרטים האלו, ובהשפעה בא כל ענין פרטי בפ\"ע דלבד זאת שאותו הענין כמו שבא בהשפעה והתגלות אינו כמו שהוא אצל המשפיע, הנה מה שיש בו מהענין השכלי המתבאר ומובן מכל הענינים הוא בבחי' מיעוט לבד בכל ענין פרטי אף שנמצא בו גם כמו שהוא ענין פרטי בפ\"ע כו', וגם לאחר שהמקבל יודע כל הפרטי' אין הענין מאיר אצלו בגילוי ממש כמו אצל המשפיע כו'.\nכו) <b>והנה</b> בסש\"ב ח\"ב פי\"ב כ' וז\"ל כי כל אות הוא המשכת חיות וכח מיוחד פרטי וכשנצטרפו אותיות הרבה להיות תיבה אזי מלבד ריבוי מיני כחות וחיות כו' עוד זאת העולה על כולנה המשכת כח עליון וחיות כללית הכוללת ושקולה כנגד כל מיני הכחות והחיות פרטית של האותיות ועולה על גביהן והיא"],[3601330190,"מחברתן ומצרפתן יחד כו' עכ\"ל. והנה מ\"ש דכל אות הוא המשכת חיות מיוחד נראה שאין הכוונה רק על החיות דהאות עצמו דלמעלה הוא החיות דהכלים עצמן לבד האור המתלבש בתוכן כו', כ\"א שבכלל זה הוא גם האור המתלבש בהאותיות כו' כן משמע בהג\"ה שם. ומ\"ש דהעולה על כולנה הוא המשכת כח עליון וחיות כללי המחבר ומצרף כל האותיות נראה שאין זה מהאור השכל המתלבש בהאותיות כ\"א מלמעלה ממנו כו' (ואפשר בכלל זה גם האור המתלבש, אמנם נראה ברור שאין הכוונה על האור הזה לבד כ\"א על אור עליון ומובדל כו'), שהרי כל אור שכל שמתלבש באותיות הרי אינו מוכרח שיהי' באותיות אלו דוקא ויכול להיות גם באותיות אחרים, וכמו אדון עולם שהו\"ע השליטה והממשלה, הרי הענין הזה יכול לבוא גם באותיות אחרים כמו מלך העולם כו'. וא\"כ לא מצד השכל עצמו הוצרך להיות מלובש באותיות אלו דוקא, וכמו שאנו רואים שני חכמים אומרים סברא אחת וכמו תוס' ורא\"ש ור\"ן שאומרים סברא א' וכאו\"א אומר אותה באותיות אחרים, הרי שמצד השכל אינו מוכרח שיהי' דוקא באותיות אלו, רק מצד כח המצרף שהוא\nמצרף ומחבר האותיות ומלביש בהם את השכל כו', שזהו כח עליון יותר מגוף השכל המלובש בהאותיות כו'. ולכן התינוק הגם שיש לו מעט השגה כפי ערכו מ\"מ לא ילביש באותיות גם השכל הקטן המושג בדעתו מפני שאין לו אותיות וצירופים במה להלביש ולהביא את השכל כו', והיינו מפני שאין לו התגלות הכח העליון המצרף שזה בא במשך השנים כו', דכח המצרף הוא כח החכ' (והאור המתלבש הוא מבינה כמ\"ש במ\"א), וזה בא בימי הגדלות דוקא, וכמו ולמכור בנכסי אביו עד שיהי' בן עשרים שאז שלימות בחי' המוחין דאבא כו' וכמ\"ש בלק\"ת פ' במדבר ד\"ה מבן עשרים שנה (עמ\"ש לקמן פ' קמ\"ו דהצטרפות האותיות הוא ע\"י מוחין דיניקה, אך המתבאר שם הוא שכאשר השכל הוא בבחי' או\"פ יכול להגביל את השכל בצירופי אותיות, משא\"כ כשהשכל אצלו בבחי' מקיף, ונק' זה חכ' שבדיבור היינו שלימות השכל המביא לידי דיבור. וענין צירוף המבואר כאן הוא מה שמגלה ומביא את הענין באותיות וצירופים אלו דוקא ולא בצירופים אחרים, שזהו דוקא מבחי' מוחין דאבא שלמעלה מהשגה כו' ומבחי' יחידה שבנפש כו'). וכן גם\nבגדול כמו בהשפעת השכל מהרב אל התלמיד הנה ודאי לא יכול להשפיע לו השכל כמו שהוא אצלו בצירופי אותיות שלו, מפני שהתלמיד קטן שכלו מלקבל השכל הגדול כמו שהוא אצל הרב, וע\"כ יוצרך להלביש ולצמצם את השכל בצרופי אותיות אחרים לפ\"ע שכל התלמיד, וכמו שנראה בחוש שבכל השפעת שכל לזולתו יוצרך לשנות הצירופי אותיות מכמו שהוא משיג בדעתו לעצמו, שזה כח נעלה יותר מהמצאת והשגת השכל לעצמו כו'. וזהו הסיבה שלא כל מי שמשיג שכל לעצמו יכול להשפיע אל הזולת, דגם שממציא את הענין שכלי ומשיגו לעצמו מ\"מ להשפיע אל הזולת אינו יכול, מפני שאינו מוצא אותיות וצירופים במה להביא את השכל אל הזולת כו'. והיינו להיות כי הצירופי אותיות באים מן הכח ההיולי דשכל שהוא הפנימיות שלמעלה מהמצאת והשגת השכל כו', ובשרשו הוא מעצמות הנפש כו', דכשם שהאותיות עצמן אין מקורן והתהוותם מהאור שכל המושג כ\"א ממקור השכל כנודע, כמו\"כ הצירופי אותיות הן ג\"כ ממקור השכל ושרשן מבחי' יחידה שבנפש שמשם שרש האותיות ומשם כח הצירוף לצרף ולחבר אותיות כו'. הרי דבצירוף האותיות בתיבה א' הנה לבד האור שכל המלובש בהתיבה יש בזה עוד אור"],[3601330191,"עליון שלמעלה הרבה מהשכל המושג כו' (וי\"ל דכח עליון הוא כח נעלם והוא העצמי של האו\"פ כמו שהוא בשרשו ומקורו, וחיות כללי הוא אור מתגלה והוא בחי' או\"מ כו' וי\"ל שזהו בחי' יחידה וחי' כו').\n<span data-k=\"ks\"><b>קיצור.</b> הנה מ\"ש בסש\"ב דבכל תיבה יש כח עליון וחיות כללי העולה על כולנה כו' והיא מחברתן ומצרפתן, זהו למעלה מהאור שכל המושג המלובש בהתיבה, דכח המצרף הוא מחכ' ושרשו מעצם הנפש כו'. </span>\nכז) <b>וי\"ל</b> הדוגמא מזה בע\"ס הגנוזות הכלולים באוא\"ס לפני הצמצום שהיו בבחי' אחדות דאז הי' בהם גילוי אור כו' כמשנת\"ל פכ\"ג וכ\"ה, הנה לבד האור שהי' בהם בבחי' אור פנימי כו' (שזהו הכוונה העליונה שיש באצי' הע\"ס ובמה שהן עשר דוקא כו' וכמשנת\"ל פכ\"ה), עוד זאת הי' בהם בחי' האור כללי העולה על כולנה כו', די\"ל שהי' מאיר עליהם בגילוי האור שבבחי' אוא\"ס שהוא בבחי' בל\"ג ממש כו', וע\"י הצמצום להיות נמשך ספי' אחת לבדה הנה לבד בחי' מיעוט דהאו\"פ עוד זאת הי' בחי' הסתלקות והתעלמות האור העולה על כולנה כו'. והנה במשל דתי' ברוך הנ\"ל כשמפרידין אות א' מהתיבה הרי מסתלק ממילא האור העולה על כולם ג\"כ, ולמעלה הן ב' צמצומים הא' צמצום הא\"ס והוא שהאור שבבחי' א\"ס נסתלק ונתעלם שנכלל בעצמותו כו', והב' הצמצום בשרש ומקור הקו להיות נמשך ספי' אחת לבד לא בהתערבות כולם יחד כו'. וי\"ל דכשהי' מאיר האור הבלי גבול ממש היו הע\"ס הגנוזות בטלים לגמרי כביטול זיו השמש בשמש כו' כמשנת\"ל פי\"ח, וע\"כ הי' תחלה הצמצום בחי' התעלמות האור הבל\"ג\nואח\"כ הצמצום בהע\"ס הגנוזות כו'. והענין הוא (עמ\"ש בלק\"ת בהבי' הב' דשחורה אני ספ\"א), דהנה נת\"ל פט\"ז דע\"ס הגנוזות הן בבחי' עליית הרצון שעלה ברצונו הפשוט להאציל כו' והא\"ס הבל\"ג זהו מה שלמעלה מעלות הרצון ושם הן ספי' עד אין קץ כו', ונת' שם שזהו שרש ומקור דסוכ\"ע וממכ\"ע הכלולים באוא\"ס ב\"ה וכמ\"ש מזה באורך בדרוש יו\"ט של ר\"ה, רס\"ו. והנה האור דממכ\"ע ה\"ה נמשך מבחי' אור הסובב, ולפי המבו' כאן צ\"ל דאין זה מבחי' אור הסובב ממש (היינו בחי' חיצוניות דהאור הבל\"ג כו'), כ\"א שכלול בהאור הסובב כו', אבל מ\"מ ה\"ה בבחי' התכללות ובבחי' התאחדות ממש באוא\"ס ב\"ה. וכמ\"ש במ\"א בענין הציצית שהן מין כנף דעם היות שאינן מהכנף ממש דהכנף הוא מהטלית שזהו בחי' לבוש מל' בחי' סוכ\"ע כו', והל\"ב חוטין דציצית שהן ל\"ב נתי' חכ' דבשרשן הן הע\"ס הגנוזות שרש בחי' ממכ\"ע אינן מהכנף ממש שהוא בחי' אוא\"ס הבל\"ג כו', מ\"מ ה\"ה קשורין ומיוחדי' בהכנף והן מין כנף כו' (והיינו שאין זה כמו שרשי הכלים הכלולים באוא\"ס דעם היות שזהו ג\"כ א\"ס ממש ה\"ה בחי' אותיות\nלבד כו', אבל שרשי האורות ה\"ה בחי' אורות כו'. וי\"ל דכמו באצי' בבחי' או\"כ אומר בת\"ז איהו וחיוהי חד איהו וגרמוהי חד שנא' ב\"פ חד, ומבו' בכ\"מ שאינו דומה היחוד דכלים להיחוד דאורות, דיחוד הכלים עם האורות הוא כמו שני דברים המתייחדים, אבל יחוד האורות במאציל עליון הוא בבחי' יחוד ודביקות ממש עד שהאור הוא מעין המאור כו'. וכמו\"כ י\"ל בשרשן ומקורן באוא\"ס שלפני הצמצום דהע\"ס שהן שרש ממכ\"ע ה\"ה קשורין ומיוחדים באור הסוכ\"ע וה\"ז מעין המאור, דהגם שזהו בחי'"],[3601330192,"אור פנימי מ\"מ ה\"ז מעין המאור שזה\"ע מין כנף כו'). וי\"ל שזהו נחשב בחי' האחרונה שבאוא\"ס, וכמ\"ש בע\"ח שמ\"א בענין עתיק שזהו בחי' היותר תחתונה ושפלה שבא\"ס (וכבר נת\"ל פט\"ו דהע\"ס הגנוזות הן בחי' עתיק דא\"ק כו'), דלכאורה אינו מובן מה שייך לומר בחי' אחרונה בדבר שאין בו ראש וסוף, וכמ\"ש בע\"ח בתחלתו דבאוא\"ס שהי' ממלא מקום החלל לא הי' בו ראש וסוף ומעומ\"ט כו', וא\"כ מה שייך בזה בחי' אחרונה כו'. ומבו' בלק\"ת בהבי' דשחורה אני דהיינו בחי' או\"ר הא\"ס דלהיותו בחי' אור וזיו בלבד ה\"ז בחי' אחרונה כו', ושם דמ\"ש בע\"ח בחי' היותר אחרונה אין הכוונה על כללות האור כ\"א שמבחי' האחרונה שבהאור נמשך להיות עתיק כו', די\"ל שזהו בחי' ע\"ס הגנוזות שהו\"ע התכללות בחי' ממכ\"ע שבאוא\"ס הסוכ\"ע ה\"ז בחי' היותר אחרונה שבאוא\"ס כו', דענין התכללות הזאת הוא מה שהאוא\"ס הבלי גבול שיער בעצמו ההמשכה שבבחי' גבול כו' (עמשנת\"ל פט\"ז צור שבו שרשי ההוויות כו'), דהשערה זו היא בחי' היותר אחרונה שבאוא\"ס כו' (והיינו בחי' עלות הרצון שז\"ע השערה הנ\"ל שבאוא\"ס\nהבל\"ג ה\"ז בחי' האחרונה שבאוא\"ס כו'). וי\"ל שזהו ג\"כ הכוונה בלק\"ת שם בהמשל ונמשל דסש\"ב פנ\"א בענין כחות הנפש שאינן עצמות הנפש אלא תרי\"ג מיני כחות וחיות כלולים בה כו' והן מתלבשים במוח וע\"י המוח נמשך לכל האברים כו', דהנמשל דכחות הכלולים בנפש הו\"ע הע\"ס הגנוזות בחי' עתיק דא\"ק הכלולים באוא\"ס הבל\"ג דענין ההתכללות הו\"ע ההשערה הנ\"ל, ומזה נמשך הקו שמתלבש בבחי' אריך דכללות העולמות דהיינו בחי' א\"ק כו'. ונמצא דבחי' הע\"ס הכלולים באוא\"ס זהו בחי' האחרונה שבאוא\"ס כו'. וי\"ל שזהו בחי' מל' דא\"ס בכלל כו', והגם דבאוא\"ס הבל\"ג אינו שייך ע\"ס כ\"א ספי' עד אין קץ כו'. הענין הוא דהנה נת\"ל פט\"ז דספי' אין קץ היינו שהן בבחי' בלי גבול, אמנם השערת ההמשכה שבבחי' גבול י\"ל שזהו בחי' המל' שבא\"ס הבל\"ג כו' (עמשי\"ת לקמן פ' ומשם יובן כאן), (וביאור הענין י\"ל עפמ\"ש במ\"א שהמל' נק' רגל לפי שבה וע\"י ההמשכה מעולם העליון לעולם התחתון דהיינו ההמשכה ממהות למהות וכמו מאצי' לבי\"ע כו', דכמו\"כ י\"ל באוא\"ס שלפני הצמצום דההשערה להיות ההמשכה שבבחי' גבול זהו בחי' מל' כו').\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא מזה למעלה דקודם הצמצום הי' אור הא\"ס מאיר בגילוי על הע\"ס הגנוזות, והצמצום הי' בב' ענינים, סילוק אור הא\"ס ושיהי' אצילות ספירה אחת פרטיות. דהנה שרשי האורות הן מעין בחי' אור הא\"ס. והו\"ע מין הכנף, וי\"ל שזהו בחי' האחרונה שבהאור, כי ענין התכללותם באוא\"ס הוא שהאוא\"ס הבל\"ג שיער בעצמו להאיר בבחי' גבול, והשערה זו היא בחי' מל', והי' הכל כלול באור הא\"ס כו'. </span>\nכח) <b>והנה</b> הצמצום שהי' באוא\"ס הוא שנתעלם האור שבבחי' א\"ס ונשאר רק בחי' השערה הנ\"ל, דהיינו התכללות הע\"ס הגנוזות שזהו בחי' היותר האחרונה שבאוא\"ס והיא בחי' נקודה לבד לגבי האוא\"ס הבל\"ג והיא בחי' מל' שבא\"ס כו'. אמנם הנקודה הראשונה שהתחיל להתגלות לאחר הצמצום והיינו בחי' הראשונה שבע\"ס היא בחי' החכ' כו' (וזהו צמצום הב' להיות החכ' בחי' ספי'"],[3601330193,"פרטיות בפ\"ע כו'). דנקודה זו יש בה ב' צמצומים, צמצום הא' הוא שאור א\"ס ב\"ה צמצם כל אורותיו והאציל רק מבחי' תחתונה שבאור כו' (והיא בחי' השערה הנ\"ל), שזהו מ\"ש כולם בחכ' עשית כי גם חכ' היא בחי' עשי' אצלו ית' הבלתי בעל גבול ותכלית (דהיינו שגם לגבי האור והזיו היא בחי' עשי'), לפי שנאצלה מבחי' היותר תחתונה שנק' עשי' עד\"מ כו' (והיא בחי' מל' שבא\"ס כנ\"ל). וצמצום הב' הוא שבהע\"ס הגנוזות הכל קשור בבחי' התאחדות, וא\"כ הרי בחי' החכ' היתה כלולה עם שאר הספי' שהיתה בעצם במדרי' גבוה ונעלית, דהיינו לא בבחי' מציאות ניכרת והי' בה גילוי האור הנעלה שבהצטרפות דכל הספי' יחד (כמו עד\"מ אור השכל המלובש בהתיבה והו\"ע גילוי הכוונה העליונה שבע\"ס כו'), וכאשר האציל החכ' נאצלה ספי' החכ' לבדה כו'. אך צמצום הא' הוא בבחי' סילוק והתעלמות האור וצמצום הב' הוא בבחי' מיעוט לבד כו'. ולפי\"ז מובן איך שהקו לגבי שרשו ומקורו הוא בבחי' גילוי ההעלם, דהגם שההמשכה הוא ע\"י הצמצום מ\"מ להיות שהצמצום אינו בבחי' סילוק האור כ\"א מה שהספי' נתחלקו\nלהיות ספירות מיוחדות, והחכ' בעצם ה\"ה בחי' החכ' שבא\"ס (ויש בה מהאור הראשון כו' וכמובן מהמשל דפרטי השכליים שנת\"ל פכ\"ה) רק שהיא בבחי' מיעוט האור, א\"כ ה\"ז בחי' גילוי ההעלם לבד כו'. ולגבי האוא\"ס הבל\"ג והוא האור העולה על כולנה, החכ' (וכן כל הספי') היא באין ערוך שהרי נק' שרש ומקור הגבול לגבי מדרי' זו כמשנת\"ל פט\"ו, וגם שהצמצום הי' בבחי' סילוק האור שנשאר רק רושם בלבד כו' (ר\"ל שהאוא\"ס הבל\"ג שזהו האור העולה על כולנה על שרשי האורות כנ\"ל, הנה גם כשנסתלק האור ע\"י הצמצום נשאר רושם ממנו בשרשי האורות, שהרי דבר שבקדושה אינו נעקר ממקומו לגמרי כו' כנודע, אבל הוא בחי' רושם בלבד כו'). וי\"ל שהרושם הנשאר זהו בחי' אוא\"ס ששורה בחכ' וכמ\"ש בסש\"ב פל\"ה בהג\"ה שהחכ' נק' אמת משום שבו שורה אוא\"ס היינו בחי' הרושם דאור א\"ס הבל\"ג כו' (ועמשית\"ל פ'), ועמ\"ש בלק\"ת ד\"ה ויקח קרח פ\"ב דבחכ' מתלבש האור הסובב בבחי' פנימי ושהו\"ע המשל שבמדרש ממראות גדולות ומראות קטנות כו' יעו\"ש, מ\"מ י\"ל שזהו רק בחי' רושם מהאוא\"ס הבל\"ג שהרי מ\"מ ה\"ז מין\nכנף ולא כנף ממש כו', רק להיותו רושם הא\"ס הבל\"ג ה\"ז ג\"כ בבחי' ריבוי אור ובבחי' בל\"ג כו' (ואין זה כענין הרשימו שהיא רושם הא\"ס הבלי גבול דמבו' במ\"א שזהו רושם האור שנשאר בהאותיות כו', דשם להיות שזהו בחי' כח הגבול שבא\"ס ע\"כ רושם האור הוא בבחינת העלם בהאותיות וגם בא בחי' כח גבולי כו' וכמ\"ש במ\"א, אבל בשרשי האורות ה\"ז בבחי' גילוי כו'). ולפי\"ז יש לבאר גם לשטה זו מ\"ש במ\"א בענין הקו שיש בו ב' הפכים שהוא קו המדה וגם מקשר ומייחד ועושה התכללות בהספי' כו' (דלפמ\"ש במ\"א שהקו שרשו מהאוא\"ס הבל\"ג רק שנמדד ע\"י הרשימו ה\"ז מובן בפשיטות דמאחר שבעצם הוא בל\"ג ע\"כ הוא מקשר ומייחד והמדידה היא מצד הרשימו כו', אך לפי המבו' כאן י\"ל) דעם היות שגם בשרשו יש ע\"ס דמשו\"ז הוא בבחי' קו המודד באופן האורות הגלוים בע\"ס כו' וכמשי\"ת בעזה\"י, מ\"מ ה\"ה מקשר ומייחד כל הספי' ע\"י הרושם שבו מאור הא\"ס הבל\"ג העולה על כולם דגם הרושם הוא בבחי' א\"ס כו', ומ\"מ ה\"ז רושם לבד כו'. אבל הקו לגבי שרשו ומקורו הוא בבחי' גילוי ההעלם כו'."],[3601330194,"<b>וע\"פ</b> הנ\"ל יובן מ\"ש וידבר ה' כו' זאת חקת התורה אשר צוה ה' כו'. דהנה כתיב ויניחהו בג\"ע לעבדה ולשמרה, וארז\"ל לעבדה זו רמ\"ח מ\"ע ולשמרה שס\"ה מל\"ת ובמד\"ר אי' שקאי על עבודת הקרבנות, והיינו שעי\"ז ממשיכים תוס' אורות בג\"ע. דהנה בג\"ע כתי' ויטע הוי' אלקים שם מלא שבג\"ע מאיר גילוי ש' הוי', שזהו יתרון הג\"ע על העולמות שהן מש' אלקי' בחי' העלם ובג\"ע מאיר ש' הוי' בחי' גילוי כו', והו\"ע ביו\"ד נברא עוה\"ב בחי' חכ' כו' וזהו גילוי התענוג שבג\"ע כו'. ומ\"ש ויטע ה' אלקי' שנק' בשם נטיעה לפי שמ\"מ אין ערוך התענוג שבג\"ע לגבי התענוג שבחכ' כו', כמו הנטיעה שאינו בערך הפרי כו', אך ע\"י העבודה דתו\"מ ועבודת הקרבנות בבירור הנה\"ב דאדם כי יקריב מכם כו' ממשיכים תוס' אורות בג\"ע מבחי' החכ' וגם מבחי' האוא\"ס שלמעלה מהחכ' והיינו מבחי' הכתר דרמ\"ח מ\"ע ושס\"ה ל\"ת וזמד\"ר הן תר\"ך עמודי אור כו'. וי\"ל שזהו בחי' האוא\"ס השורה בחכ' שנת\"ל שזהו הרושם מהאוא\"ס הבל\"ג כו', והיינו להיות בג\"ע (שהוא בחי' ממכ\"ע כו') גילוי בחי' אוא\"ס הסובב\nהשורה בחכ' כו'. אך הנה פרה אדומה מעשי' בחוץ דוקא. דהנה כתי' ונהר יוצא מעדן כו' ומשם יפרד והי' לד' ראשים והן ד' חיות המרכבה, ובהשתל' נעשה מזה ד' מלכיות כו' שזהו התענוג שנפל בדרך שבירה ונפילה כו', וז\"ע פרה אדומה שמעשי' בחוץ היינו ענין התשובה להפוך את היצה\"ר שנפל בשבירה כו' וכמ\"ש אמצאך בחוץ דקאי על בע\"ת כו'. ושבע הזאות נוכח פני אוה\"מ הוא להעלות פנימיותה כו'. ואח\"כ שריפת הפרה לעשותה אפר ועד\"מ עץ הנשרף ונעשה אפר הרי האפר הוא מהותה ועצמותה וציור העץ הוא מהרכבת הג' יסודות שזה נשרף ונשאר רק עצם המהות כו', וכמו\"כ יצה\"ר הוא ציור הרע והוא הרצון ושכל ומדות שלו שכ\"ז צריך שריפה ושבירה לגמרי ויהי' נשאר רק האפר היינו עצם כח המתאווה הפשוט כמו שהוא בלי שום ציור שזה יכול להתהפך לקדושה להיות תוקף הרצון לאלקות כו'. וזהו שמצות פרה אדומה הי' באלעזר דוקא, דאי' בילקוט אלעזר אל עוזר כי הבא לטהר מסייעין לו דבכדי לצאת מטומאה לטהרה צריכים עזר וסיוע מלמעלה וזהו אל עוזר כו'. וע\"י עבודת פרה אדומה ממשיכים מלמעלה בחי'\nמים חיים וכמ\"ש ונתן מים חיים כו', מים הוא בחי' חכ' ומים חיים הוא בחי' מקור החכ' והיינו בחי' החכ' כמו שהיא בע\"ס הגנוזות קודם הצמצום שהחכ' היא במדרי' גבוה ועליונה בעצם וגם יש בה האור שבהתאחדות והתכללות כולם, והיינו האור העולה על כולנה כו' וכנ\"ל פכ\"ז. גם י\"ל שעי\"ז ממשיך בחי' עצמות אוא\"ס הבל\"ג שלמעלה משרשי האורות בשרשן ומקורן הראשון כו'. וזהו שנא' בפרה אדומה ב\"פ הוי', דהנה ב' שמות הוי' ידוע דא' הוא בסדר השתל' והב' שלמעלה מסדר השתל', וע\"י פרה אדומה ממשיכים בחי' הוי' דלעילא למעלה מהשתל'. וי\"ל שזהו בחי' שרשי האורות כמו שהן לפני הצמצום כו'. גם י\"ל שזהו בחי' עצמות האוא\"ס הבל\"ג שרש בחי' סוכ\"ע כו', וכמשנת\"ל פט\"ז דב' השמות הן שרשי הב' מדרי' דממכ\"ע וסוכ\"ע כו' וכמ\"ש במ\"א. וזהו וידבר הוי' אל משה היינו ש' הוי' דהשתל', זאת חקת התורה אשר צוה הוי' הוא ההוי' שלמעלה מהשתל' שממשיכים ע\"י פרה אדומה דמעשי' בחוץ דוקא שהו\"ע התשובה לצאת מהטומאה אל הטהרה כו', וע\"ז צריכים עזר שזה ע\"י אלעזר אל עוזר כו', ועי\"ז ממשיכים מ\"ח בחי' מקור החכ' דהיינו גילוי בחי' עצמות אוא\"ס הבלי גבול כו'."],[3601330195,"<span data-k=\"ks\"><b>קיצור.</b> והצמצום הוא שנתעלם אור הא\"ס ונשאר בחי' ההשערה, שהיא כנקודה לגבי אור הא\"ס, ונאצלה החכ' שהיא נקודה הראשונה דהתגלות, ויש בה ב' צמצומים, סילוק אור הא\"ס, ומיעוט האור, ונשאר בה רושם מהאור הא\"ס, וי\"ל שזהו בחי' אור א\"ס שבחכ', וזהו שהקו הוא בחי' גילוי ההעלם לגבי שרשי האורות, ויש מאין לגבי אור הא\"ס שנסתלק ונשאר רק רושם בהקו (ולפ\"ז יצדק גם לשטה זו שהקו קושר ומחבר משום רושם הא\"ס שבו). ובכל הנ\"ל ית' פסוק זאת חקת התורה כו'.</span>"],[3601330196,"<h3>בס\"ד. ש\"פ בלק, תער\"ב</h3>\n<b>מי</b> מנה עפר יעקב ומספר את רובע ישראל, וצ\"ל פי' ומספר את רובע אם הכוונה שיש מספר או שקאי על מ\"ש מי מנה דהיינו שלא יש מספר. וגם הלא ישראל הוא למעלה ממדרי' יעקב כידוע ולמה גבי יעקב נא' מי מנה דפשט הפשוט הוא שלא יש מספר וגבי ישראל כתי' ומספר כו'. ולהבין כ\"ז יש להקדים משנת\"ל דהמשכת האורות דע\"ס דאצי' משרשן ומקורן שהן הע\"ס הגנוזות באוא\"ס הוא ע\"י צמצום כו', ונת' שיש בזה ב' צמצומים הא' צמצום האור שבבחי' א\"ס שהצמצום בזה הוא בבחי' סילוק כו', והב' הצמצום בשרשי האורות דכמו שכלולים באוא\"ס ב\"ה הם בבחי' התערבות והתאחדות שגבוהים במעלתן בעצם שאינם בבחי' מציאות ניכרת וגם מאיר בהם אור נעלה שהיא הכוונה העליונה שבענין הע\"ס כו', והצמצום הוא שנפרטו להיות נמשך ספי' א' פרטיות שעי\"ז נתמעט האור ונעשית בבחי' מציאות ניכרת כו'.\nכט) <b>וע\"פ</b> הנ\"ל יובן ענין התלבשות האורות בכלים, שהרי האורות והכלים הם בבחי' ריחוק הערך זה מזה וכמו הגוף והנפש שרחוק ערכם מאד שהנפש רוחני והגוף הוא חומר וגשמי כו', כמו\"כ בדוגמא כזאת הן האורות והכלים וכמא' וכמה גופין תקינת לון כו', ומ\"מ הרי האורות באים בבחי' התלבשות בכלים שזהו בבחי' התלבשות ותפיסא ממש כו', והוא מפני שבהאורות גם כמו שהן בשרשן ומקורן באוא\"ס ה\"ה בבחי' ע\"ס (והוא בבחי' עלות הרצון שהו\"ע ההשערה להאיר במדה וגבול כו'), דעם היות שהן שם בתכלית ההתאחדות דהיינו שהן בבחי' פשיטות עד שאינם בבחי' ניכרת לעצמן כלל כו' מ\"מ ה\"ה בבחי' ע\"ס עכ\"פ. ואופן המשכתם והתגלותם הוא ע\"י הצמצום היינו שנמשך ספי' פרטיות בפ\"ע שעי\"ז נעשית בבחי' מציאות ניכרת ע\"כ הוא בערך להתלבש בכלים כו' (והיינו בכלים שהן ג\"כ אלקות בעצם כו'), והגם שהצמצום הוא בבחי' מיעוט לבד דענין המיעוט הוא בבחי' גילוי מההעלם (וזהו ההפרש בין מיעוט לסילוק דמיעוט הוא שההמשכה הוא בערך שרשה ומקורה, וסילוק הוא באין ערוך וכמו התחדשות כו'. ובאמת גם בזה אינו בבחי' התחדשות ממש שהרי הוא עכ\"פ בבחי' דביקות במקורו כו', והתחדשות"],[3601330197,"ממש שייך רק במציאות דבר כמו בכלים כו') וכל גילוי מההעלם הרי הגילוי מעין ההעלם כו', וכשם שההעלם הוא בבחי' פשיטות כמו\"כ הגילוי ג\"כ בבחי' פשיטות כו'. הנה באמת הרי הע\"ס דאורות הן בבחי' פשיטות לגבי ע\"ס דכלים וכמשנת\"ל פי\"ד, מ\"מ מאחר שגם בשרשן ומקורן יש בחי' ע\"ס דעם היות שהן בבחי' פשיטות מצד הדביקות ומצד ההתכללות שלהם באוא\"ס ב\"ה וכמשנת\"ל פכ\"א, ה\"ה מ\"מ בבחי' ע\"ס כו', וכמו שנמשכו ע\"י הצמצום בבחי' ספי' פרטיות בפ\"ע הרי נעשה כל אור בבחי' מציאות ניכרת עכ\"פ, ה\"ה בערך שיתלבש בבחי' הכלים כו' (ולקמן פ' ית' עוד סיבה לזה, והא בהא תליא כו'). וע\"י ההתלבשות בהכלים שהוא בבחי' התלבשות ותפיסא נעשה האור בבחי' מציאות דבר בחי' אור החכ' ואור החסד כפי מהות הכלים כו'. והנה בד\"כ יש ג' מדרי' באורות מדרי' הא' הן האורות כמו שהן כלולים באוא\"ס ב\"ה לפני הצמצום והן ע\"ס הגנוזות במאצילן שעז\"א אנת הוא חד ולא בחושבן כו', דפי' חד הוא בחי' יחיד בעצם שמיוחדים ממש באוא\"ס וגם הע\"ס עצמן הם בתכלית היחוד כו' (ולעיל פכ\"ד נת' דבעלות הרצון\nהוא בחי' שמות ל' רבים, הנה זהו במדרי' דאוא\"ס שלפני הצמצום כו', ועמ\"ש בשער היחוד פי\"א בענין יחיד אחד וקדמון, דיחיד הוא עצם האור שאינו בבחי' גילוי עדיין, ואחד הוא הגילוי בבחי' כללות ובבחי' פשיטות, וקדמון הוא ההשערה בכח כו'. דאחד וקדמון זהו קודם עלות הרצון ובחי' עלות הרצון (עמש\"ל פט\"ז) וכמ\"ש במ\"א, אבל לגבי האורות שנתגלו אחר הצמצום הנה שרשי האורות (שזהו בחי' השערה הנ\"ל וכמו שנת\"ל פכ\"ז) הכלולים בעצמותו ית' שלא נתגלו עדיין, ה\"ז בחי' יחיד שעז\"נ אנת הוא חד כו'). וכמ\"ש במ\"א ההפרש בין אחד ליחיד דאחד הוא התאחדות הפרטים והיינו מה שנעשה אחד לאחר שכבר נתגלו והיו פרטים נבדלים וכשחוזרין ונכללין במקורן שהן חוזרין ומתאחדין ה\"ז התאחדות הפרטים לבד, וכמו עד\"מ התפשטות כח התנועה שביד לעשות איזה מלאכה ואח\"כ כשנח ממלאכתו וחוזר התפשטות כח היד לעצמותו נעשה בבחי' אחד והוא רק התאחדות הפרט אחרי שכבר נמשך והי' כח בפ\"ע כו'. אבל יחיד הוא שמיוחד בעצם שאין כאן פרט כלל וכמו כח היד קודם שמנענע לעשות איזה דבר, הרי ודאי יש\nביד כח הזה לעשות הדבר רק שמיוחד הוא בעצם כח היד שאינו במציאות דבר לעצמו וממילא ה\"ה בבחי' יחוד ממש כו'. וכן הוא ביחוד כל הכחות כשהם מיוחדים בעצם הנפש קודם שמתפשטות מעצם הנפש כו' (וכמו היוצא ליהרג ר\"ל שיש לו אז שכל ומדות וכלולים בעצם הנפש בבחי' נקודה בלי שום התפשטות כלל כו'). וכמו\"כ למעלה הע\"ס הגנוזות במאצילן הם כלולים בעצמות המאציל בבחי' יחוד בלי שום מציאות לעצמן כלל כו', וזהו אנת הוא חד בבחי' יחיד בעצם כו', וז\"ש ולא בחושבן פי' שהגם שכלולים בו כל הע\"ס, אינם בחושבן עשר להיותם בטלים ומיוחדים באוא\"ס ב\"ה וגם הם בבחי' אחדות ממש זע\"ז כו', ואינו שייך לומר שם חשבון ע\"ס כו'. והמדרי' הב' הוא המשכת והתגלות האורות לאחר הצמצום שהן הפרשת הארה מאוא\"ס המאציל והוא המשכתן בבחי' ספירות פרטיות כו', שעז\"א ע\"ס בלי מה שהן בלי מהות עדיין, והיינו דקודם התלבשותם בכלים הן בבחי' פשיטות עדיין כו', דמאחר שהצמצום הוא בבחי' מיעוט לבד דהיינו שהן בבחי' גילוי ההעלם משרשם ומקורם והרי מקורם הוא בחי' חד ולא בחושבן כו' כנ\"ל, ע\"כ גם האורות שבאו בהתגלות יש בהם התגברות מקורם"],[3601330198,"שאינם בבחי' מציאות ובבחי' התחלקות עדיין כו', וכמא' אנת הוא חכים ולא בחכ' ידיעא כו', דחכים שייך לומר על האור כשבא בהתגלות דוקא, דכמו שכלול באוא\"ס ב\"ה הרי אינו בבחי' חכים וכמשנת\"ל פי\"ט שאינו בבחי' מציאות ניכרת כלל כו', ורק כשהאור בא בהתגלות שייך לומר חכים כו', אבל לא בחכ' ידיעא כמו ח\"ע דאצי' כו', כי החכ' היא בבחי' פשיטות עדיין כו', וכמשנת\"ל פי\"ד בענין ח\"ס שזהו למעלה מהחכ' עדיין גם לגבי בחי' ח\"ע דאצי' כו', וכן הוא בכל האורות שהן בבחי' פשיטות עדיין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והיות דשרשי האורות הן בבחי' ע\"ס, וע\"י הצמצום באו האורות בבחי' התחלקות ובבחי' מיעוט, ע\"כ ביכולתם שיתלבשו בכלים דאצי' שהן אלקות, ובהתלבשותן ה\"ה כאופן הכלים, ויש באורות ג' מדרי', הא' שרשי האורות הכלולים באוא\"ס קודם הצמצום שעז\"נ אנת הוא חד, דעם היותם עשר ה\"ה בבחי' חד ממש (לגבי האורות המתגלים), הב' התגלות האורות משרשם, להיות שהן בבחי' גילוי ההעלם, הגם שהן בבחי' מיעוט, ה\"ה בבחי' פשיטות, ועז\"נ ע\"ס בלי מ\"ה, וחכים ולא בחכ' ידיעא. </span>\n<b>למ\"ד)</b> ועל ב' מדרי' הנ\"ל נא' המלך המרומם לבדו מאז כו' והמתנשא מימות עולם, דפי' המלך המרומם הוא שמרומם ומנושא בעצם שאינו שייך לעולמות כלל, וזהו לבדו בחי' הוא לבדו הוא וכמו ונשגב הוי' לבדו כו', וכמו אתה הוא הוי' לבדיך כו' וכמ\"ש במ\"א, והיינו בחי' מל' דא\"ס כמו שהוא לפני הצמצום שזהו בחי' ההשערה שבאוא\"ס הבל\"ג להאיר בבחי' גבול והן הע\"ס הגנוזות כו' כמשנת\"ל פכ\"ז, דבחי' ומדרי' זו היא בתכלית היחוד וההתכללות באוא\"ס ולא בחושבן ע\"ס עדיין כנ\"ל פכ\"ט, וע\"כ ה\"ז בבחי' רוממות והתנשאות לגמרי כו', והיינו בבחי' התנשאות עצמי דמאחר שאינו בבחי' מקור עדיין ממילא ה\"ז בבחי' התנשאות עצמי כו'. והגם שזהו ההשערה להאיר במדה וגבול כו', מ\"מ הרי אינו בבחי' המשכה כלל להיות בגדר מקור כו', ובפרט דכללית השערה הזאת היא השערת האורות לא השערת הכלים הרי אינו שייך לומר בזה התנשאות מהדבר המתהווה כ\"א מה שהוא מרומם לבדו כו'. ומש\"א והמתנשא מימות עולם הוא בהאור כמו שבא בגילוי להתלבש בכלים, אבל קודם שמתלבש עדיין, דבחי' זו אינו\nבבחי' המרומם לבדו היינו בבחי' רוממות עצמי מאחר שכבר בא בגילוי להיות בבחי' מקור להאורות דע\"ס כו', ומ\"מ או' ע\"ז והמתנשא מימות עולם להיות שאורות אלו הם ג\"כ בלי מה בבחי' פשיטות ה\"ה מנושאים עדיין מבחי' ימות עולם שהן יומין דז\"א ויומין דע\"ס דאצי' בכלל כו'. ובד\"כ י\"ל דב' בחי' אלו הן בחי' עתיק ואריך וכמשנת\"ל פט\"ו דהע\"ס הגנוזות הן בחי' עתיק דא\"ק כו', והאור שבא בגילוי לאחר הצמצום ה\"ז בחי' אריך בכלל כו', דעם היותו בחי' מקור לע\"ס מ\"מ הוא מרומם ומנושא מהם כו'. וכ\"ז הוא בהאורות שהן בבחי' פשיטות דגם מדרי' הב' הנ\"ל הוא בבחי' פשיטות ובבחי' בלי מ\"ה כו' (דעם היותם מדרי' פרטיות ה\"ה בבחי' בלי מ\"ה מפני שהצמצום הוא בבחי' מיעוט לבד כו' וכנ\"ל), וכמו ח\"ס שהיא למעלה מהחכ' לגבי חכ' הגלוי' כו', וכמו סברת הרב שהיא סברא אחת עדיין כו' וכמשנת\"ל פי\"ג. והמדרי' הג' הוא האורות המתלבשים בכלים שבאים בבחי' תפיסא והתלבשות ממש בכלים עד שנעשים כפי מהות הכלים שבאין ערוך כלל"],[3601330199,"לגבי האור כו', וכמו בהשגה דאור השכל שבמוח להשיג השגה גשמיות שאינו בערך השכל וההשגה שבנפש המשכלת כו', וכמו הסברא כשהיא בהשגת שמאי והלל שהן בבחי' חו\"ג ממש כו', וכמו\"כ האורות כשהן בהכלים ה\"ה בבחי' מהות ומציאות דבר בבחי' אור החכ' ואור החסד ואור הגבו' כו', ולא רק מה שנראי' לפי גוון הכלים כ\"א שנעשים בבחי' חו\"ג ממש בבחי' מציאות עד דבכדי להיות בחי' הביטול וההתכללות בהם להיות אחליפו דוכתיי' כו', זהו דוקא ע\"י גילוי אור עליון כו'. וע\"ד מ\"ש המשל ופחד עמו עושה שלום במרומיו מיכאל שר של מים כו' ואינם מכבים זא\"ז שזהו ע\"י גילוי אור עליון דוקא, דהמלאכים הגם שהן בעולם הבריאה שרשן הוא מאו\"כ דאצי' וכמ\"ש בסי' שער הק\"ש דנפש דמלאכים שרשן מאורות דאצי' כו', והתכללות שלהם הוא ע\"י האור עליון שלמעלה משניהם שעי\"ז מתבטלים ממציאותם כו'. וכמו\"כ באצי' באורות המתלבשים בכלים שהן בבחי' חו\"ג כו', בכדי שיהי' הביטול והתכללות שלהם הוא ע\"י אור העליון דוקא כו', וכן ההתאחדות וההתקשרות שלהם באוא\"ס ב\"ה הוא ע\"י אור העליון כו'. דהנה\nשרשי האורות הכלולים באוא\"ס ה\"ה מיוחדים בעצם באוא\"ס ב\"ה וגם בבחי' התגלות שלהם קודם שמתלבשים בהכלים שהן בבחי' בלי מ\"ה ובלי מהות ה\"ה ג\"כ בבחי' התאחדות באוא\"ס ב\"ה כו', וכמו שמתלבשים בכלים הגם שגם אז הן בבחי' אור הדבוק במקורם מצד שהן בבחי' אור בעצם כו' (והוא ג\"כ ענין שנת\"ל פי\"ד שהע\"ס דאורות הן בבחי' פשיטות לגבי ע\"ס דכלים כו'), מ\"מ זהו ע\"י גילוי אור עליון שפועל בהם ההתאחדות וההתכללות כו', וכמאמר אנת הוא דקשיר לון ומייחד לון דקאי על האורות המתלבשים בכלים דהתקשרות והתאחדות שלהם באוא\"ס ב\"ה וכן היחוד וההתכללות שלהם הוא ע\"י דאנת הוא דקשיר כו' (ומ\"מ הדביקות והיחוד הוא בבחי' איהו וחיוהי חד להיות שזהו בחי' האור כו'), והיינו לפי שנעשים בבחי' מציאות כפי מהות הכלים, וע\"כ דוקא ע\"י אור עליון נעשה בהם הביטול כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והמדרי' הא' הנ\"ל היא בחי' המרומם לבדו, בחי' עתיק דא\"ק, והמדרי' הב' הוא המתנשא מימות עולם, בחי' אריך, וכ\"ז בבחי' בלי מ\"ה. והמדרי' הג' הן האורות המתלבשים בכלים, שנעשים כערך מהות הכלים, וזה שאחליפו דוכתייהו וכן ההתקשרות שלהם באוא\"ס וההתכללות שלהם הוא ע\"י אור עליון המאיר עליהם ובהם. </span>\nלא) <b>והנה</b> ג' מדרי' אלו הן ג' בחי' נקודה קו שטח, דנקודה הוא בחי' העצמית שלמעלה עדיין מבחי' המשכה וגילוי, וכמו נקודת יו\"ד שאין בה עדיין התפשטות אורך ורוחב כו', ועם היות שיש בה ו\"ד שהוא האורך ורוחב הכל הוא בהעלם עדיין והכל בבחי' נקודה לבד בבחי' פשיטות עדיין כו'. והקו הוא בחי' המשכה וגילוי רק שהוא בחי' המשכה היולית עדיין כו', והיינו שהקו עם היות שיש בו פרטים בהתגלות מ\"מ ה\"ה בבחי' פשיטות עדיין ובבחי' התאחדות כו'. דהנה ענין הקו בד\"כ הוא בחי' האורך שהוא בחי' הגילוי כו', אמנם יש בזה ב' אופנים הא' הוא מה שפרט א' בא בהמשכה והתגלות ממדרי' למדרי' וכמו בהשפעת השכל מגדול לקטן, שאותו הענין הפרטי שמשפיע לו מתלבש במשל או באיזה ענין שהוא"],[3601330200,"בערך המקבל שעי\"ז יבין את הענין הפרטי ההוא, וכן מלבישו עוד באיזה ענין שלמטה מזה עד שיובן גם למקבל שהוא נמוך במדרי' כו', ובאופן כזה מורידו ממדרי' למדרי' עד שיהי' הענין מובן גם לבעל שכל קטן כו'. והאופן הב' הוא שהקו הוא רק התגלות הפרטים שבהנקודה לא הבאת הפרט לידי השגה והבנה כ\"א רק הבאת והתגלות הפרטים שבהנקודה כו', דממילא גם הפרטים הם בבחי' פשיטות ובבחי' היולית עדיין כו' (וע\"ד המשנה שהם ענינים פרטים שאינם בבחי' השגה עדיין עד שמתבארים אח\"כ בגמ' בריבוי סברות והשגות שונות כו', רק שהן התגלות הפרטים שבהנקודה דהיינו תושב\"כ כו'), ועמ\"ש באורך בד\"ה כל הנהנה, רנ\"ב, בענין הקו שמחיבור נקודות הרבה נעשה קו כו', והוא שהמדרי' פרטיות שבו הן בבחי' נקודות ובבחי' פשיטות כו' (ושם ביאר הענין שזהו כמו עקודים ונקודים דעקודים הוא שהעשר כתרים שהן האורות העצמיים ה\"ה בבחי' בלתי מציאות ניכרת וכולם קשורים ומיוחדים יחד כו', ונקודים הוא שבאו בהתגלות כמו שהן בפשיטותן ובעצמיותן כו'. ובדוגמא כזאת הו\"ע הקו מה שמחיבור נקודות\nרבים נעשה הקו דהיינו התגלות האורות בבחי' פשיטות כו', רק דבנקודים ה\"ה בבחי' ענפין מתפרדין ובקו הן בבחי' אחדות כו'. והיינו ההפרש כשההתגלות היא להיות בבחי' מציאות שז\"ע הנקודים שהוא ההתגלות להיות בבחי' מציאות וכמו אנא אמלוך כו', או שההתגלות היא רק בבחי' גילוי מן העצם לא להיות בבחי' מציאות רק התגלות לבד כו'. וכמו חכם הגדול המגלה אור שכלו כמו שהוא אצלו שכל הפרטים באים בהפשטה ואינו ניכרים עדיין הפרטים והחילוקי' שבהם כו', וכמשנת\"ל פי\"ט המשל באור שכל מופשט שיוכל להתערב עם אור שכל ההפכי המופשט ג\"כ כמוהו כו'). ועם היות דהקו הוא בבחי' מיעוט האור לגבי הנקודה וכמשנת\"ל פכ\"ב בענין הצמצום בשרשי האורות להיות נמשך ספי' פרטיות שעי\"ז נעשה בבחי' מיעוט האור כו', מ\"מ ה\"ז בבחי' פשיטות עדיין ובבחי' בלי מ\"ה לגבי האורות המתלבשי' בכלים כו'. והשטח הוא כמו שהאורות מתלבשים בכלים שנעשים בבחי' אור החכ' ואור החסד כפי מהות הכלים כו', ואינם בבחי' פשיטות כמו האורות מצ\"ע עד שפועלים ההתהוות דבי\"ע כפי אופן הכלים כו'. והדוגמא\nבזה י\"ל כמו באצי' רוחו של משה על הזקנים, הרי ע\"י שנח על הזקנים הי' יכול להיות השפעת הבשר מה שלא הי' אפשר להיות מרוחו של משה עצמו שלא ע\"י הזקנים כו', וז\"ש ואצלתי מן הרוח אשר עליך ושמתי עליהם שיש בזה ב' דברים אצילות רוחו של משה ומה שנח על הזקנים כו', והיינו דבאצילת רוחו של משה לבד הגם שזהו ירידה ממדריגתו לא הי' אפ\"ל עדיין השפעת הבשר כ\"א ע\"י שנח על הזקנים שהיו באין ערוך לגבי משה, עי\"ז נעשה רוחו של משה באופן כזה שיהי' בו וע\"י השפעת הבשר כו', וכנודע דכל ההשפעות הי' צ\"ל ע\"י משה דוקא כו'. וכמו\"כ הוא בענין אצי' דהאורות כמו שנאצלו ונתגלו משרשן ומקורן מהע\"ס הגנוזות ה\"ה בבחי' בלי מ\"ה עדיין כו', וממילא אינן בערך עדיין להיות בבחי' מקור לבי\"ע כו', וע\"י שנתלבשו בכלים עי\"ז נתפסו בבחי' מציאות להיות בבחי' מקור לבי\"ע, דאיהו וגרמוהי חד לברוא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והו\"ע נקודה קו שטח, נקודה היא העצמיות והיא שרשי האורות, קו הוא התגלותן ע\"י הצמצום בבחי' ספירות פרטיות, בבחי' נקודות פשוטות</span>"],[3601330201,"<b>והיוליות</b> (וכמו עולם הנקודים רק שם ההתגלות להיות בבחי' מציאות, ובהקו הוא להיות בחי' גילוי מהעצם), והו\"ע שהקו עשוי מנקודות ושטח הוא תפיסת האורות בכלים, שנעשים בבחי' מציאות חכ' וחסד כו'.\nלב) <b>אמנם</b> זה שבהתלבשותן בהכלים נתפסו בבחי' מציאות להיות בבחי' אור החכ' וכו' אין זה מחמת הכלים לבד, כ\"א מפני שהאור בעצם יש בו ע\"ס, דעם היותם בבחי' בלי מ\"ה מ\"מ ע\"י הכלים נעשים בבחי' מציאות כו', וכמשנת\"ל פי\"ג בענין הלל ושמאי דהסברות אצלם המה בבחי' חו\"ג ממש דעם היות שנעשה זאת בהשגתם שזה תופס הסברא להיתר כו', מ\"מ הסיבה לזה מפני שסברת הרב כוללת חו\"ג בעצמה בהעלם ע\"כ באה בהשגתם בבחי' חו\"ג במציאות ממש כו', וכמו\"כ באור השכל שבא במוח בהשגה כזו שאינה בערך ההשגה דהשכל שבנפש המשכלת הוא מפני שגם בנפש היא בבחי' שכל וחכ' דוקא, דלולא כן לא הי' בא בהתלבשות כלל בחומר המוח ולא הי' בבחי' השגה גשמיות כו'. כן הוא הדוגמא למעלה דמפני שיש בחי' חו\"ב וחו\"ג בהאור הגם שזהו בהעלם ובפשיטות עדיין כו', זאת היא הסיבה שבא האור בבחי' התלבשות פנימי בהכלים, שנתפס בהכלים ונעשה כמהות הכלים בבחי' מציאות חו\"ב וחו\"ג, שאינו כלל כמו פשיטת האור מצ\"ע ופועל פעולת הכלים שאינו בערך האור מצ\"ע כו'. וזהו כמשל בנפש שנת\"ל פ\"ג שמפני\nשהכחות הם פנימיים בעצם, דהיינו שאינם הארה מעצם הנפש כ\"א מה שהנפש כוללת בעצמה כחות כו', דכמו שהן כלולים בנפש אינם בבחי' מציאות כחות עדיין עד שהן כולם שם בהתערבות כו', אך בהמשכתן מהנפש ע\"י צמצום ה\"ה בבחי' התלבשות ותפיסא באברי הגוף כו'. וכמו\"כ הוא באור הקו דשרשו מהע\"ס הגנוזות באוא\"ס ב\"ה, שאין זה האור א\"ס עצמו כ\"א מה ששיער הא\"ס בעצמו להאיר בבחי' מדה וגבול כו', וכמו שכלולים באוא\"ס ה\"ה בבחי' פשיטות לגמרי ובבחי' התערבות כו'. אך כמו שנמשכים ע\"י הצמצום ספירות פרטיות כל ספי' בפ\"ע, הגם שגם בזה הם בבחי' בלי מ\"ה כו', מ\"מ ה\"ה בערך להתלבש בכלים שעל ידן נעשה בבחי' חו\"ב וחו\"ג כו', והיינו דבסוף המשכתן מתגלה בחי' ההגבלה שבשרשן ומקורן מה שהן בחי' ע\"ס כו', להיות דכללות ענין הע\"ס הגנוזות הוא ההשערה להאיר בבחי' מדה וגבול כו', ה\"ז מתגלה בסוף ההמשכה בהתלבשות האורות בכלים כו' (וכנודע דבכל דבר עיקר ואמיתית ענינו מתגלה בסוף ההמשכה דוקא כו'). דהנה הע\"ס הגנוזות עם היותם להאיר בבחי' מדה וגבול ה\"ה בבחי' א\"ס שה\"ה\nכלולים ומיוחדים באוא\"ס עצומ\"ה כו' (וה\"ה בבחי' א\"ס הן מצד עצמן והן מצד ההתכללות בבחי' אוא\"ס הבל\"ג וכמשנת\"ל פכ\"ז בענין הכנף מין כנף כו'), ובבחי' התגלות שלהם אחר הצמצום קודם שמתלבשי' בכלים מאיר בהם בחי' הא\"ס שבהע\"ס הגנוזות כו', והיינו מה שהן בבחי' בלי מ\"ה כו'. ובסוף המשכתן היינו בהתלבשותן בכלים מתגלה בחי' המדה והגבול והיינו מה שהן בבחי' חו\"ב וחו\"ג כו'. ומ\"מ מה שנעשים בבחי' מהות ומציאות דבר כפי מהות הכלים הוא ע\"י הכלים דוקא, רק שזהו מפני שהאורות עצמן הם בבחי' ע\"ס כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש מי מנה עפר יעקב ומספר את רובע ישראל. דהנה רובע יש בו ב' פי', הא' מל' ארחי ורבעי זרית דעש\"ז נק' מי גשמים בשם רביעה"],[3601330202,"כמו רביעה ראשונה רביעה שני' דמיטרא בעלא דארעא כו', והב' רובע מל' ארבע. והענין דהנה כנס\"י נק' בשם ארץ כמ\"ש ארץ ארץ ארץ שמעי דבר ה' כו', וכמ\"ש בתו\"א ד\"ה השמים כסאי, ומטרא שהוא בעלא דארעא הוא ההמשכה שע\"י תומ\"צ שעי\"ז נמשך תוס' אורות בנש\"י כו', ובד\"כ הוא בירידת הנשמה למטה שע\"י תומ\"צ למטה מגיעים לבחי' האור כו'. דהנה נשמה שנתת בי טהורה היא בחי' הכלים (הו\"ע ישראל עלה במח' כו'), וע\"י התומ\"צ בבחי' אתכפי' ואתהפכא באים לאשתאבא בגופא דמלכא היינו בחי' האורות כו', וזהו רובע ל' ארבע דג' עולמות בי\"ע הן מחדו\"מ דבעשי' כתי' אף עשיתיו להפסיק הענין כו', ואף מרבה בחי' רביעית בחי' האצי' שזהו בחי' האורות כו', וזהו ומספר את רובע ישראל. דהנה המצות הן בזמן ומקום וכמ\"ש לכל זמן ועת לכל חפץ גם בחי' חפצי שמים כו', וע\"כ גם ההמשכה שע\"י המצות הן באים בבחי' מספר והו\"ע תרי\"ג מצות תרי\"ג ארחין דז\"א שהן תרי\"ג המשכות מאוא\"ס ב\"ה, ומספר זה הוא בד\"כ ובפרטיות כל מצוה מתחלקת לפרטים רבים לאין קץ ותכלית כו', והכח לזה להיות מספר בבחי'\nלא מספר הוא ממקור ההמשכה קודם שנתחלק לתרי\"ג כו', והו\"ע חד ארחא דפלגותא דשערי דגלגלתא שממנה מתפשטין התרי\"ג ארחין דז\"א כו', ובד\"כ זהו ב' מדרי' שבאור שנת\"ל שהוא האור כמו שבא בכלים שהוא בבחי' התחלקות כו' והאור כמו שהוא למעלה מכלים שהוא בבחי' בלי מ\"ה למעלה מהתחלקות עדיין כו'. וכ\"ז הוא בחי' ישראל דהיינו צדיקים המקיימים תומ\"צ שהן בבחי' מספר ובבחי' בלי מספר כו', אך מי שפגם והעביר את הדרך ח\"ו הרי צריך לתשובה ובע\"ת משכין לי' בחילא יתיר היינו שממשיכים מבחי' אנת הוא חד ולא בחושבן שזהו מדרי' הא' שבאור שנת\"ל והן בחי' ע\"ס הגנוזות שהן בבחי' התאחדות ממש כו'. ועז\"א מי מנה עפר יעקב שזהו בבחי' בלי מספר ממש כו'. וגם י\"ל שעי\"ז ממשיכים בחי' האוא\"ס שבבחי' בל\"ג ממש כו'. וז\"ע עפר יעקב כמו אפר פרה שמטהר את הטמאים ע\"י ההמשכה מעצמות אוא\"ס בחי' מ\"ח כו' וכמשנת\"ל בענין פרה אדומה כו', ואו' עפר יעקב דוקא שהו\"ע בע\"ת כו'. וזהו מי מנה עפר יעקב שע\"י התשובה ממשיכים מבחי' ע\"ס הגנוזות במאצילן שאינם בבחי' המשכה כלל כו', וגם\nמבחי' עצמות אוא\"ס הבל\"ג כו' ומספר את רובע ישראל הוא ההמשכה שע\"י תומ\"צ שזהו בחי' מספר אשר לא יספר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם שרש סיבת הדבר שהאורות באים בבחי' מציאות בהתלבשותן בכלים הוא מפני ששרשי האורות הוא מה שהא\"ס שיער להאיר במדה וגבול, דבסוף המשכתן היינו בבחי' השטח מתגלה בחי' ההגבלה שבשרשן, ובאמצען היינו בחי' הקו מתגלה בחי' הא\"ס שבשרשן. וע\"פ הנ\"ל יובן מ\"ש מי מנה כו' ומספר את רובע ישראל.</span>"],[3601330203,"<h3>בס\"ד. ש\"פ פנחס, תער\"ב</h3>\n<b>ובראשי</b> חדשיכם תקריבו עולה לה'. ואי' בזהר וכי כמה ראשין אינון לסיהרא והא לית רישא לסיהרא אלא שמשא דאיהו רישא לגבה כו', וכנודע דסיהרא היא בחי' מל' וההמשכה במל' היא משמש הוי' בחי' ז\"א כו', וא\"כ מה\"ע ראשי ל' רבים כו', אלא ראשי תרין בכל ירחא וירחא דאינון יעקב ויוסף, ופי' המק\"מ דיעקב ויוסף זהו ת\"ת ויסוד כו'. ולכאו' אינו מובן והלא ההמשכה מת\"ת הוא ג\"כ ע\"י יסוד וכנודע שכל ההמשכות הן מיסוד, וא\"כ מה מחשב יסוד לראש בפ\"ע ונשארה הקושי' וכי כמה ראשין אינון לסיהרא כו'. ולהבין זה ילה\"ק משנת\"ל דהאורות דאצי' ה\"ה בבחי' התלבשות פנימי בבחי' הכלים דאצי' שעי\"ז נעשים בבחי' מהות ומציאות דבר בבחי' אור החכ' ואור החסד כו'. וסיבת הדבר הוא מפני שהאורות גם בשרשן ומקורן כמו שהן כלולים באוא\"ס לפני הצמצום ה\"ה בבחי' ע\"ס, והיינו שאין זה האור שבבחי' א\"ס כ\"א מה שאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול כו', והגם דכמו שהם כלולים באוא\"ס ב\"ה ה\"ה בבחי' פשיטות לגמרי שאינן בבחי' מציאות ניכרות כו', מ\"מ בבחי' ע\"ס וכאשר נמשכו\nע\"י הצמצום בבחי' ספירות פרטיות ה\"ה בבחי' מציאות ניכרת עכ\"פ עם היותם בבחי' בלי מ\"ה כו', וכמו הקו העשוי מנקודות כו', וה\"ה בערך להתלבש בכלים כו', וע\"י ההתלבשות בהכלים נעשים כפי מהות הכלים בבחי' מציאות דבר בבחי' אור החכ' ואור החסד כו'.\nלג) <b>והנה</b> זהו ג\"כ סיבת ההתחלקות דמעלה ומטה שיש בע\"ס, שהרי הע\"ס דאצי' הן בבחי' מעלה ומטה שהחכ' היא למעלה במדרי' מהבינה והמוחין למעלה מהמדות כו' עד המל' שהיא סודכ\"ד דאצי' נק' מטה כו'. דבאוא\"ס עצומ\"ה לא יש ענין מעומ\"ט, וכמ\"ש בע\"ח בתחלתו טרם שנאצלו הנאצלים הי' אור עליון פשוט כו' ולא הי' בו מעלה ומטה ראש וסוף כו', ובע\"ס יש התחלקות מעומ\"ט כו'. והוא להיות שהע\"ס הן בבחי' התלבשות פנימי אורות בכלים ע\"כ לפי אופן הכלים מאיר בהם האור כו', וע\"כ הכלי שהיא בבחי' דקות ורוחניות יותר מאיר בה האור בריבוי ביותר ה\"ז בחי' מעלה והכלי שהיא בבחי' מציאות יותר שהאור בה בבחי' מיעוט ה\"ז בחי' מטה כו'. והרי כלי החכ' היא בבחי' דקות יותר הרבה מכלי הבינה, וכמו עד\"מ בהשכלת איזה ענין הרי אין השכלי בא בבחי' הלבשה עדיין, וכמו שנראה בחוש שאינה בא עדיין בריבוי אותיות ולא בענינים רבים כ\"א בבחי' נקודה מופשטת עדיין מהשגה כו', והגם שהנקודה כוללת הכל, שהרי כל הפרטים הבאים אח\"כ בהשגה הכל בא מהנקודה (עס ווערט אלץ ארויס\nגיטראגין מהנקודת השכלה), הרי הנקודה כוללת כל הפרטים. מ\"מ בהנקודה אינם ניכרים הפרטים כלל רק נקודת הענין לבד כו', וגבי חכם גדול ניכרים אצלו לעצמו הפרטים שבהנקודה, דבעת שנופל לו השכלה חדשה מאירים אצלו הפרטים שבה כו', ומ\"מ ה\"ז בהעלם ובבחי' מקיף (והיינו שגם לעצמו הוא בבחי' העלם ומקיף לגבי כללות השכלת הענין כו'), ומה שבהתגלות הוא רק נקודת השכלי לבד כו' (וזה ודאי שאין שם כלל ריבוי אותיות במציאות וגם לא הריבוי ענינים שבהם מתלבש הענין שכלי כו'). והו\"ע דקות הכלי כו', וע\"כ מאיר שם הענין שכלי ביותר בבחי'"],[3601330204,"הדקות והעילוי כו', וכאשר בא לידי השגה שנתפס בהרבה אותיות ובענינים רבים שכולם הם בבחי' תפיסה והשגה כו' מתמעט האור הרבה כו'. וכנראה בחוש דבהשגה והבנה הגם שמושג הענין יותר הרי מתעלם בחי' דקות האור של השכלי ואינו כלל כמו בנקודת ההשכלה כו' (ואח\"כ בנקודת התמצית שאחר ההשגה, והוא מה שלאחר שמבין ומשיג את הענין שכלי בכל הפרטים שבו ה\"ה מקשר א\"ע (טראגט זעך צוא) אל עצם הענין שכלי איך שהוא מושג מכל ההשגות פרטיות כו', ואז חוזר ומאיר בזה בחי' דקות האור להיות שזהו כמו שההתפשטות דבינה באה לבחי' אין להיות בבחי' נקודה לבד שנשלל בזה האורך ורוחב כו' והוא בחי' וחכם בבינה כו' וכמ\"ש במ\"א. ומ\"מ אינו בבחי' עילוי כ\"כ כמו בנקודת החכ', דבנקודת התמצית בא האור שכלי במורגש ובמציאות יותר כו', וממילא אין זה בחי' דקות עצם האור ממש כמו בנקודת החכ' כו'. להיות דנקודת החכ' היא בחי' אין שקודם להיש ונקודת התמצית היא מה שהיש נעשה אין כו', והיינו להיות דנקודת התמצית באה מן ההשגה הגם שזהו ביטול ההשגה (היינו שלילת כל האורך ורוחב\nכו') שנעשית בבחי' נקודה מ\"מ ה\"ז במציאות ובמורגש כו', ויש מעלה בנקודת התמצית בזכות ובירור השכלי ובבחי' התיישבות כו' וכמ\"ש במ\"א). וכ\"ז הוא שלפי אופן הכלי מאיר בהם האור והגילוי כו', וכן המדות שהכלים הם בבחי' מציאות דבר ובמורגש ביותר, דכללות ענין המדות הו\"ע הרגש עצמי דהיינו הרגש מציאותו כו', וכמו האהבה שאוהב איזה דבר זהו מפני שמרגיש א\"ע ומרגיש איך שהדבר טוב לפניו ה\"ה מתעורר באהבה כו', וכן היראה מפני שמרגיש איך שהדבר לא טוב כו', דבלתי הרגש עצמו לא הי' התעוררות המדות כלל כו'. וכנודע דלידת המדות הן מהדעת דוקא שהו\"ע ההרגש כו', דגם שמבין בשכלו איך שהדבר טוב אם אין לו שייכות אל הדבר והיינו שאין נפשו יקרה אצלו (שהו\"ע הרגש עצמי) לרצות בדבר הטוב לו, לא יתעורר כלל באהבה לזה כו', לפי שכל ענין המדות אינם באים ומתעוררי' רק ע\"י הרגש עצמו כו'. לבד מדות עצמיים וטבעים שאינם באים מצד השכל ולא מצד הרגש עצמו כ\"א מפני שזהו עצמו ומהותו כו', דאהבה זאת היא בחי' רצון לא אהבה כו', דמדת האהבה היא לא שהדבר האהוב הוא\nמעצמו ומהותו כ\"א מפני שהדבר טוב לו ובאה ע\"י הרגש עצמו כו', ואהבה עצמיות היא בחי' רצון והוא מה שרוצה בדבר שהוא עצמו ומהותו כו', וכמו אהבת האב אל הבן או אהבת הבן אל האב דהאהבה בזה הוא ענין הרצון שרוצה מה שהוא עצמו ומהותו בלא טו\"ד כלל כו'. ולכן הרצון תופס בהעצמות דוקא, וכמ\"ש במ\"א ההפרש בין אהבה לרצון דאהבה תופסת בההתפשטות והגילוים לבד, משא\"כ הרצון תופס בהעצם כו'. וכמו באהבת האוהב אל האהוב (באהבה התלוי' בדבר) דסיבת האהבה היא מפני שמשפיע לו מדת חסדו וטובו או מצד העילוי שלו הרי צריך לזה התבוננות להתבונן בהטוב וחסד שמשפיע לו כו', או להבין ולהשיג העילוי והיוקר שלו שעי\"ז היא האהבה כו', וממילא מה שתופסת האהבה היא רק בההתפשטות והגילוים שזהו סיבת האהבה ובזה הוא מתקשר ונדבק כו'. משא\"כ באהבת ורצון הבן בהאב הרי אינו צריך שום התבוננות כלל כי אין הרצון בא מצד השפעת טובו וחסדו או מצד העילוי שלו כ\"א מפני שהוא אביו היינו שהוא עצמו ומהותו, ובהרצון הוא תופס בהעצם ממש לא בהגילוים כו'. וכן הוא הענין ברוחניות דמדת האהבה היא שבאה ע\"י ההתבוננות בהעילוי והטוב באלקות ובמדת חסדו וטובו ית' כו', שהקירוב"],[3601330205,"והדביקות בזה הוא בהאור האלקי שבא בבחי' גילוי כו', אבל הרצון דבחי' רעו\"ד תופס בעצמות אוא\"ס ב\"ה וכמ\"ש מי לי בשמים ועמך לא חפצתי כו', שאינו רוצה בהאורות והגילוים כ\"א בבחי' אוא\"ס עצומ\"ה כו'. ולכן יכול להיות רצון גם כשלא יש אהבה וכמו באהבת אב ובן כשהבן אינו כדבעי ח\"ו דאז לא יש התגלות אהבה אליו ומ\"מ ישנו להרצון שבעצם הוא רוצה בבנו כו', דכן הוא הדוגמא למעלה דכתי' ואף גם זאת כו' לא מאסתים ולא געלתים כו', וכמארז\"ל בין כך ובין כך בני הם כו', והיינו בהרצון שזהו מפני שהוא עצמותו ומהותו כו'. אבל ענין מדת האהבה היא מצד הטעם ותלוי בהרגש עצמו דוקא כנ\"ל, וכן כל המדות הן דוקא ע\"י הרגש עצמי כו'. שזהו ההפרש בין מוחין למדות דהמוחין הן בבחי' ביטול והעדר הרגש עצמותו להיות דענין המוחין בכלל הן העלי' וההתקשרות לדבר שלמעלה ממנו שזה פועל ביטול מציאות עצמו כו' וכמ\"ש במ\"א, והמדות הן בבחי' הרגש עצמי דוקא כו', וע\"כ הגילוי במדות הוא למטה הרבה מבמוחין כו'. והגם שזה גופא מה שמשיג את טוב ה\"ז במוחין, הנה השגת המוחין הוא\nרק טוב הדבר בעצם לא מה שלו טוב כ\"א רק העילוי והיוקר של הדבר, ומה שבא במדות הוא רק מה שלו טוב כו'. וגם זאת דהשגת טוב הדבר זהו רק בחיצוניות המוחין והעיקר הוא במדות שבמוחין, דמוחין בעצם הן רק השגת עצם הדבר לא את הטוב של הדבר רק מה שמשיג עצם הענין, והשגת הדבר איך שהוא טוב שמתפעל במוחו ע\"ז זהו במדות שבמוחין כו'. וכ\"ז הוא רק השגת הטוב בעצם כו', ובמדות בא ההרגש איך שלו טוב הדבר שעי\"ז נעשה התעוררות המדות כו' וכמ\"ש במ\"א. ויובן זה בעבודת ה' דכשמתבונן באיזה ענין אלקי ומעמיק דעתו בזה הרי הענין האלקי מאיר במוחו ומה שנשאר במדות הוא רק מה שקרבת אלקים לו טוב, וכל האור שמאיר במוחו מתעלם בהתעוררות המדה כו', ונודע דבכדי שיהי' התעוררות המדות בהכרח שיהי' התעלמות המוחין דכאשר אור המוחין מאיר בגילוי א\"א להיות התעוררות המדה כ\"א כאשר מתעלם אור המוחין אז מתעורר המדה כו'. אך התעוררות המדה הוא מהבכן דהיינו מה שקרבת אלקים לו טוב כו' (רק בדרך מקיף נרגש אז האלקות על מה שנתפעל והיינו מה שהשיג במוחו כו'), ולכן המדות הן\nבבחי' התפעלות דכל התפעלות הוא חוץ לעצם היינו שהוא בריחוק מן העצם, דכאשר הוא בקירוב שהוא בתוך אותו דבר אינו שייך התפעלות על הדבר (שהרי הוא מתאחד עם אותו הדבר והו\"ע הדביקות כו', ואפי' אם אינו עדיין בבחי' התאחדות, מ\"מ כשהוא בתוך אותו הדבר טרדתו הוא בעצם הדבר ואינו שייך ההתפעלות אז כו'), וכל שמתפעל הוא מפני שמתרחק מעצם הדבר כו', והמדות ה\"ה בבחי' התפעלות שמתפעל על אלקות זהו מפני שהן בבחי' ריחוק מן העצם כו'. ובפרט מה שבמדות רוצה בהקירוב ודביקות באלקות שיהי' הגילוי בנפשו או בבחי' צמאון כו', הרי כ\"ז שייך בבחי' הריחוק דאז רוצה בהגילוי ואז הוא בבחי' צמאון כו' דבבחי' הקירוב הרי כ\"ז אינו שייך כלל כו'. ובד\"כ יש הפרש במוחין ג\"כ שזהו ההפרש בין חכ' לבינה, דבינה היא בבחי' התפעלות והתלהבות וחכ' היא בחשאי דוקא כו'. וכידוע ההפרש בין כהנים ללוים, דעבודת הכהנים הוא בחשאי וברעותא דליבא ועבודת הלוים הוא לארמא קלא בבחי' התלהבות כו', והוא ההפרש בין בחי' החכ' שהיא בבחי' ביטול ממש ובחי' בינה שהו\"ע השגה ה\"ז בבחי'\nיש ומציאות כו'. אמנם מוחין בכלל הן בבחי' הביטול ומאיר בהם גילוי אור כו', אך המדות הן בהתפעלות מורגשת בבחי'"],[3601330206,"יש ומציאות כו'. והנה בעבודה בהכרח שיהיו המדות אהוי\"ר בהתגלות הלב מפני שזה שייך לקיום המצות בפו\"מ, וכמ\"ש בסש\"ב דאהוי\"ר הן מקור מ\"ע ומל\"ת והמקיימן באמת הוא האוהב כו'. ועוד שעי\"ז דוקא נעשה הזיכוך ובירור דנה\"ב כו', דבעבודה דמוחין לבד אינו ניתק עדיין מחומריות הנה\"ב (רק מי שעבודתו היא בדרך מלמעלמ\"ט כו') כ\"א ע\"י העבודה דאהוי\"ר דוקא, כי הנה\"ב עיקרו הוא מדות כמ\"ש במ\"א, וע\"כ גם התלבשות הנה\"א בנה\"ב עיקרו בבחי' המדות שבו ובזה דוקא הוא פועל הבירור דנה\"ב כו'. ולכן בעבודה דמוחין עם היותו בבחי' קירוב ודביקות במוחו יכול להיות שהחומריות דנה\"ב הוא במקומו ובתקפו עדיין כו', ורק באהוי\"ר בהתגלות הלב פועל חלישות בנה\"ב שנחלש חומריותו וגם ביטל החומרי והמורגש דנה\"ב כו' וכמ\"ש במ\"א. וע\"כ אין להסתפק בעבודה דמוחין לבד כ\"א צ\"ל העבודה באהוי\"ר שבלב כו', אמנם מצד הגילוי יש יתרון גדול במוחין דלהיותם בבחי' ביטול מאיר בהם גילוי אור, והמדות להיותם בבחי' מציאות מתמעט בהם האור שאינו מאיר בהם בגילוי כלל כמו במוחין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה ע\"י התלבשות האורות בכלים ה\"ה בבחי' התחלקות דמעומ\"ט, וכמו בכחות הנפש כח החכ' שהיא ההשכלה בבחי' נקודה מופשטת עדיין מאיר בה דקות עצם האור, וכח הבינה שהיא השגה, ה\"ה מעלמת על האור שבחכ' (ובנקודת התמצית מאיר דקות עצם האור אבל הוא במורגש) והמדות הן הרגש עצמו, ולכן באין ע\"י הדעת דוקא ואהבה עצמיות אינה מדה כ\"א רצון, שרוצה מה שהוא עצמו ומהותו, והמדה הוא שרוצה רק מה שטוב לו, ולכן המדה תופס בהמציאות והרצון תופס בהעצם. וכן הוא ברוחניות, ויכול להיות רצון בלא אהבה, ומה שהמדות באין מהמוחין זהו רק מהמדות שבמוחין, ושם הוא רק הרגש עצם הטוב, ובמדות הרגש הלו טוב, והו\"ע קרבת אלקים לי טוב, ולכן התעוררות המדות הוא דוקא לאחר התעלמות המוחין, והן בבחי' התפעלות ולכן האור בהם במיעוט ובמוחין ג\"כ עיקר הביטול בחכ', ובעבודה בהכרח שיהיו מדות בהתגלות שעי\"ז הוא קיום המצות, ועי\"ז הוא התיקון דנה\"ב.</span>\nלד) <b>והדוגמא</b> מזה יובן למעלה דבחכ' מאיר ריבוי אור לפי שחכ' היא בבחי' מיעוט הכלים, וכידוע דבחכ' גם הכלי היא בערך אל האור כו' (בפרדס שער השמות דהש' דחכ' הוא י\"ה, ובהגהות לביאור דוארא תקס\"ח כ' דהרי בת\"ת שהוא בריח התיכון הכלי היא שם הוי', כ\"ש חכ' שמשם מקור המשכת בריח התיכון שהכלי היא כמו האור כו'. ובמ\"א אי' וז\"ל כי הוי' הוא האורות דאצי' ושם אלקים הוא הכלי והכלים הם ג' בחי' כו', וא\"כ ע\"י הבינה הוא התחברות האור עם הכלי לכן הוא הוי' בניקוד אלקים כו', אבל חכ' נק' הוי' לבד כי שם רק איהו וחיוהי חד למעלה מבחי' גרמוהי כו' עכ\"ל, ועמ\"ש בדרוש דג' מיני אדם), ובד\"כ הרי חכ' היא בחי' נקודה לבד שהוא בחי' אין ע\"כ מאיר שם האור בריבוי כו', ובבינה נתמעט האור לפי שהכלים דבינה הם בבחי' מציאות דהשם דבינה הוא הוי' בניקוד אלקים דאלקים הו\"ע הכלים כו', דבינה היא בחי' השגה שזהו בחי' יש ומציאות וכמ\"ש להנחיל אוהבי יש כו', ולהיות שהכלים הם בבחי' מציאות ע\"כ האור הוא בבחי' מיעוט כו'. וכמארז\"ל גבי מי השילוח שהיו מקלחין כאיסר"],[3601330207,"הרחיבו נתמעטו מימיו, והיינו דבבחי' מיעוט הכלים מאיר גילוי אור וכשנתרחבו הכלים נתמעט האור כו'. וזהו דבינה להיותה בבחי' התרחבות הכלים מתמעט האור והגילוי כו', וכידוע דבינה מעלים על החכ' דזהו מ\"ש והניף ידו על הנהר ונודע דנהר היא בחי' בינה, ולעתיד יהי' בקיעת הנהר בכדי שיהי' גילוי פנימיות התורה שזהו גילוי בחי' החכ' כו'. דכשם שקרי\"ס הי' הכנה למ\"ת דקודם מ\"ת הי' צ\"ל קרי\"ס, דים הוא בחי' מל' שכונסת ומעלמת בתוכה אורות דאצי' כו', ובכדי שיהי' מ\"ת שזהו גילוי אצי' הי' צ\"ל קריעת הים וההעלם כו'. כמו\"כ לעתיד בכדי שיתגלה פנימיות התורה שהיא גילוי בחי' עצם החכ' צ\"ל בקיעת הנהר, והיינו מפני שהבינה להיותה בבחי' מציאות ה\"ה מעלמת על האור וע\"כ צ\"ל בקיעת הנהר כו', ואח\"כ בז\"א וכ\"ש במל' ששם עיקר ענין הכלים האור שם במיעוט ביותר כו'. וזהו מה שלפעמים מצינו שבמדרי' העליונות המספר המרובה יותר ובמדרי' תחתונות מתמעט המספר ולפעמים בהיפך, וכידוע בענין יחידות עשירות מאות דיחידות במל' ועשירות בז\"א ומאות בחו\"ב, או דיחידות הן\nבז\"א ומל' ועשירות בחו\"ב ומאה בכתר, וכידוע ממ\"ש ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים דשבע בז\"א ועשרים בחו\"ב ומאה בכתר, וכמ\"ש בזהר קוב\"ה דאתכליל מאתר עילאה סדכ\"ס ברזא דמאה ברכאין כו' וכמ\"ש במ\"א באריכות על מאה\"ז הנ\"ל, וגם אלף ורבבה הן בכתר וכמ\"ש בלק\"ת ד\"ה ואתא מרבבות קדש. ולפעמים שהמספר המועט הוא במדרי' העליונות דוקא וכל שלמטה יותר מתרבה המספר, וכמו אנת חד ולא בחושבן הרי ידוע שזהו בפנימיות הכתר דוקא כו', ועיקר ריבוי המספר הוא בבחי' מל', וכמ\"ש כי אלף שנה בעיניך כיום אתמול דיום א' דז\"א בא במל' במספר אלף כו'. ומבו' במ\"א שזהו ההפרש בין האורות להכלים דמצד האורות כל מה שלמעלה מספר המרובה יותר, ולא שהן בבחי' מספר רק שהוא בבחי' ריבוי האור כו', וכל מה שיורד למטה יותר מתמעט האור והגילוי כו'. ומצד הכלים למעלה יותר הוא מספר המועט דהיינו בחי' מיעוט הכלים, וכל מה שיורד למטה יותר מתרבים הכלים כו' (ועמשית\"ל פ'). וכמו עד\"מ בהשפעת השכל מהרב אל התלמיד הרי הרב אינו משפיע את השכל כמו שהוא לעצמו רק אפס\nקצהו לבד, וכן התלמיד כשמשפיע לתלמיד קטן ג\"כ אינו משפיע השכל כמו שהוא אצלו הרי שהאור מתמעט ממדרי' למדרי' כו', ומצד הכלים הרי כל שבאה ההשפעה למטה היא בריבוי אותיות ובריבוי ענינים שהמשפיע לעצמו א\"צ לכ\"ז רק בשביל המקבל כו'. וכמו\"כ במדרי' עליונות יותר האור בריבוי והכלים במיעוט וכל מה שנמשך למטה בחי' ריבוי הכלים ומיעוט האור כו', והא בהא תלי' דבבחי' מיעוט הכלים הוא ריבוי האור וכשהכלים הם בריבוי מתמעט האור כו'. וזהו מ\"ש לעתיד והנער בן מאה שנה דנער הוא בחי' קטנות בבחי' מיעוט האור, יתעלה לעתיד בבחי' מאה למעלה מזקנה ושיבה שהוא ששים ושבעים שנה וכמ\"ש ימי שנותינו בהם שבעים שנה, ומאה למעלה מזה, וז\"ש ונערים פני זקנים ילבינו דנערים יהיו למעלה מזקנים כו'. והענין הוא דהנה שבעים שנה הן ז\"ת דכתר בחי' אור שבעת הימים ומאה הו\"ע ג\"ר דכתר, וזהו והנער בן מאה הוא שיתעלה בבחי' ג\"ר דכתר כו'. וזהו מה שבעליית האדם עכשיו ארז\"ל במשנה דאבות בן חמש למקרא בן עשרה למשנה כו' בן מאה כאלו מת ועבר ובטל מן העולם, והקשו המפרשים\nשהרי במשנה זאת חשיב הכל מעלת האדם שעולה ממדרי' למדרי', ומהו המעלה בזה שכאלו מת כו'. אך הענין הוא שזהו מה"],[3601330208,"שבמיתתן רואין, דהנה כתי' כי לא יראני האדם וחי בחייהן אינן רואין אבל במיתתן רואין, והיינו בבחי' ראיית המהות והעצמית דא\"ס ב\"ה עז\"נ כי לא יראני האדם וחי, אבל במיתתן רואין כו', וזהו כאלו מת שהו\"ע במיתתן רואין והו\"ע עולמך תראה בחייך כו', והיינו להיותו בן מאה שיתעלה בבחי' פנימיות הכתר כו', וזהו ע\"י ההקדמה דבחי' שבעים שנה, דימי שנותינו בהם הו\"ע בירור הנה\"ב שע\"ז נקצבו ימי האדם שבעים שנה שהן נגד ז\"מ כו', וכאשר מברר הז\"מ רעות דנה\"ב ה\"ה זוכה לבחי' במיתתן רואין כו'. וזהו\"ע בן מאה בחי' הכתר בחי' ריבוי האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא מזה למעלה דכלי החכ' היא בחי' אין היא בבחי' ריבוי האור, ובינה בחי' יש היא בבחי' מיעוט האור ומעלמת על אור החכ', ולכן לעתיד והניף ידו על הנהר, ובז\"א ומל' המיעוט יותר, ולכן לפעמים למעלה יותר הוא מספר המועט דהיינו בהכלים, ולפעמים למעלה מספר המרובה שזהו בהאורות, וזהו בן מאה כאלו מת היינו (ביטול הכלי ו)ריבוי האור, ולעתיד הנער בן מאה שיתעלה בבחי' הכתר.</span>\nלה) <b>והנה</b> כשם שבע\"ס יש התחלקות מעומ\"ט, כמו\"כ יש התחלקות מעומ\"ט גם בעולמות, וכידוע דכללות ההשתל' נבחן בג' מדרי' והן ג' עולמות בי\"ע כו'. וכמו עד\"מ האדם נחלק לג' חלקים כללים הן בכחות נפשו והן בגוף, והן ראש גוף ורגל דברגל הוא כח ההילוך שהוא כח היותר אחרון שבנפש, דהגם שכח ההילוך הוא ג\"כ לצורך הנפש וגם יש יתרון בכח ההילוך שהוא נושא את הראש ומעמיד את הראש כו', מ\"מ ה\"ה כח היותר אחרון שאור הנפש בו במיעוט הגילוי ביותר כו', ובגוף מאיר אור הנפש יותר שהרי בגוף הן האברים הפנימים שחיות האדם תלוי בהם וכמו הלב והריאה כו', וגם המדות שבנפש משכנם בלב כו', ואפי' באברים החיצונים שבגוף יש בהם גילוי אור הנפש יותר מברגל, וכמו ביד שבו כח התנועה לכתוב ולצייר דבר ולעשות בו איזה מלאכה, דעצם הכח הוא למעלה מכח ההילוך עם היות שזה ג\"כ רק כח המעשה מ\"מ ה\"ה למעלה מכח ההילוך שברגל וגם יש בו התלבשות אור השכל כו', והגם שבכח ההילוך יש ג\"כ התלבשות השכל מ\"מ אין זה כלל כמו אור השכל המתלבש בכח התנועה שביד כו' וכמ\"ש\nבמ\"א. ובראש מאיר אור הנפש בריבוי יותר כו', דהגם דבעצם חיות הנפש הראש והלב שוין, מ\"מ בהכחות אינם שוין שהרי בראש הוא גילוי המוחין וכל החושים הנעלים כמו ראי' ושמיעה כו', הרי עיקר גילוי אור הנפש הוא בראש והעיקר במוח שבראש כו'. וענין רעו\"ד שהוא בלב דוקא, הנה יש בזה ב' אופנים, הא' מה שבא ג\"כ ע\"י התבוננות שבמוח רק שההתבוננות היא בהאוא\"ס שלמע' מהשתל' כו' וכמ\"ש במ\"א, והב' שיש בחי' רעו\"ד שאינה ע\"י ההתבוננות כלל כ\"א מצד העצם כו', ה\"ז נקודה העצמית שבנפש שלמעלה מגדר כחות שהיא נאחזת בלב וה\"ה למעלה מכחות וכמ\"ש במ\"א. אך בכחות הנפש עיקר גילוי אור הנפש הוא בראש כו', ומצד הכלים ואברי הגוף הרי הראש הוא החלק היותר קטן שבגוף, וחלק הגוף גדול ממנו וחלק הרגלים יותר גדול, הרי שבהכלים הרגל הוא בריבוי הכלים יותר מהראש, ובהאור הוא להיפך דבראש מאיר אור הנפש בריבוי ובגוף מתמעט האור וברגל מתמעט ביותר כו'. וכמו\"כ הוא הדוגמא למעלה בג' עולמות בי\"ע דבעולם הבריאה מאיר"],[3601330209,"עדיין גילוי האור דלהיות שעולם הבריאה הוא היש הראשון שנברא מהאין האלקי מאיר שם עדיין גילוי האין כו', ולכן הבריאה נק' חשך וכמ\"ש יוצר אור ובורא חשך, והיינו לפי שבבריאה מאיר גילוי אור ה\"ז בבחי' חשך והעלם לגבי למטה כו', ויצי' שאין האור שם בגילוי כ\"כ ה\"ז בבחי' אור וגילוי לגבי למטה כו'. ומצד הכלים הוא להיפך דבריאה היא בבחי' מיעוט הכלים וביצי' הוא ריבוי הכלים, וכנודע דברי' ויצי' הן מח' ודבור והרי אנו רואין דמה שמחשב במח' במיעוט זמן ובמיעוט אותיות ה\"ז בא בדבור בריבוי זמן ובריבוי אותיות כו', וגם אותיות המח' הן אותיות רוחני' שאינן מורגשים אל הזולת, משא\"כ אותיות הדבור הן מורגשים אל הזולת כו', דכמו\"כ בחי' הכלים דבריאה הן בבחי' מיעוט הכלים דהיינו מיעוט הישות והמציאות ויצי' הוא בבחי' ריבוי הכלים כו'. וזהו הטעם מה שיחזקאל מאריך הרבה בענין המרכבה וישעי' אינו מאריך כ\"כ, והיינו מפני שיחזקאל ראה את המרכבה דעולם היצי' שהוא בבחי' ריבוי הכלים וע\"כ מאריך בהענין, וישעי' ראה מרכבה דבריאה שהיא בבחי' מיעוט הכלים\nכו', ומצד האור אדרבה בבריאה מאיר ריבוי אור וביצי' מתמעט האור כו'. והא בהא תליא דכשהכלים הן בבחי' מיעוט שהן כלים יותר אל האור מאיר שם ריבוי האור ובריבוי הכלים מתמעט האור כו'. וכן גם כללות העולמות נחלקים לג' מדרי' כללים אדם דברי' דכללות ואדם דיצי' ואדם דעשי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו יש התחלקות מעומ\"ט בעולמות, וכמו באדם הראש היא כלי קטנה ובה גילוי הכחות נעלים שבנפש, והגוף גדול ובו משכן המדות וכחות חיצונים (ורעו\"ד הוא ג\"כ ע\"י התבוננות, או שזהו עצמי) וברגל מיעוט האור, וכמו\"כ בברי' שהכלים אינם במציאות עדיין מאיר גילוי האור, וביצי' שהכלים במציאות הוא מיעוט האור, מח' ודבור, ולכן יחזקאל האריך בענין המרכבה וכ\"ה בבי\"ע הכללים.</span>\nלו) <b>אמנם</b> באמת אין זה רק מצד הכלים כ\"א שיש מדידה בהאור באיזה אופן הוא נמשך להאיר בכל ספי' כו', וגם המדידה בהכלים באיזה אופן יהיו הוא כפי מדידת האור כו', והיינו שלפי המדידה באיזה אופן יהי' בחי' החכ' נמדדה כלי החכ' באופן כך בכדי שתקבל האור והגילוי דבחי' החכ' וכה\"ג בשארי הספי' כו'. והענין הוא כמשנת\"ל פ\"ח דמהתעבות האור נעשה הכלי דעם היות שיש לכלים שרש מיוחד משרש האורות מ\"מ ההתהוות בפועל דכלים הוא ע\"י אמצעות האור כו', וע\"כ נתהווה הכלי כפי אופן האור היינו שתהי' מוכנת לקבל את האור כו'. ועיקר המדידה הוא בהאור באיזה אופן יאיר בעולמות כו' (וי\"ל דבשרש הראשון מדידת הכלים קדום למדידת האור דתכלית הכוונה הוא בהתהוות הכלים כו' והוא מה שבנין החומר קדום בשרשו להצורה כו'. וזהו הטעם מה שהכלים למע' ממשיכים את האו', ולא כמו הכלים למטה שרק מקבלים הדבר הניתן בתוכן אבל למע' הכלים ממשיכים את האור, וכמו איברי הגוף שממשיכים את החיות, מפני ששרש הכלים קדום אל האור כו'. אמנם זהו לאחר זיכוך הכלי שלפי אופן\nהזיכוך שלה ממשכת את האור כו', ובתחלת ההתהוות הרי מהתעבות האור נעשה הכלי כו'. וכן הוא בהמדידה דבשרשם מדידת הכלים קדום למדידת האורות ורק בהתגלות"],[3601330210,"מדידת האור קדום כו'. והו\"ע דבמח' ארץ קדמה ובהתהוות שמים קדמו כו'). וכמ\"ש בע\"ח דהמשכת הקו הוא בכדי לעשות מעלה ומטה כו', דאם הי' ההמשכה שלא ע\"י הקו לא הי' מעלה ומטה בעולמות דכל עולם הי' בהשוואה בכל חלקיו ולא היו ניכרים בו חלקי י\"ס כו' כמ\"ש במבו\"ש, וע\"כ הוא ההמשכה ע\"י הקו בכדי שיהי' מעלה ומטה כו', דלהיות שהקו בקצהו העליון נוגע ודבוק באוא\"ס ב\"ה ובקצהו התחתון אינו נמשך עד האור א\"ס הסובב תחת העולמות ואינו דבוק בו, הרי עי\"ז יש בהקו ראש וסוף ומעלה ומטה כו', ועי\"ז יש בעולמות וספי' ג\"כ מעלה ומטה דהמקבלים מעליונו של קו שקרוב יותר אל האור א\"ס שהוא בחי' מעלה שבו ה\"ה בבחי' מעלה וכל מה שמתרחק מקצהו העליון ה\"ז בבחי' מטה כו'. וזהו שהקו נק' קו המדה (עמ\"ש בהבי' דועתה יגדל שלא נדפס, וי\"ל דמקור הדבר הוא מע\"ח הנ\"ל) להיות שע\"י הקו הוא מדידת האורות, אם ההמשכה היא מעליונו של הקו וכמו פרצוף דא\"ק שמקבל מבחי' העליונה של הקו שהוא בקירוב לאוא\"ס ב\"ה, והעולמות שלמטה מא\"ק מקבלים בבחי' ריחוק כו', וכן הוא בכל ספי' בפרט\nכו'. שזהו מ\"ש בע\"ח דבכתר וחכ' מאיר אוא\"ס בקירוב מקום ובבינה בבחי' ריחוק כו', והיינו שבבינה מאיר האוא\"ס כמו שהוא בגדר השגה ובחכ' מאיר האוא\"ס כמו שהוא למע' מגדר השגה עדיין כו' וכמשי\"ת. וידוע ג\"כ שיש צינורות פרטים לכל ספי' בפרט כו', ועמ\"ש מזה בבה\"ז פ' וישלח ע\"פ כי ישרים דרכי ה' כו'. ובפרד\"ס בשעה\"כ אות ש' כ' שיעור קומה שהנשמה המתאחדת בתוך הספי' נק' שיעור מפני שהיא הנותנת שיעור לכל הקומה והיא האומרת לספי' די כו', וכן כ' בשער עצמות וכלים פ\"ז (ולפמ\"ש שם זהו רצון המאציל ב\"ה בענין הספי', ולפי מ\"ש בע\"ח הוא לפי מה שכבר נמדד בהרצון עליון באופן המשכת הקו בבחי' הקירוב והריחוק שבו כו'). ונמצא דהמדידה דמעומ\"ט הוא בהאור באיזה אופן הוא נמשך בהספי' כו', הרי שבע\"ס יש התחלקות מעומ\"ט הן בהאורות והן בהכלים, איך שיהי' אם שהמדידה הוא בהאור ובאופן כזה נתהווה הכלי או שהמדידה היא בהכלי ובאופן כזה תמשיך את האור כו'. דבאמת שניהם אמת דבתחלת ההתגלות המדידה היא בהאור באיזה אופן יאיר ויתגלה דלפי אופן זה הוא התהוות הכלים\nכו', ואח\"כ לפי אופן זיכוך הכלים ממשיכים את האור כו'. וכ\"ז אינו שייך רק באורות פנימיים שבאים בבחי' התלבשות בכלים שיש בהם המדידה בבחי' התחלקות דמעלה ומטה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ובראשי חדשיכם, והקשה בזהר וכי כמה ראשין אינון והלא לית רישא לסיהרא אלא שמשא אלא ראשי תרין יעקב ויוסף. והענין הוא דהנה אי' במאו\"א דתפלת מוסף הוא בחי' יסוד שבא בסוד תוס' והו\"ע יחוד ישראל ורחל כו', דזהו ההפרש בין שחרית למוסף דתפלת שחרית הוא יחוד יעקב ורחל ותפלת מוסף הוא יחוד ישראל ורחל, דיעקב הוא ל' בקיעה כמו אז יבקע כשחר כו' שאינו רק הארה לבד וישראל הוא בחי' עצמית כו', ושניהם הם בחי' חכ' בחי' יסוד אבא רק יעקב הוא בחי' הארת החכ' וישראל בחי' עצמית החכ' כו'. וכמ\"ש בלק\"ת מהאריז\"ל ע\"פ ויקם עדות ביעקב ותורה שם בישראל, דיעקב הוא בחי' עדות לבד לא עצם הדבר כו' וישראל הוא בחי' עצמות הדבר כו', והו\"ע אירוסין ונשואין דאירוסין הו\"ע נובלות חכ' שלמע' תורה ונשואין המשכה עצמית מבחי' עצמות החכ' כו', והו\"ע חיצוני' התורה ופנימית התורה, דחיצוניות התורה היא מבחי'"],[3601330211,"חיצוני' החכ' דבד\"כ ה\"ז הארה לבד לא העצם ממש כו', ופנימי' התורה היא פנימיות ועצמות החכ' כו', וכללות ענין היחודים שייכים רק בהאור פנימי לפי שבא בבחי' התחלקות המדרי' שייך בזה ענין היחודים כו'. וזהו ראשי תרין יעקב ויוסף דפי' המק\"מ שזהו ת\"ת ויסוד, והיינו דיעקב הוא המשכת הארה כנ\"ל, אמנם בחי' יוסף היינו עיקר בחי' היסוד שהוא המשכת בחי' פנימיות ועצמות אוא\"ס ב\"ה. וזהו בן פורת יוסף ברא דיסגי יוסף בחי' תוס' אור מה שתוספתו של הקב\"ה מרובה על העיקר כו', והוא בחי' ריבוי אור בבחי' גילוי אור עצמי כו'. והענין הוא דכל ההשפעות הן ע\"י יסוד רק שבזה יש ב' מדרי' השפעה חיצונית והשפעה פנימיות ועיקר בחי' יוסף הוא בחי' השפעה פנימיות כו'. וכ\"ז שייך רק בהאור פנימי שיש בו מעומ\"ט ריבוי ומיעוט כו'. וזהו דלית רישא לסיהרא אלא שמשא דהאמת כן הוא דכל ההשפעות במל' הוא מבחי' שמש ה' בחי' אור פנימי כו', ובזה יש ב' מיני יחודים כנ\"ל. וזהו ובראשי חדשיכם דבכל ירחא וירחא נמשכים ב' היחודים והן בחי' יעקב ויוסף דיעקב הוא בחי' הארה לבד\nבחי' השפעה חיצוניות ויוסף הוא בחי' השפעה פנימית ועצמית, והו\"ע ברא דיסגי יוסף שנמשך בחי' אור עצמי בגילוי בבחי' מל' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובאמת אין זה רק מצד הכלי, כ\"א שיש מדידה בהאור, ולפי אופן זה הוא מדידת הכלי, דמהתעבות נעשה הכלי באופן שתקבל האור, וכמ\"ש בע\"ח ובמב\"ש דהקו עושה מעומ\"ט, ובפרדס שנשמת היא הנותנת שיעור לכל הקומה, ושניהם אמת דמדידת הכלי היא לפי מדידות האור (דלאור שבבחי' מעלה הכלי לזה הוא רק מיעוט הכלי) ואח\"כ לפי אופן זיכוך הכלי ממשכת את האור, וע\"פ הנ\"ל ית' מ\"ש ובראשי חדשיכם.</span>"],[3601330212,"<h3>בס\"ד. ש\"פ מטו\"מ, תער\"ב</h3>\n<b>וידבר</b> משה אל ראשי המטות לבנ\"י לאמר זה הדבר אשר צוה ה' כו'. וצ\"ל מהו\"ע זה הדבר אשר צוה ה' דהו\"ל להתחיל בענין הנדרים איש כי ידור כו' מהו ההקדמה שמקדים תחלה זה הדבר כו'. גם צ\"ל מפני מה נאמרה פ' נדרים לראשי המטות דוקא והלא התורה נאמרה לכל ישראל ומה נשתנה פ' נדרים שנאמרה דוקא לראשי המטות כו'. ולהבין זה ילה\"ק משנת\"ל דבע\"ס יש התחלקות מעלה ומטה והוא מפני שהאורות הן אורות פנימיים שבאים בבחי' התלבשות בכלים יש בהם מדידה באופן ההמשכה וההתגלות שלהם שאינם בשוה בכל המדרי' והו\"ע ההתחלקות מעומ\"ט שבהם.\nלז) <b>והנה</b> בענין מעלה ומטה ר\"ל מה נק' מעלה ומטה, מבואר במ\"א שזהו בבחי' ריבוי ומיעוט, דזה שמתמעט האור ממדרי' למדרי' זהו בחי' מטה כו',"],[3601330213,"וזהו ג\"כ ענין קירוב וריחוק דבקרוב מאיר האור בגילוי יותר דזהו ריבוי האור והגילוי, וכל מה שמתרחק מתעלם ומתמעט האור כו', וזהו ג\"כ ענין מעלה ומטה שבהמשכת הקו שהו\"ע קירוב וריחוק כמ\"ש במבו\"ש ש\"א פ\"ב, היינו דבקצהו העליון שהוא בבחי' קירוב אל מקורו מאיר שם האור בגילוי יותר וכל מה שנמשך ומתרחק ממקורו מתמעט ומתעלם האור כו'. וכמו עד\"מ באור הנר או גם באור אבוקה שבקירוב מאיר הרבה, ובריחוק מקום אינו מאיר כ\"כ עם היותו אותו האור עצמו רק כשנתרחק ממקורו ה\"ה מתעלם ומתמעט כו' (ובמשל הגשמי הוא שנכלה האור שזה אינו שייך ח\"ו ברוחניות רק מה שמתעלם שז\"ע המיעוט כו'). וזהו מ\"ש בע\"ח דבחכ' מאיר אוא\"ס בקירוב מקום ובבינה בריחוק מקום ובז\"א דרך חלון ובמל' דרך נקב כו', דבחכ' מאיר האור בגילוי יותר, וכמו עד\"מ בהשכלת איזה שכל הרי בנקודת ההשכלה דחכ' מאיר האור שכל בגילוי אור רב, הגם שאינו משיג עדיין את הענין שכלי איך ומה הוא, מ\"מ ה\"ה מאיר שם בגילוי ביותר, וכאשר בא בהשגה בבינה מתמעט האור, עם היות דעיקר השגת הענין הוא בבינה,\nדחכ' הגם שהיא ג\"כ ידיעה מ\"מ אינה השגה כו' וכמשי\"ת, וענין ההשגה הוא בבינה דוקא, ומ\"מ בחכ' הגילוי הוא בבחי' אור רב יותר מכמו בבינה כו' וכמשנת\"ל פל\"ג. ומ\"מ גם בבינה מאיר האור בהתרחבות דמוחין בכלל מאיר בהם גילוי אור כו', משא\"כ בז\"א הוא דרך חלון שהיא בבחי' מיעוט יותר כו'. וכמו עד\"מ אור השמש הרי מחוץ לבית הוא מאיר בהתרחבות בכל שטח המקום, ובבית מאיר רק דרך החלון שהדפנות מסתירים על האור שאינו מאיר בהתרחבות תוך הבית רק דרך החלון לבד שהאור הוא במיעוט יותר מכמו שהוא מחוץ לבית כו', ולכן ארז\"ל אכסדרה לאורה נבדקת מפני שהאור שם בריבוי משא\"כ הבית כו'. וכמו\"כ יובן דבז\"א כשמאיר רק דרך חלון ה\"ז בבחי' מיעוט האור כו'. וכמו עד\"מ פסק דין הבא לאחר אריכות הפלפול בכמה טעמים וסברות, הרי בהפסק דין אינן ניכרים הטעמים והסברות רק מה שפוסק כך וכך, ובהכרח לומר שבהעלם יש בזה כל האריכות שהרי הפסק דין בא מכל אריכות הפלפול, הרי בהכרח יש בו כל הטעמים והסברות רק שהן בהעלם ואינם ניכרים בגילוי כו'. וכמו המשנה ה\"ז קיצור שבא אחר\nהאריכות שהי' אצלם כל הענין בריבוי טעמים וסברות ופלפול גדול וכ\"ז בא במשנה בדרך קצרה ואח\"כ בגמ' מתרחב הענין כו', ולכן מי שהוא חכם גדול הרי מל' הקצר דהמשנה באותיו' קצרים יודע הוא את כל האריכות ובהמשנה הוא בהעלם כו'. וכמו סוכה שהיא גבוה מעשרים אמה פסולה ויש בזה טעמים משום שלמעלה מכ' אין אדם דר בצל סוכה או משום דלא שלטא בי' עינא כו', שיש בזה ענינים מחולקים, והכל יש בהקיצור דהמשנה רק שהוא בהעלם כו'. והו\"ע מיעוט האור דעם היות שישנו בהעלם אינו מאיר בגילוי ומה שהוא בגילוי הוא בבחי' מיעוט האור כו'. וכן הוא במוחין ומדות שהמדות הן בבחי' מיעוט האור והגילוי לגבי המוחין, וכמו בהתבוננות בענין אלקי שעי\"ז מתעורר באהוי\"ר הרי מה שמאיר מהמוחין בהמדות הוא רק אפס קצהו לבד כו', והארה מהמוחין בהכרח שיהי' בהמדות דאל\"כ לא יהי' התעוררות המדות (ובהארה זו יש בה בהעלם האריכות שבההתבוננות כו'), רק שהוא בבחי' מיעוט אור כו'. וכמו\"כ הוא למע' דבבינה מאיר האור בהתרחבות ובז\"א רק דרך חלון בבחי' מיעוט האור כו', ובמל' האור דרך\nנקב לבד, וכמו עד\"מ שמגלה את המדות בדבור וכמו כשמדבר דברי אהבה או שהאהבה היא סבת הדיבור דמצד האהבה הוא מדבר"],[3601330214,"עמו, הרי הדיבור מגלה מדת האהבה שהרי השנאה היא היפך הדיבור, וכמו איזה שונא כל שלא דיבר עמו כו', ומ\"מ מה שהדיבור מגלה ה\"ז רק הארה לבד מהמדה, והראי' שהרי בתוקף התפעלות המדות אינו יכול לדבר רק כשהמדה מתצמצמת יכול לדבר ומאיר בזה רק הארה לבד מהמדה כו', וכמו\"כ הוא בבחי' המל' שמאיר האור בצמצום ומיעוט בבחי' נקב לבד כו', וזהו\"ע מעלה ומטה שבע\"ס דבחי' ריבוי האור הוא בחי' מעלה ומיעוט האור הוא בבחי' מטה כו', וע\"כ החכ' היא בבחי' מעלה לגבי הבינה מפני שבחכ' מאיר האור בריבוי יותר כו', וכן המוחין הן בבחי' מעלה לגבי המדות כו'. אבל כאשר האור והגילוי הוא בשוה בכל הספי' עם היות שהן מחולקים במדריגתן בעצם (והו\"ע ראש וסוף כו') אין זה בבחי' מעומ\"ט כו', וכמו בהתגלות כחות עצמיים הגם שהמוחין בעצם הן במדרי' עליונה מהמדות, מ\"מ מאחר שאור הנפש מאיר בהם בשוה אין זה בבחי' מעומ\"ט כו', וכמו\"כ הוא בהדוגמא למעלה כמו בעולם התהו שלא הי' בבחי' מעומ\"ט כו' וכמ\"ש במ\"א.\n<span data-k=\"ks\"><b>קיצור.</b> והנה מעומ\"ט הו\"ע ריבוי ומיעוט (וסיבתם הוא הקירוב והריחוק) דריבוי האור והגילוי הוא בחי' מעלה, והעלם ומיעוט האור הוא בחי' מטה, וע\"כ החכ' היא בחי' מעלה מפני ריבוי האור, וכמו בנקודת ההשכלה שהאור בריבוי ובהשגה מתמעט ומתעלם האור, ומ\"מ הוא בהתרחבות, ובמדות מתמעט יותר וכמו בפס\"ד וכמו במשנה שכל האריכות הוא בהעלם, ובדבור גם המדות הן בהעלם. וכחות עצמיים שהאור בהם בשוה הגם שהן בבחי' ראש וסוף, אינם בבחי' מעומ\"ט, וכ\"ה בספי' דתהו.</span>\nלח) <b>אמנם</b> זהו בענין השתל' הספי' זמ\"ז, וכן בהתהוות העולמות זמ\"ז, דבכדי שיהי' הספי' התחתונה מהעליונה הוא ע\"י מיעוט האור כו', וכמו השתל' הבינה מהחכ' הוא ע\"י מיעוט האור בבחי' החכ' עצמה דאם הי' הגילוי בכל ספי' החכ' בשוה בבחי' ריבוי האור לא הי' נאצל ממנה ספי' הבינה כו', כ\"א ע\"י שמתמעט האור בבחי' החכ' שזהו בחי' יסוד אבא שמזה נאצל בחי' הבינה כו', כי אבא בעצם דהיינו עצמות החכ' הגם שהיא ג\"כ ידיעה ה\"ז למעלה משכל מושג כו' וכמשי\"ת, ואם הי' הגילוי בחכ' כמו שהיא בעצמותה לא הי' בא לידי השגה דבינה כו', ורק ע\"י מיעוט האור במדרי' התחתונות דחכ' בחי' נה\"י דאבא יכול להיות אצי' הבינה מהחכ' כו', ועי\"ז הוא בחי' מיעוט האור בבינה כו'. וכן בכדי להיות אצי' בחי' ז\"א מהמוחין זהו ג\"כ דוקא ע\"י מיעוט האור שמהמדרי' התחתונו' דחו\"ב יהי' אצי' הז\"א כו'. וכמו\"כ בכדי שיהי' התהוות בי\"ע מאצי' זהו ע\"י שבאצי' גופא מתמעט האור ממדרי' למדרי', דבאם הי' האור בשוה בכל המדרי' דאצי' שגם בחי' המל' שהיא סודכ\"ד דאצי' יהי' בה ריבוי\nאור לא הי' אפשר להיות התהוות בי\"ע, כ\"א דוקא ע\"י מיעוט האור יכול להיות ההתהוות כו', והגם שההתהוות היא בדרך אין ערוך, מ\"מ צ\"ל שהאין יהי' בערך להיות ממנו התהוות היש כו' וכמ\"ש במ\"א, וזהו ע\"י שבמדרי' דאצי' מתמעט האור ממדרי' למדרי' עד בחי' המל' אז אפ\"ל מבחי' המל' התהוות היש דבי\"ע כו'. וכ\"ז הוא לענין ההשתל' וההתהוות שהמעלה ומטה הוא בבחי' ריבוי ומיעוט האור כו', אבל בעצם הענין דמעלה ומטה בעולמות וספי' אין זה בחי' המעלה רק מה שהמדרי' העליונה היא בבחי' ריבוי האור לגבי"],[3601330215,"המדרי' התחתונה, רק המעלה ומטה הוא בעצם מדריגתן שהעליון הוא למעלה במדריגתו בעצם מהתחתון, והוא ג\"כ בבחי' ריבוי אור באותה מעלה ומדרי' שהוא כו' (וסיבת הריבוי והמיעוט בהאור הוא ג\"כ מצד המעומ\"ט בעצם מדריגתן, דהספי' שהיא מעלה בעצם מדריגתה מאיר בה ריבוי האור (והאור הוא ג\"כ עליון במדריגה), וזו שהיא בבחי' מטה היא בבחי' מיעוט האור כו' (והיינו דלא רק הצמצום בסדר ההשתל' הוא סיבת המיעוט וההעלם, וכנ\"ל שצ\"ל מיעוט בסוף המדרי' העליונה בכדי שיהי' נאצל המדרי' התחתונה, והיינו מה שהריחוק הוא סיבת המיעוט, כ\"א שהמדרי' התחתונה מפני שהיא בעצם תחתון במדרי' זהו סיבת מיעוט והעלם האור כו'), ולפ\"ז הוא שהמדרי' שהיא עליונה בעצם (מצד שרשה ומקורה) נאצלה בבחי' קירוב היינו בבחי' עליונו של הקו, והיא בבחי' ריבוי האור והגילוי, והמדרי' שהיא תחתונה בעצם נאצלה בבחי' ריחוק ובבחי' מיעוט והעלם כו' ועמ\"ש לקמן פמ\"ד). וכמו בעולמות בכלל שהעולמות שלפני האצי' הן למע' מאצי', ה\"ז שהן למע' בעצם מדריגתן, והוא שלמע' מאצי' מאיר עצמות הקו\nובאצי' אינו רק הארת הקו לבד, שזהו עילוי גדול מאד בעצם מהות האור שלמע' מאצי' הוא מהות ועצמות האור ובאצי' הוא בחי' גילוי המציאות לבד שז\"ע הארה כו', וכמ\"ש במ\"א דהארה לגבי עצם ה\"ז כמו מציאות לגבי מהות, וגם האור שהוא בבחי' גילוי העצם (דהיינו האור שהוא בבחי' א\"ס כו') ה\"ה רק בבחי' מציאות לבד כו', והיינו שהאור מגלה רק מציאות המאור לא עצם מהותו כו' וכמ\"ש במ\"א, וא\"כ האצי' שהוא רק הארת הקו ה\"ז רק בחי' מציאות לבד לגבי עצמות האור שלמע' מאצי' כו' (רק שבאצי' מאיר מהות הזיו והיינו שבספי' דאצי' מושג מהות הזיו וכמ\"ש במ\"א בענין השגת הנשמות בג\"ע כו'), ולכן המדרי' שלמע' מאצי' הן בבחי' העלם לגמרי והתחלת הגילוי הוא מאצי' כו', להיות כי הגילוי בעולמות הוא רק בחי' המציאות דאוא\"ס ב\"ה, דעצמות אוא\"ס הרי לית מח' תב\"כ כו', וע\"כ אצי' הוא התחלת הגילוי, אבל מה שלמע' מאצי' שזהו בחי' העצמות ה\"ז בבחי' העלם כו'. וכן בהמדרי' שלמע' מאצי' גופא דבחי' א\"ק מובדל בערך מהמדרי' שלמט' ממנו, שהרי נק' אדם קדמון, דפי' א\"ק הוא שזהו בחי'\nאדם שעלה במח' באוא\"ס קדמון לכל הקדומים דבצלם אלקים עשה את האדם, וכשם שהוא קדום כך גם מחשבתו קדומה כו' וכמ\"ש במ\"א. ועמ\"ש בדרוש ג' מיני אדם דא\"ק הוא כמו אדה\"ר שהי' יציר כפיו של הקב\"ה, וכמו\"כ בא\"ק הכלים הן מאוא\"ס ב\"ה שלא ע\"י אמצעות איזה מדרי' כו'. וא\"כ מובן דגם האור דא\"ק הוא למע' הרבה בעצם מדריגתו לגבי האורות שלמטה ממנו כו'. וי\"ל שזהו ג\"כ עצמות והארה, שהרי כל הגילוים שמא\"ק נק' הבלים דא\"ק, גם ההמשכה מבחי' אח\"פ נק' הבל שזהו בחי' הארה לבד כו'. והנה כשם שהעולמות מחולקים בעצם מהותם בבחי' האור והגילוי שבהם כנ\"ל, כמו\"כ הוא בהספירות בפרט שמחולקים ג\"כ בעצם מהותם כו'. וכמו בבחי' חכ' ובינה הנה החכ' בעצם היא למע' מהשגה, הגם שבכ\"מ בחי' החכ' היא בבחי' ידיעא לא למע' מהטעם והדעת לגמרי, כמו בחי' הכתר בעצם שלמע' מטו\"ד לגמרי, וכמו ענין הרצון שזהו רק הטי' והמשכת הנפש לאיזה דבר בלי שום ידיעה כלל באיזה טעם כו', וכנודע דאמיתת הרצון הוא שאין לו שום סיבה כלל רק שרוצה מצד העצם לבד כו' (ויש רצון שיש בו תענוג שהוא\nסיבת הרצון ויש ברצון שאין בו תענוג ג\"כ כו' וכמ\"ש במ\"א), והיינו שאין לו שום טעם כלל דאין טעם לעצם הרצון גם לא"],[3601330216,"טעם כמוס כו' וכמשי\"ת בעזה\"י (ומזה הוא ג\"כ כח האמונה שיש בכאו\"א מישראל שזהו בשרשו מבחי' הכתר שלמע' מטו\"ד כו', רק שבאמונה היא בבחי' קטנות כו', והתגלות הרצון הוא ברעו\"ד, והעיקר הוא במס\"נ בפו\"מ על קדה\"ש שזהו מצד התקשרות עצמות הנפש בעצמות א\"ס ב\"ה שלמע' מטו\"ד, ואין בזה שום ידיעה והתבוננות כו' וכמ\"ש במ\"א). אבל החכ' ה\"ה בחי' ידיעה (ולכן החכ' היא בבחי' או\"פ כו'), רק שהיא למע' מטעם ודעת המושג כו', והיינו שבחכ' מאיר אוא\"ס כמו שהוא למע' מהשגה עדיין והוא מה שלית מח' תפיסא בי' ה\"ז מאיר בבחי' החכ' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם ענין ריבוי האור ומיעוט האור הוא רק לצורך השתל' הספי' זמ\"ז, דמשו\"ז צ\"ל המיעוט גם בסוף המדרי' העליונה בכדי שיהי' ממנה אצילות המדרי' התחתונה, דכן הוא בחכ' ובינה, ובינה וז\"א, וז\"א ומל', אך עצם ענין מעומ\"ט הוא שמחולקים בעצם מדריגתן (וזהו סיבת הריבוי והמיעוט דהאור), וכמו דא\"ק הוא מעלה להיותו בחי' עצמות האור, והכל הוא בחי' הבלים דא\"ק, ולמעלה מאצי' עצמות הקו ובאצי' הארת הקו שזהו רק מציאות, וכן בחכ' ובינה, חכ' בעצם למעלה מהשגה, עם היותה ידיעה (לא כמו הכתר שלמע' מבחי' ידיעה), מאיר בה האוא\"ס כמו שהוא למעלה מהשגה.</span>\n<b>טל)</b> והענין הוא דהנה עיקר ההפרש בין חכ' ובינה הוא דחכ' תופס בעצם הדבר ובינה תופס רק במציאות הדבר כו', דבינה היא בחי' השגה וכל השגה היא בציור הדבר לא בהעצם והיינו רק במציאות הדבר לבד איך ומה הוא כו', וזהו שההשגה תופסת בהו\"ק של הדבר המושג, דכל דבר שהוא פשוט שאין בו קצוות (היינו שהוא בבחי' העדר המציאות) אינו נתפס בהשגה, כי ההשגה תופסת רק בהקצוות של הענין המושג שזה\"ע ציור הדבר שהוא רק מציאות הדבר לא עצם מהותו כו', והחכ' תופס בעצם ומהות הדבר כו'. וז\"ע מה שמוחין דאבא הן למע' מהשתל', דענין השתל' עו\"ע שייך רק בבחי' מציאות לבד, משא\"כ בדבר עצמי אינו שייך ענין עו\"ע כו'. דענין עו\"ע הוא בב' אופנים או שהעלול הוא מהות אחר מהעילה רק שנמצא כלול בהעילה ונולד ע\"י כו', או שהעלול הוא הארה מן העילה ומסתעף ממנו כמו ענף המסתעף מן האילן כו'. וכמו עד\"מ במדות הנולדים מן השכל שהמדות נמצאים כלולים בשכל קודם שנולדו בלב כו', וכמ\"ש במ\"א בביאו' מאה\"ז במדבר דק\"ך ע\"א בענין וצפונך תמלא בטנם שזהו עיבור דזו\"נ\nבבטן דאי' כו', והוא כענין התפעלות אהוי\"ר שקודם שבאו בגילוי בלב היו תחלה כלולים בההתבוננות שהיו במציאותם ממש כמו שהן אח\"כ בלב, וכנראה בחוש שיש התפעלות אהוי\"ר במוח כו', ובודאי הן בבחי' דקות יותר מכמו שהן בלב רק שהן עכ\"פ בבחי' מציאות מדות כו'. וכמשנת\"ל פל\"ג ההפרש בין התפעלות המדות להתפעלות השכל דהתפעלות המדות הוא בהרגש עצמי שמתפעל מה שלו טוב הדבר, והתפעלות השכל הוא שמתפעל רק על הטוב דהדבר עצמו כו', ומ\"מ ענין ההתפעלות הו\"ע המדות, כי מוחין בעצם אינם בבחי' התפעלות רק השגת הדבר לבד, ומה שמתפעל על הדבר אפי' על הטוב דעצם הדבר זהו בחי' מדות כו', והן בחי' מדות שבמוחין לפי שההתפעלות היא מ\"מ על עצם הדבר לא מה שלו טוב"],[3601330217,"הדבר. וכבר נת\"ל פרק הנ\"ל דעיקר ענין המדות הוא הרגש עצמי והיינו מה שלו טוב, וכאן שההתפעלות היא רק על טוב הדבר בעצם אין זה מדות ממש, וגם ההתפעלות היא בהעלם מצד שמאיר עדיין ההשגה שמשיג בעצם הענין (עם היות שאינו כמו שהוא בעת ההשגה ממש כו'). וע\"כ זהו רק מדות שבמוחין כו', ומ\"מ ה\"ז מקור למדות שבלב, כי ההתפעלות מה שמתפעל במוחו ה\"ז במורגש עכ\"פ רק שהוא בדקות וממנו בא בחי' המורגש שבלב בהתפעלות מורגשת דמדות כו'. וגם ענין ההרגש בהטוב שבהענין ה\"ז מקור שממנו בא ההרגש איך שהדבר טוב לו כו', כי במוחין בעצם בעת שהוא טרוד ומתעסק בהשגת הענין אינו שייך אל ההרגש דהטוב והעילוי של הענין, וכאשר נכנס ומתקשר בעומק הענין ביותר (ובפרט כאשר ההשגה היא בעצם הענין האלקי כו') בא ממילא בחי' היוקר והעילוי דאלקות, וכמו לאסתכלא ביקרא דמלכא כו', אמנם אין זה במורגש ולא דבר בפ\"ע מן ההשגה, רק שבהשגת הענין ודוקא כשנכנס בעומק הענין ביותר, מאיר במוחו היוקר והעילוי דאלקות שנפשו מתדבקת בזה בבחי' דביקות עצמי, והו\"ע אהבה בתענוגים\nלהתענג על ה' כו'. אבל הרגש הטוב דהענין האלקי ה\"ז דבר בפ\"ע מן ההשגה (רק שמאיר בזה עדיין ההשגה, אבל הוא מרחוק כו') ובא במורגש במוחו כו', ולכן ה\"ז בא בבחי' התפעלות במוחו עכ\"פ מה שמתפעל על טוב הדבר כו' (דבאהב\"ת הנ\"ל אין זה בבחי' התפעלות כלל כ\"א בבחי' דביקות כידוע), והרגש הטוב זהו מקור לההרגש דקרבת אלקים לי טוב כו', והיינו שמהרגש טוב הדבר בא ההרגש איך שהדבר לו טוב (כי בד\"כ הוא בא לענין המורגש כו'), ומההתפעלות שכלי בא ההתפעלות מורגשת כו'. וענין דעו\"ע בזה הוא שבהתבוננות והשגת השכל נמצאים מדות והו\"ע מורגש הנ\"ל, והיינו הרגש טוב הדבר וההתפעלות שמתפעל ע\"ז, שאין זה מהות המוחין בעצם כ\"א מהות המדות כנ\"ל. והוא התכללות העלול בתוך העילה שהוא בדקות עדיין ואח\"כ נולד העלול בהתגלות במציאות מורגשת כו'. דשכל ומדות הן מהותים נבדלים בעצם רק ששניהם מהותים רוחניים וכלולים זב\"ז ונולדים ומשתלשלים זמ\"ז כו'. ומאחר שהעלול הוא מהות אחר מהעילה ממילא מה שהעילה כוללת את העלול ה\"ז רק בבחי' החיצוניות וההתפשטות שלו לבד כו'\n(וכ\"ה גם בחו\"ב דבינה היא מהות נבדל מן החכ' ומשתלשל מהתפשטות החכ' וכמא' האדר\"ז האי חכמה אתפשט ואפיק מיני' בינה כו' וכמ\"ש במ\"א). ובמ\"א מבואר דהמדות שבמוחין הן כמהות מוחין עדיין, והיינו דההתפעלות שכלי להיות שזהו ההתפעלות על הטוב דהדבר עצמו ה\"ז בכלל מוחין עדיין כו', והולדת המדות שבלב הוא שנמשך הארה מהמוחין להיות הולדת המדות כו', ובאופן הזה י\"ל שהעלול הוא הארת העילה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה חכ' תופס עצם הדבר ובינה תופסת המציאות, ולכן מוחין דאבא למע' מהשתל' כי עו\"ע שייך רק בבחי' המציאות (דהיינו בהארה) לא בעצמי, ויבאר ב' אופנים בעו\"ע הא' שהעלול הוא מהות אחר ונמצא כלול בהעילה, וכמו הרגש טוב הדבר במוחו, הו\"ע מדות שבשכל (דבמוחין ה\"ז בא בדרך ממילא לא במורגש, ובבחי' דביקות), וזה מקור לההרגש דלו טוב שבלב, ובא מחיצוניות השכל.</span>"],[3601330218,"<b>מ\"ם)</b> והאופן הב' בעו\"ע הוא בענין עו\"ע במוחין גופא, וכמו בהשפעת השכל מן המשפיע אל המקבל, הרי השכל הנשפע אל המקבל אינו מהות אחר מהשכל של המשפיע, רק שהוא הארה לבד משכל המשפיע ונמשך משכל המשפיע לא מגוף ועצמות המוחין שלו כ\"א מבחי' חיצוני' שהוא ג\"כ הארה כו', דכל הארה שבאה בבחי' עו\"ע בהכרח שגם העילה היא בחי' הארה לבד (דאור לגבי מאור אינו בבחי' עו\"ע אלא או בבחי' גילוי מן העצם, דעם היות שהגילוי הוא לפי אופן העצם מ\"מ ה\"ה באין ערוך לגבי העצם כו' וכמ\"ש במ\"א, או שבא ע\"י הצמצום ובחי' סילוק האור העצמי דממילא ה\"ה באין ערוך כו'. אבל הארה שבאה בבחי' עו\"ע דהיינו בבחי' ערך וע\"י התלבשות העילה להמציא את העלול בהכרח שהעילה היא ג\"כ הארה לבד כו'). וזהו דהתהוות העלול הוא ע\"י שיש קצת השגה מהעילה בהעלול, וכמו במדות ומוחין הוא ע\"י שנמשך הארת המוחין בלב וכמא' בינה ליבא ובה הלב מבין להיות מזה התעוררות המדות כו', והו\"ע התלבשות העילה בהעלול והיינו שאור המוחין בא בבחי' התלבשות להיות מושג ומורגש בלב כו', ועי\"ז\nהתהוות העלול הוא בערך העילה כו'. וכן במשפיע ומקבל הרי שכל המקבל משיג את שכל המשפיע ונעשה כערך שכל המשפיע כו', וקירוב העלול אל העילה הוא מה שמשיג יותר את העילה, וכמו כשמעיין ומייגע א\"ע בהשכל הנשפע ובא אל עומקו ופנימיותו יותר שזהו הקירוב והעלי' של העלול, להיות שעי\"ז הוא יוצא מחומריות השגתו בהענין ובא אל הדקות והרוחניות יותר כו' (ובד\"כ מזדכך שכלו בזה כו'). וכן במדות שמאיר בהם אור המוחין יותר שנעשים המדות בבחי' דקות בלתי מורגשים כ\"כ כו', וכ\"ז שייך בבחי' הארה לבד דהרי העצם הוא למע' מהשגה כו'. והדוגמא מזה יובן למע' דהשתל' עו\"ע שייך רק באוא\"ס שנודע מציאותו ולא מהותו, דבבחי' המציאות דאוא\"ס ב\"ה שייך השגה ושם שייך ענין ההשתל' שהעלול משיג את העילה ונמצא בערך העילה כו', אבל בעצמות שאינו מושג אינו שייך ענין עו\"ע כו'. וזהו דמוחין דאבא למע' מהשתל', והענין דהנה ידוע דחו\"ב הן ראי' ושמיעה דאינו דומה שמיעה לראי', וההפרש ביניהם ידוע דשמיעה הוא מרחוק והיינו רק השגת מציאות הדבר, וראי' מקרוב שהוא ראיית עצם\nהדבר, שז\"ע החכ' שהוא התאמתות הדבר לא מצד ההשגה כ\"א מה שבעין השכל רואה אמיתות הדבר כמו שהוא כו' וכמ\"ש במ\"א דראי' דחכ' הוא הראי' בעצם המהות שלמע' מהשגה, וזהו בחי' עצמות החכ' כו' (ובחכ' יש ג\"כ ע\"ס ובחי' ג\"ר דחכ' הוא הראי' בעצם הדבר שאינו שייך עדיין למדות כו', אך גם המדות שבחכ' הן ג\"כ בבחי' התאמתות שלמע' מהשגה וכמ\"ש במ\"א בענין שתיק רב דמ\"מ לא הדר בי', והוא שהתאמת אצלו שהוא אסור רק שלא הי' לו טעם מושג ע\"ז, והיינו בחי' המדות שבחכ' שהן בבחי' התאמתות למעלה מהשגה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מה שפ' נדרים נאמרה לראשי המטות ונא' בה זה הדבר כו', דהנה ידוע דנדרים הם בבינה וכמא' כל הנודר כאלו נודר בחיי המלך, מלך בחי' ז\"א וחיי המלך בחי' בינה, וחכם המתיר את הנדר זהו מבחי' חכ' כו'. והענין הוא דהנה כל הדברים הגשמיים הם תחת ממשלת ק\"נ, שנוגה מעורב טו\"ר ומצד הטוב שבה נכללת לפעמים בקדושה ומצד הרע שבה נכללת לפעמים בגקה\"ט כו', וע\"כ נק' להט החרב המתהפכת כו' כנודע. וכן כל הדברים הגשמיים מעורבים טו\"ר וכמו"],[3601330219,"המאכל הגשמי כשאוכלו לש\"ש מתברר הניצוץ הטוב שבו ומוסיף לו חיות בעסק התו' ועבודה וכמו חמרא וריחא פקחין, ועד דלא אכילנא בישרא דתורא לא צלינא דעתאי כו', ולהיפך כשאוכלו למלאות תאוות נפשו ה\"ה מעבה ומגשם אותו וכמא' מלי' כריסי' זינא בישא כו'. ובזה הוא העבודה לדחות את הרע דנוגה ע\"י שיפעול בנפשו שלא ירצה להתענג בתענוגי בנ\"א כו', וע\"י הכוונה לש\"ש מברר את הניצוץ הטוב כו'. והעבודה היא תחלה בתפלה שהו\"ע ההתבוננות באלקות שעי\"ז בא לבחי' אהבה וקירוב לאלקות שתכלית חפצו ורצונו הוא באלקות ולא ירצה בגשמיות וחומריות העולם כו', וגם בעניני העולם שהוא מוכרח בהם יהיה רק מצד ההכרח ובכוונה לש\"ש כו', ועי\"ז נעשה דחיית הרע דנוגה והעלאת הניצוץ הטוב שנכלל בקדושה כו'. אמנם יש אופן שגם הרע דנוגה נכלל בקדושה וכמו בשבת שארז\"ל מצוה לענגו באכו\"ש, והוא שגם התענוג הגשמי הוא במדרי' הקדושה בשבת שאינו תענוג גשמי כ\"א כמו תענוג אלקי כו', והו\"ע האתהפכא שהרע נהפך לטוב ונעשה תענוג אלקי כו'. דהנה אופן הבירור הנ\"ל שצריכים לדחות הוא כשהרע\nישנו במציאות והיינו כשהתענוג הגשמי הוא בתאוה גשמי' ה\"ז מגשם כו' כנ\"ל וצריכים לדחותו והיינו שלא יתענג בזה כו', וזהו בבחי' אתכפיא שכופה ומכניע את הרע כו'. אבל בבחי' אתהפכא שהרע נהפך לטוב היינו שבהתענוג אין בו שום תאוה גשמיות כלל אדרבה הוא תענוג אלקי הרי הרע נהפך לקדושה כו'. וזהו ההפרש בין עבודה דחול לעבודה דשבת, דהנה ידוע דששת ימי החול הן בחי' יומין דז\"א וכנודע בענין ששת ימים עשה ה' כו', והמוחין דחול הן מוחין דאימא שכ\"ז הוא במדרי' דהשתל' שזהו בחי' המציאות דאלקות כו', וע\"כ העבודה בזה הוא בבחי' אתכפיא לבד כו'. אבל שבת הוא בחי' מוחין דאבא שלמע' מהשתל' והוא בחי' המהות דאלקות, דהעבודה במדרי' זו הוא בבחי' אתהפכא, והיינו שהכל הוא אלקות גם הענינים הגשמיים שהתענוג הוא אלקי וכמו צדיק אוכל לשובע נפשו כו'. ובד\"כ זהו ג\"כ ההפרש בין הבירור דתפלה שמלמטלמ\"ע להבירור דתורה שהוא מלמעלמ\"ט כו' וכמ\"ש במ\"א. והנה ארז\"ל נדרים סיג לפרישות והיינו בהעבודה שבדרך אתכפיא לפעמים צ\"ל בדרך פרישות לגמרי והוא כשיודע בנפשו\nשא\"א לו לפעול בנפשו שיהנה מהדבר הגשמי רק בכוונה לש\"ש, וירא לנפשו שיהי' בתאוה גשמי' ועי\"ז יורד ח\"ו, ע\"כ פורש א\"ע לגמרי מזה. וז\"ע הנדרים שאוסר על עצמו הדבר המותר, ואמרז\"ל לא דייך במה שאסרה תורה כו', אך זהו מפני שא\"א להעלות הדבר ה\"ה אוסרו עליו במה שממשיך עליו אור מקיף דקדושה שנעשה כקרבן כו', אך זהו בדרך דחי' לבד, וכ\"ז הוא מבחי' הבינה שהעבודה היא בבחי' אתכפיא כו'. אבל מבחי' החכ' שעי\"ז גם הרע נהפך לטוב, ז\"ע חכם המתיר את הנדר שהכל נעשה טוב, וכמו האכילה דשבת שאינו מגשם כו'. וזהו שנאמר גבי נדרים זה הדבר, דהנה כל הנביאים נתנבאו בכה ומשה נתנבא בזה שהוא גילוי המהות וכנודע דמשה הוא בחי' החכ' כו', ולהיות דכל ענין התרת נדרים הוא דוקא מבחי' גילוי המהות דבחי' חכ' ע\"כ נא' כאן זה הדבר כו'. ונאמרה לראשי המטות דוקא, דהנה י\"ב שבטים הן ששה מדות דז\"א שהן בבחי' י\"ב גבולי אלכסוני' כו', וראשי המטות הן בחי' המוחין דז\"א שזהו מבחי' בינה כו', והמשיך להם משה מבחי' החכ' להיות בכוחם להתיר את הנדר כו', והיינו שבינה היא\nמ\"מ כלי לאור החכ' כו'. וזהו וידבר משה אל ראשי המטות דוקא, וידבר הוא ל' הנהגה והמשכה שהמשיך מבחי' החכ' אל ראשי המטות"],[3601330220,"בחי' מוחין דאימא להתיר את הנדר כו'. וזהו זה הדבר בחי' גילוי המהות דבחי' חכ' שעי\"ז דוקא בכוחם להתיר את הנדר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והאופן הב' הוא כמו השפעת השכל, שהוא הארה לבד, ובא מחיצוניות שהוא ג\"כ רק הארה ולכן התהוות העלול הוא ע\"י השגת העילה, ומתהווה כערכו ועילוי העלול הוא שמשיג יותר את העילה ונעשה בבחי' דקות יותר, וכ\"ז אינו שייך בעצמי, וזהו חכ' ובינה ראי' ושמיעה (וגם מדות שבחכ' הן בחי' התאמתות). ובזה יובן ענין הנדרים שהן מבינה, והיתר נדרים מחכ'. וית' מ\"ש וידבר משה אל ראשי המטות.</span>"],[3601330221,"<h3>בס\"ד. ש\"פ דברים, תער\"ב</h3>\n<b>ציון</b> במשפט תפדה ושביה בצדקה, וצ\"ל מהו אומרו ציון במשפט כו', הלא הכוונה היא על כללות ישראל לא על יושבי ציון דוקא וא\"כ מהו אומרו ציון דוקא. גם מהו\"ע ושביה בצדקה דמשמע שזהו ענין אחר ממה שאמר קודם וצ\"ל מהו. ולמה ציון במשפט תפדה ושביה בצדקה כו'. ולהבין זה ילה\"ק משנת\"ל דבע\"ס יש התחלקות מעלה ומטה, וענין מעומ\"ט הוא בבחי' ריבוי ומיעוט שבהמדרי' העליונה מאיר האור בגילוי יותר מבהמדרי' התחתונה כו'. ונת' דעיקר ענין מעלה ומטה הוא בעצם מהותם ומדריגתן שהמדרי' העליונה היא בבחי' מעלה בעצם מדריגתה לגבי המדרי' התחתונה, וכמו בחו\"ב שהחכ' בעצם מדריגתה למעלה מבחי' הבינה, דבינה תופסת רק בבחי' המציאות דאלקות וחכ' תופסת בבחי' המהות כו'.\nמא) <b>אמנם</b> עדיין צ\"ל והלא החכ' היא ג\"כ ידיעה שכליות ועכ\"פ במדרי' התחתונות שבחכ' כמו נקודת ההשכלה (דבד\"כ זהו בחי' יסוד אבא) ה\"ז ידיעה שכליות ונק' שכל גלוי, וכל ההשגה דבינה היא בנקודת ההשכלה דחכ', וא\"כ הרי גם נקודת ההשכלה היא בבחי' שכל והשגה (לא בבחי' השגה ממש אבל הוא שכלי ששייך לענין ההשגה לא הידיעה דראיה כו'). ועם היות דמדרי' העליונות שבחכ' הן למע' משכל והשגה כ\"א בבחי' ראי' והתאמתות כו', מ\"מ המדרי' התחתונות שבחכ' שנעשה מקור לבינה ה\"ז בבחי' שכל והשגה כו'. וא\"כ איך אנו אומרים שהחכ' בעצם מהותה ומדריגתה היא בבחי' מעלה, מאחר שגם החכ' היא בבחי' ידיעה שכליות, וכל שכל והשגה הוא רק בבחי' המציאות דאלקות, א\"כ הרי משתווה החכ' אל הבינה בעצם מהותה (ומתחלקת רק בבחי' ריבוי האור כו'). והנה עפ\"י פשוט י\"ל שזהו בחי' מיעוט האור בבחי' חכ' גופא, דהרי בכדי שיהי' התהוות הבינה מהחכ' צ\"ל מיעוט האור בחכ' וכמשנת\"ל פל\"ח, והיינו מה שהמדרי' התחתונות דחכ' הן בבחי' ידיעה שכליות שזהו בחי' מיעוט האור, דמדרי' העליונות הן למע' משכל והשגה ומדרי' התחתונות הן בבחי' שכל והשגה, וה\"ז מקור להשגה"],[3601330222,"דבינה כו'. אבל באמת א\"א לומר כן שהרי אין זה מיעוט לבד כ\"א שינוי בעצם המהות, דראי' והשגה ה\"ה מחולקים בעצם מהותם כו'. ואם נאמר דמדרי' התחתונות שבחכ' הן בבחי' שכל והשגה, ה\"ז שינוי המהות לגבי מדרי' העליונות שבחכ' שהן למע' מענין שכל והשגה כו'. וזה א\"א לומר שבמדרי' אחת יהי' שינוי המהות במדרי' הפרטים שבה, וענין המיעוט הוא רק מה שהאור מתמעט ואינו מאיר בגילוי אבל הוא באותו המהות כו'. וזה אפשר לומר שבמדרי' זו גופא האור מתמעט ממדרי' למדרי' בהמדרי' הפרטיות שבה, אבל לא שיהי' בבחי' שינוי המהות כו'. והיינו דלבד זאת דמשמעות הענין הוא דהחכ' בכללות מדריגתה גם במדרי' התחתונות שבה היא בבחי' מעלה בעצם מדריגתה לגבי הבינה, הנה ג\"ז א\"א לומר שיהי' שינוי המהות בבחי' החכ' גופא במדרי' הפרטים שבה כו'. אך הענין הוא דהנה ידוע דחו\"ב נק' אין ויש, החכ' נק' אין וכמ\"ש והחכ' מאין תמצא, והבינה נק' יש כמ\"ש להנחיל אוהבי יש כו', וא\"כ התהוות הבינה מהחכ' הוא בבחי' יש מאין, והיינו שהאין דחכ' הוא בבחי' העלם לגבי היש דבינה. דזהו\nההפרש בין אין ויש לעו\"ע, דעו\"ע הוא שהעלול משיג את עילתו ועי\"ז הוא מתהווה מן העילה, והיינו שע\"י ההשגה שמשיג את העילה ה\"ה נמצא במציאותו כו', ויש מאין הוא אדרבה שהאין מתעלם מן היש שאינו משיג אותו ועי\"ז הוא נמצא בבחי' מציאות יש כו', ועש\"ז נק' אין ע\"ש שאינו מושג כו'. וכמו\"כ הוא בבחי' חו\"ב שהאין דחכ' מתעלם מבחי' הבינה כו' (ועמ\"ש בסי' ד\"ה מזמור לתודה). ולכאורה א\"מ הרי נקודת ההשכלה דחכ' בא בבחי' השגה בבינה, וכל השגת הבינה היא בנקודת ההשכלה, ואיך נק' החכ' אין לגבי בינה כו'. ובהכרח לומר שגם נקודת ההשכלה היא בבחי' הבדלה מהבינה עד שנק' אין לגבי הבינה, והוא שבהשכלי דחכ' ג\"כ מאיר בזה בחי' העצם, והיינו דבנקודת ההשכלה דחכ' מאיר בזה דקות עצם הענין המושכל מה שא\"א לבא לידי השגה, וזה שבא לידי השגה הוא רק החיצוני' מזה היינו השכלי לבד לא הרגשת העצמי שבהנקודה כו'. דהנה ידוע ומבואר בכ\"מ דבנקודת ההשכלה מאיר האור בגילוי וכשבא בהשגה בריבוי פרטים מתעלם האור כו', והנה מה שמאיר בנקודת ההשכלה אין זה רק הריבוי דאור\nהשכל, דהיינו שהאור שכל הוא אותו המהות שבא בבינה, רק שבנקודת ההשכלה דחכ' הוא בריבוי וכאשר בא להשגה דבינה מתמעט כו', כ\"א מה שלבד זאת הנה בנקודת ההשכלה מאיר העצם של השכלי מה שא\"א באמת לבוא בהשגה וכאשר בא הענין לידי השגה מתעלם ואינו מאיר כלל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועדיין צ\"ל הלא נקודת ההשכלה היא שכלי, וא\"א לומר שזהו המיעוט בחכ' בשביל הבינה והלא הוא שינוי המהות, אך הענין דחכ' היא אין, ובינה מחכ' היא יש מאין שאינו מושג, והוא מפני שגם בנקודת ההשכלה מאיר עצם השכלי שלמע' מהשגה.</span>\nמב) <b>אמנם</b> נראה ונרגש הדבר שגם השכלי דחכ' בעצם אינו ענין השגה באמת, דבעיקרו הו\"ע הנחה בנפש (אלייג אין נפש וואס בא עם לייגט זעך דיא זאך אזוי), ועם היות שזהו לא בחי' ההנחה שמצד הראי' כ\"א מצד ההשכלה, הנה השכלי גופא הוא בדרך הנחה לא בדרך השגה כו', והשכלי שבזה והיינו מה ששייך להשגה הוא בחי' החיצוני' לבד, ועצם הענין הוא בדרך הנחה כו'. וזהו שאנו רואין"],[3601330223,"כאשר מייגע א\"ע באיזה ענין שאינו מובן לו, וכאשר בא אל עומק ופנימי' הענין ונופל לו בשכלו שהוא באופן כך וכך, הנה כאשר מאיר אצלו הנקודה שכליות בהענין מתיישב אצלו הענין בטוב (עס ווערט עם רעכט דער ענין און זייער גוט), וכאשר מתחיל להביא בהשגה פרטי הענין איך ומה הוא עדיין אין מתיישב אצלו הענין כלל. והסיבה הוא מפני שנתעלם אצלו ההנחה שהי' אצלו קודם, כי זה שבא מקודם אל עומק ופנימי' הענין הי' זה בדרך הנחה שכליות לא בבחי' שכלי לבד, והי' נרגש בזה עצמות המושכל ומצד עצם המושכל נתיישב אצלו הענין, ואח\"כ כשמתחיל להשיג הענין מתעלם העצמות ומאיר רק החיצוני' דהיינו השכלי לבד, ובהשכלי אין הענין מתיישב עדיין, והעצה הוא שיקשר עצמו עוד הפעם (ער זאל זעך צו טראגין) אל עומק ופנימי' הענין כמו שהי' אצלו בההנחה שכליות, והוא שירגיש יותר ההנחה שכליות (דעם לייג פון דעם ענין), וזה נותן כח בהשכלי ביותר ובא לידי השגה דבינה להשיג כל מה שבאפשר להשיג בהענין כו'. וכנודע בענין ראי' דחכ' שמאיר בזה עצם הענין שלמע' מהשגה לגמרי, ומ\"מ\nה\"ז מוסיף כח בהשכלה ג\"כ שיהי' ריבוי נביעות ההשכלה ביותר כו'. וכמ\"ש בפע\"ח בהאריז\"ל שבשינת צהרים דש\"ק ראה בפ' בלק ובלעם מה שהי' צריך לדבר בזה פ' שנה, ובאמת גם בזמן פ' שנה לא הי' מגלה מה שראה בזה, כי הראי' הוא בעצם המהות שא\"א לבוא לידי השגה כלל, רק שע\"י ראיית המהות גם ההשכלה היא בריבוי ובעומק ביותר כו' (ועמשית\"ל פ'). וכמו\"כ ההנחה שכליות הוא בעצם למע' מהשגה כי ההנחה שכליות היא כמו הראי' דחכ' רק שהיא במדרי' תחתונה ממנה, דראי' היא למע' משכלי לגמרי (הגם שזהו מה שבעין השכל דבלבך כו', ולעתיד יהי' בבחי' ראי' ממש כמו ראיית העין וכמ\"ש כי עין בעין כו' וכמ\"ש במ\"א), וההנחה שכליות ה\"ה בשכל רק שהעיקר בזה הוא ההנחה כו', וה\"ז מוסיף כח גם בהשכלי שזהו מה שמושג בבינה כו'. וכמו שיש כמה ענינים שכליים עמוקים ונפלאים שהן למע' מהשגה ומ\"מ יש להם מקום בשכל גבי חכמים, ואין זה בבחי' ראי' דחכ' כי אינם במדרי' זו דבחי' ראי', וגם דזה שיש להם מקום הוא בשכל לא רק בדרך התאמתות דראי' כו', כ\"א זהו מצד ההנחה שכליות דחכ', דעם\nהיות שזהו שכלי עיקרו הוא בבחי' הנחה לא בבחי' השגה ולכן יש שם מקום גם להענינים שלמע' מהשגה כו', ועי\"ז ביכולתם להביא הענינים גם לידי השגה כו'. וזהו שהחכ' הוא בחי' ד\"ע והיינו שבחכ' מאיר האוא\"ס יש האמיתי דהיינו בחי' העצמות שזהו בחי' יש האמיתי כו', ומה שלמטה (היינו מה שבא בהשגה) שזהו בחי' הארה לבד ה\"ז בבחי' אין דכלא חשיב קמי' כו' (ולא כמ\"ש במ\"א דבחי' ד\"ע דחכ' הוא רק מה שבחכ' מושג הדיעה העליונה איך שא\"ס יש האמיתי וכולא קמי' כל\"ח, והיינו שהחכ' הוא ההארה, ולהיותה הארה הדבוקה במקורה מושג ומורגש שם איך שהא\"ס הוא היש האמיתי וכולא קמי' כל\"ח, ועי\"ז החכ' עצמה היא בבחי' הביטול דכל\"ח שהוא הביטול דיחו\"ע כו'. ולפי המבואר כאן הוא דבחכ' מאיר אוא\"ס בחי' יש האמיתי והיינו בחי' העצמות שלמע' מהשגה כו', וכל ענין השכל וההשגה הוא בבחי' אין דכלא חשיב כו'). ובבוא השפעת החכ' בבינה נק' השפעת החכ' אין והיינו בחי' ההנחה שכליות כו', דמה שמושג בבינה הוא רק החיצוניות דהיינו השכלי שבנקודת ההשכלה, אבל ההנחה שזהו בחי' העצמות שבנקודת ההשכלה ה\"ז בבחי' אין לגבי הבינה היינו בבחי' העלם שאינו מושג בבינה. ומ\"מ זהו עיקר"],[3601330224,"המקור והסיבה לההשגה דבינה, וכנ\"ל דההנחה שכליות נותנת כח בהשגה כו' (דבאמת בכל השכלה חדשה כמו שהיא בנקודת ההשכלה עיקרה בחי' ההנחה והיא דוקא סיבת השכלי וההשגה כו', רק שניכר הדבר ביותר באיזה עומק ופנימיות דשכל כו' כנ\"ל). וזהו שהחכ' נק' קדש וכמ\"ש ושמרתם את השבת כי קדש היא, וידוע דשבת הוא גילוי מוחין דאבא כו', ואי' בזהר קדש הוא מלה בגרמי', דפי' קדש הוא היותו מובדל, וכמו שענין ההבדלה הוא שאינו מתערב עם דוגמתו היינו גם עם דבר שנראה שהיא כיוצא בו ובדומה אליו כו', דהבדלה מדבר שאינו בערכו אין זה הבדלה, וכמו שאינו שייך לומר שהאדם מובדל מהבע\"ח שאינו מערכו כלל כ\"א כאשר מובדל מדבר שבערך אליו, וכמו כשאומרים על החכם שהוא חכם גדול בהפלאה והבדלה היינו שהוא מובדל גם מהחכמים, דלגבי אנשים פשוטים אינו שייך לומר שהוא מובדל שהרי אינם מערכו וממהותו כלל במהות השכל כו', כ\"א לגבי חכמים שהן מ\"מ בערכו שייך לומר שהוא מובדל כו', דדוקא על דבר שיש איזה דמיון נופל ל' הבדלה שעם היותו דומה אליו מ\"מ אינו מתערב עמו כו'. וכן\nבחי' הבדלה דחכ' הוא שהיא מובדלת מלהיות מושג בשכל כו', ואין זה בבחי' ראי' דחכ' שאין זה בבחי' שכלי ואינו בערך השגה כו', כ\"א בבחי' השכלי דחכ' דעם היותו דומה להשגה דבינה ה\"ז בבחי' הבדלה באמת מהשגה דבינה מפני שעצם ענין השכלי דחכ' מצ\"ע הוא למע' מהשגה באמת כ\"א בבחי' הנחה כו', ומה שהוא מ\"מ שכל ובא בהשגה זהו אינו בחי' העצם שלה כלל כ\"א בחי' חיצוניות שבא ע\"י צמצום כו' כנ\"ל. וגם מה שהחכ' היא בבחי' הבדלה הוא כי ענין ההשגה הוא התערבות הדבר שמתייחד עם הדבר המושג כמו שהוא לאחדים, והוא מפני שבהשגה הרי בא הדבר בבחי' התלבשות ותפיסה ממש בכלים בבחי' אור פנימי ה\"ז בבחי' התאחדות ממש, אבל מה שמובדל מגדר השגה ה\"ז בבחי' הבדלה כו', והוא בבחי' ההארה שאינו נתפס ואינו מושג כלל רק מאיר למע' משכלו ובינתו כו'. וז\"ע שמן שצף ע\"ג יין בפ\"ב דטבו\"י מ\"ה, דרבנן ס\"ל שאינו חיבור כי יין הוא בינה שהיא מקור להשתל' משא\"כ שמן שהוא בחי' חכ' (והיא בחי' עליונה שבחכ' שלמע' ממה שהחכ' נק' מים שזהו בחי' חיצוני' החכ' וכמו השכלי שבחכ' ובחי'\nהחיצוני' שבה כנ\"ל, ושמן י\"ל שזהו בחי' אור שלמע' ממים כו'), שאינו מתערב עם הבינה כו'. והרמ\"ז פ' אמור דצ\"ד ע\"ב כתב בשם לקו\"ת מהאריז\"ל שיש בדיקנא ב' בחי' הא' בחי' השערות ושם מציאות אימא, והב' אור הפנימי שיש בתוכם (והוא בחי' שמן הטוב כו') והוא מציאות אבא כו' (ועמשית\"ל פ'). ונמצא מכ\"ז מובן מה שהחכ' היא בבחי' מעלה לגבי הבינה אין זה רק בבחי' ריבוי האור כ\"א שהיא בבחי' מעלה בעצם מדריגתה לגבי הבינה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם באמת גם השכלי דחכ' הוא הנחה שכליות שהוא תפיסת העצם שלמעלה מהשגה (למטה ממדרי' הראי') והשכלי הוא חיצוני, ולכן מה שמתיישב בנקודת ההשכלה יכול להיות שלא יתיישב עדיין בהשגה, וכמה ענינים נפלאים שלמע' מהשגה יש להם מקום בשכל החכמים, וההנחה מוסיף כח בהשכלי, ומה שמושג בבינה הוא השכלי, וההנחה זהו בחי' האין שאינו מושג רק שמוסיף כח, וזהו שהחכ' היא ד\"ע שמאיר בה יש האמיתי בחי' העצמי, ומה שבא ממנה בהשגה היא הארה דכל\"ח, ולכן נק' קדש שגם מדרי' תחתונה שבחכ' בעצם למע' מהשגה,</span>"],[3601330225,"<b>ואינו</b> מתערב במדרי' שלמטה וכמו שמן שצף ע\"ג יין (ובמ\"א שהשמן מפעפע בכל דבר ואינו מתערב והו\"ע אין קדוש כה' כו').\nמג) <b>וזהו</b> מ\"ש בע\"ח דאוא\"ס מאיר בחכ' בקירוב מקום ובבינה בריחוק מקום, דענין הקירוב והריחוק אינו כמו שאנו מדמים קירוב וריחוק גשמי, אלא ענין הקירוב הוא כמו עד\"מ חכם גדול כשמדבר עם איש בינוני דברים רבים זה יקרא בשם קירוב שאדם גדול הנ\"ל קירבו שדיבר עמו הרבה, וביותר הוא הקירוב כשמראה לו פנים בדיבורו ומדבר עמו בסבר פנים יפות כו'. ועוד זאת ענין הקירוב הוא כמו שני בנ\"א שקרובין בדעתם זל\"ז היינו שהן סמוכים זל\"ז באומד דעתם, כמו שהקירוב הגשמי עד\"מ ב' בנ\"א קרובים זל\"ז שהוא שאביהם הם שני אחים שנולדו מאו\"א א' הרי בניהם הם קרובים זל\"ז, אך זהו בגשמיות, וכן יובן ששני בנ\"א שדעותיהם שוות בענין א' ה\"ה קרובים וסמוכים זל\"ז במוח שכלם כו'. והדוגמא מזה יובן בבחי' החכ' שהאוא\"ס מאיר שם בקירוב מקום היינו בבחי' ריבוי האור, וכמו שבנקודת ההשכלה דחכ' הרי מאיר שם הענין בגילוי הרבה יותר מכמו בפרטי הענינים דהשגה כנ\"ל, וכמו\"כ בחכ' מאיר האור בגילוי בריבוי יותר מבבינה, וזהו כמו הקירוב שמדבר עמו הרבה כו', ועיקר\nהקירוב הוא שמדבר עמו בסבר פנים שהו\"ע גילוי הפנימיות שמאיר בחכ' מה שלמע' מהשגה, וכנ\"ל דגם בבחי' השכלי דחכ' לבד ריבוי האור (שבהשגה מתעלם האור כו') הנה מאיר בזה העצם מה שא\"א לבוא בהשגה כלל כו' (ועמ\"ש במ\"א בענין ראיית פני המשפיע שבזה מקבל מעצם חכמתו של הרב שאינו בא באור השפע שמשפיע לו כו', וזהו שאמר רבי הא דמחדדנא טפי מחבראי מפני שראיתי לר\"מ כו'. ולכן אמרו בירושלמי כל האומר שמועה מחבירו יהא רואה בעל השמועה כאלו עומד לפניו כו', שעי\"ז מקבל מבחי' עצמות החכ' של המשפיע כו' וכמ\"ש במ\"א. וכמו\"כ י\"ל בחכ' דענין מראה פנים היינו גילוי הפנימיות והעצמיות כו'. ועמ\"ש ע\"פ יאר ה' פניו אליך דאי' במד\"ר ע\"ז כמד\"א באורך נראה אור דפי' באורך הוא אור העצמי כו', דמ\"ש תחלה כי עמך מקור חיים היא בחי' ההארה שנמשכה לצורך העולמות שבאה בבחי' השתל' כו', שעז\"א כי עמך ולא אתה כו', והלא ממך הכל כתיב ומה\"ע עמך כו', אך זהו להורות שהוא טפל ובטל לך לפי שהוא רק הארה לבד כו'. אבל באורך נראה אור הוא בחי' אור עצמי כו' ועז\"א יאר ה'\nפניו אליך כו', דענין הארת פנים הוא שנמשך בחי' העצמית כו', ונמשך ע\"י התורה דבאור פניך נתת לנו תורת חיים כו' דאורייתא מחכ' נפקת שמאיר שם האור העצמי כו'. ובאד\"ר דקל\"ג ע\"ב אי' באור פני מלך חיים הן תרין תפוחין שזהו תיקון הז' שנק' הארת פנים וכמ\"ש בלקו\"ת בהביאור דאלה מסעי, והוא בחי' פנימיות החכ' דחכמת אדם תאיר פניו כו'. ושם באד\"ר דמ\"ש יאר ה' פניו אליך הוא כשמאיר בז\"א כו'). וביותר ענין הקירוב הוא שקרובים בדעתם זל\"ז, וי\"ל שזהו מה שהאוא\"ס דלית מח' תפיסא בי' מאיר בבחי' החכ' שז\"ע בחי' הראי' דחכ' שהיא הראי' בעצם ומהות הדבר כו', וז\"ע מעלה ומטה בחו\"ב. וכמו\"כ במוחין ומדות בכלל ענין המעלה ומטה הוא בריבוי האור שבמוחין מאיר ריבוי האור בגילוי שא\"א להאיר כלל במדות כו', ולכן כשהמוחין מאירים בגילוי א\"א להיות מציאות המדות, ורק מהמדרי' התחתונה שבמוחין שזהו בחי' מיעוט האור מתהווים בחי' המדות כו'. וגם המעלה ומטה בעצם מדריגתן"],[3601330226,"דמהות ומדרי' המוחין הוא למע' הרבה מהמדות, דהמוחין הן ענין ידיעת והשגת אלקות והמדות הן רק התפעלות אלקי כו', והמוחין הן בבחי' דביקות דכל השגה היא ע\"י שמתקשר ונדבק בהענין כו', וע\"י ההשגה נעשה בבחי' דביקות והתאחדות עם הדבר המושג כו', משא\"כ המדות דעיקרן הוא התפעלות הרי כל התפעלות הוא חוץ לעצם כו', והגם שע\"י שמתפעל על הדבר ה\"ה נעשה בבחי' קירוב (דאהבה היא בחי' קירוב כו'), אין זה בבחי' קירוב ממש כמו המוחין שמתאחד ממש בהדבר כו'. וכנודע ההפרש בין חיוהי לגרמוהי דעם היותם שניהם חד, הנה היחוד דחיוהי הוא כמו דבר אחד ממש, והיחוד דגרמוהי הוא כמו שני דברים המתייחדים כו'. וכן הוא ההפרש בין מוחין למדות דהקירוב דמוחין הוא בבחי' דביקות ממש והקירוב דמדות אינו בבחי' קירוב ממש כו'. וכ\"ה למע' הגם דכתיב לך ה' הגדולה כו' שהמדות הן בבחי' יחוד כו', מ\"מ אינם בבחי' יחוד ממש כמו המוחין וכידוע שנק' חיוהי וגרמוהי כו'. וגם המוחין הן לעצמן דגם בלי זולת שייכים ענין המוחין, משא\"כ המדות שייכים אל הזולת דוקא, דכמו\"כ הוא למע'\nדכתי' זכור רחמיך וחסדיך כי מעולם המה שהן לצורך העולמות כו', משא\"כ המוחין אינם שייכים לעולמות שגם אם לא היו עולמות הי' ג\"כ בחי' המוחין כו' (ובסמוך ית' דמ\"מ הן לצורך ההשתל' כו'). והיינו שמוחין ומדות הן בבחי' מעלה ומטה הן בבחי' ריבוי ומיעוט האור והן בעצם מהותם ומדריגתן כו', וכן כל הע\"ס הן בבחי' התחלקות דמעלה ומטה עד בחי' המל' סודכ\"ד דאצי' שהיא מבחי' המטה, הן בבחי' האור והגילוי דסיהרא לית לה מגרמי' כלום כו', והן בעצם מהותה ומדריגתה דכללות ענין המלוכה הוא על הזולת דהתנשאות הוא על הזולת דוקא, והיינו דכל ענין המלוכה הוא בבחי' חוץ לעצמו כו' וכמ\"ש במ\"א. וזהו דהע\"ס כולם הם בבחי' התחלקות דמעומ\"ט כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו דבחכ' מאיר אוא\"ס בקירוב דהיינו ריבוי האור, ועצם האור (והו\"ע ההנחה) וכמו בראיית פני המשפיע שמקבל בזה עצם השכלי, ועוד זאת ענין הקירוב דחכ' משתווה אל האוא\"ס והיינו בחי' מהות אוא\"ס המאיר בבחי' ראי' דחכ' (ועמ\"ש בדרוש וככה רל\"ז בענין בחי' מ\"ה דחכ' כו'), וכן המוחין הן בחי' מעלה בעצם מדריגתן לגבי מדות שהן השגה ודביקות ומדות התפעלות שחוץ לעצם, והגם שהן בבחי' יחוד, ה\"ז ע\"ד חיוהי וגרמוהי, ומל' היא בחי' מטה בהגילוי ובעצם מדריגתה.</span>\nמד) <b>ובזהר</b> פ' פנחס דרנ\"ז ע\"ב אי' דכל ספי' אית לה שם ידיעא ומדה וגבול ותחום כו', וי\"ל דמדה הוא המדידה בעצם מהות ומדרי' הספי' שהחכ' היא במהות ומדרי' כזו והבינה במהות ומדרי' אחרת וכה\"ג בכל הספי' מה שמחולקים בעצם מדריגתן ז\"ע מדה כו'. וכ\"נ מפי' הרמב\"ן על הס\"י פ\"א מ\"ה מדתן עשר שאין להם סוף דכ' ואע\"פ שהדברים יש להם שיעור ומדה והן עשר אותה מדה שיש להם אין לה סוף כו', נראה דענין מדה הוא בעצם המהות שבזה הן מתחלקים לעשר כו', הנה כל מדה היא בבחי' א\"ס כו' (והראב\"ד ז\"ל מפרש שם ענין הא\"ס בענין עשר כו'. ונראה שזהו מ\"ש הרמב\"ן ז\"ל אח\"ז כי המוטבע כו'). וענין גבול ותחום אי' בלקו\"ת בהביאור דוירד הגבול שהוא ענין א', וי\"ל דגבול הוא ההגבלה באופן הגילוי אם בריבוי או במיעוט כו', ותחום הוא ההגבלה וההפסק"]]});
